/* 平成24年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h24.committeeSessions.push(...[{"id":"h24-20120312-3","meetingId":"h24-c-budget","date":"2012年3月12日","dateIso":"2012-03-12","committee":"予算特別委員会","time":"午前１０時００分～午後５時１９分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を158件整理しています。","topics":[{"id":"topic-01","title":"平成２４年度品川区一般会計予算","agenda":"平成２４年度品川区一般会計予算","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"２７９ページの清掃費の収集運搬作業費、それから、２８５ページの商店街活性化事業費の共同装飾灯維持管理補助についてお伺いします。その中で今後さらにごみの減量をしていく必要があると思うんですけれども、区としてのお考えを説明するよう求めました。","respondent":"太田品川区清掃事務所長","answer":"これからのごみの減量、サーマルリサイクルの実施に伴って、少なくとも５０年以上は使えるようなということも東京都で試算を出してきてあります。１つは、これまでも実施してきてありますけれども、さらに区民の方への普及啓発、これを強力に進めていく必要がある。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"その辺の改めて区としての今後のお考えをお聞かせいただきたい。今も聞きましたけれども、もう一度改めて、その有料化について進めていく必要があると思いますけれども、その辺をお願いいたします。","respondent":"太田品川区清掃事務所長","answer":"今まで区として実施しています普及啓発ですとか、そういった施策の１つとして、減量施策の１つとしてごみ有料化が有効に活用できるだろうです。今後減量化施策の１つとして、ごみの有料化、これは検討していかなければいけないかなと思ってあります。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"次に、商店街活性化事業の共同装飾灯維持管理補助についてお伺いします。商店街、区としてどのように把握されているのか、説明を求めました。","respondent":"米田商業・観光課長","answer":"その本数等に応じて計算をしまして、電気代、あるいは簡易維持補修の補助をしています。算定基準を増額してございまして、それなりに商店街の装飾灯の維持管理にご支援ができているのではないかと、このように考えているところです。","id":"exchange-003"},{"speaker":"沢田委員","kind":"意見","question":"そういった場合、今度町会のほうでは、今いただいている装飾灯の補助金というのが今のその制度ではないということもあります。この３つの場合について、いろいろほかに制度が必要なのかなと思うところもあるんですけれども、その点のお考えについて説明を求めました。","respondent":"米田商業・観光課長","answer":"いわゆる撤去ということでの補助ということもできるかと思いますが、ご質問のように、なかなかそうはいかないという場面もあろうかと思います。さまざまな対応、一つ一つについてご相談に応じてまいりたいと、このように考えております。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"本当に今後、こういった商店街というのは増えてくるかなと思うんです。ぜひ残していっていただきたいし、現行の補助制度でどうにか運用できるのか、その辺をぜひとも防犯上からも進めていってもらいたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"鶴委員","kind":"質問・要望","question":"２５３ページ、区施設等へのＡＥＤの設置経費とありますけれども、その金額の内訳を教えてほしいと求めました。民間施設などの設置してある場所を追加していくということの理解でよろしいかどうか、ＡＥＤの貸し出しは何台か、このあたりを説明するよう求めました。","respondent":"小川健康課長","answer":"新たに民間の施設におきましても、民間の施設のＡＥＤの状況も設置一覧ということで追加をするという予定になってあります。ＡＥＤのリースの代金ですが、新たなリースと、それから、耐用年数が切れたことに伴うリースと含めまして、全体で１７４万円です。","id":"exchange-006"},{"speaker":"鶴委員","kind":"質問・要望","question":"それで、民間施設についてはこれから確認の後、随時ということで確認できました。その辺のお考えはどうかというところと、いわゆる２４時間利用可能な設置状況になっているところがあるのか、この辺を説明するよう求めました。","respondent":"小川健康課長","answer":"貸し出しに関するご質問ですが、まずは５台ということで始めさせていただきたいと考えています。それから、現在の区有施設で２４時間稼働が可能という施設は今のところございません。","id":"exchange-007"},{"speaker":"鶴委員","kind":"確認","question":"もう一度、今の地域センターを通じてというところで、貸してもらうときというのは、どこに行けばいいのか、そこだけ確認。","respondent":"小川健康課長","answer":"基本的には、最寄りの地域センターを通じまして受け渡しをしたいと考えていますが、もちろん当然地域活動課に直接おっしゃっていただいても構いません。","id":"exchange-008"},{"speaker":"鶴委員","kind":"提案","question":"２４時間で利用可能なところがないということでありましたけれども、コンビニだとかをはじめ、２４時間利用できる環境整備の提案をしてきております。","respondent":"小川健康課長、川崎生活安全担当課長","answer":"今回、民間の施設に区のホームページに載せていいかということを確認すると同時に、営業の時間帯もあわせて確認をさせていただこうと考えています。それから、その場所にステッカーを張っていただくというようなことも考えてありますの… うちの車は軽車両を使っておりますので、ちょっとスペース的なものもありまして、載せることについては検討しておりません。","id":"exchange-009"},{"speaker":"鶴委員","kind":"提案","question":"巡回できるというのは非常にメリットかなと思いましたので、提案まで申し上げました。それから、今現在区で実施しているＡＥＤ研修ですね、これはどういったものがあるか、この辺を説明するよう求めました。","respondent":"小川健康課長","answer":"現在区の研修としましては、年に２回ほど普通救命講習会ということで研修のほうが中心に実施をしています。場所は消防署を会場にして、各回３０名定員ということで実施をしています。","id":"exchange-010"},{"speaker":"鶴委員","kind":"提案","question":"胆道閉鎖症の早期発見のための便の色見本についてお尋ねしたいと思いますが、その答弁の中で、非常に工夫されているなというふうには思います。その辺の確認と、どういう形で配布していくのか、この辺を説明するよう求めました。","respondent":"小川健康課長","answer":"こちらにつきましては、２月から始めたばかりということで、まだそのタイミングが合わなかった方がいらっしゃるかと思ってあります。基本的には広報しながわの４月１１日号にそういった便の色見本をお配りしていますということでご案内をすることが決まってあります。","id":"exchange-011"},{"speaker":"鶴委員","kind":"質問・要望","question":"早めに手を打っていただいて、両保健センターということですかね、それぞれの。３保健センターに設置とありましたけれども、そうした工夫ができるかどうか、このあたりを教えていただければ。","respondent":"小川健康課長","answer":"基本的には、窓口での対応というふうに考えてあります。そちらに参加する方についても、こちらから積極的にご案内をして、お渡しするような形をとりたいと考えています。","id":"exchange-012"},{"speaker":"大倉委員","kind":"質問・要望","question":"２５９ページ、地域猫で、猫の不妊と去勢手術費助成について少しお伺いさせてほしいと求めました。何ていうんですか、猫たちどうにかしてくださいという声が品川区にどのくらい入っているのか、わかれば教えてほしいと求めました。","respondent":"稲田道路公園課長","answer":"猫は嫌がってとか、隅に隠れていくというところなんでしょうけれども、公園のほうではそんな実績はございません。それはその時々であるというところで、はっきりした件数はないんですけれども、ほとんどが交通事故での死亡だというところです。","id":"exchange-013"},{"speaker":"大倉委員","kind":"質問・要望","question":"申しわけない。犬の増加、減少傾向がわかれば、教えてほしいと求めました。","respondent":"工藤生活衛生課長","answer":"平成１６年度、８,３００頭ぐらいですので、近年のペットを飼われる方が増えているという状況になってあります。猫に関しましては、登録制度等はございませんけれども、おおむね１０世帯に１世帯ぐらいが飼われているという報告が出ているところです。","id":"exchange-014"},{"speaker":"大倉委員","kind":"質問","question":"品川区としてご相談があった場合、どういった対応をされているのか、教えてほしいと求めました。","respondent":"太田品川区清掃事務所長","answer":"猫だけに限らず、犬等の動物の死体処理という形で、飼い主等からの依頼を受けた場合に、私どもで有料で引き取りをして、動物霊園といいますか、焼却場へ、民間のところで処理をしていると、こういう状況です。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問・要望","question":"民間のほうにお願いをして焼却をしていただくということで、この件数とかがわかれば教えていただきたいのと、必ず焼却施設に行くのか。ないんだったらないで結構です。","respondent":"太田品川区清掃事務所長","answer":"３年ぐらいということであれば、平成２０年度で２７８件、平成２１年度で２５９件、平成２２年度で２９６件と、こういう流れで推移してきてあります。それから、これは民間の焼却施設で処理をし、そこで共通のといいますか、埋めて、弔うという形になっております。","id":"exchange-016"},{"speaker":"大倉委員","kind":"質問","question":"私が聞いたところだと１件あるということなんですけれども、焼却し、やっているのかなという思いなんですが。例えばどこの民間に頼んでいるというのがわかれば、品川区の業者なのか、それとも区外の業者なのか、ちょっと教えてほしいと求めました。","respondent":"太田品川区清掃事務所長","answer":"多摩地区にあります仏教平和会というところで処理をしています。","id":"exchange-017"},{"speaker":"大倉委員","kind":"質問","question":"品川区にも、今ちょっと言いましたけれども、ペット霊園があるんですが、ペット霊園の区の考え方についてお伺いしたいと思います。火葬すると、煙が上がったりされるのかなという思いがあるんですが、区のペット霊園の考え方を教えてほしいと求めました。","respondent":"野呂瀬環境課長","answer":"先ほど言いました品川区内のペット霊園というのは、南品川に１軒ありまして、これは城南ペット霊園です。ダイオキシンとか酸化物とかばいじんといった、廃棄物焼却炉には当たらないと、こういうことです。","id":"exchange-018"},{"speaker":"大倉委員","kind":"質問・要望","question":"お寺でやられているということなので、敷地内で、余りご迷惑ないようにやられているんだなということだとわかりました。自宅に来ていただいて、そういったものとかというのは区のほうでどうお考えになっているか、教えてほしいと求めました。","respondent":"工藤生活衛生課長","answer":"新しいビジネスといいますか、ペットを扱う移動火葬車という部分のビジネスというものはあります。いわゆるインターネット等で調べましたところ、品川区のほうでも３件ぐらい、そのような会社があるというふうに把握しています。","id":"exchange-019"},{"speaker":"大倉委員","kind":"質問","question":"どういったやり方をされているというのは、各７０の自治体で、そういったやり方をされているところがあると伺っております。載っている料金以上の請求をして、払わない場合にはそのままもう遺骨は返さないよと、そういったことがあるというのを伺っております。","respondent":"工藤生活衛生課長","answer":"移動火葬車につきましては、ちょっと私どもも、状況というんですか、自治体のほうで取り組んでいる状況等は今把握していない状況です。私どもも、やはりそのような法律、その他の動き等を十分に注視してまいりたいと考えています。","id":"exchange-020"},{"speaker":"大倉委員","kind":"質問","question":"ぜひこういった都の墓地法というんですか、火葬に関する人間のほうも区に権利が下がってきたというか、移ってきたので。２６７ページの健康相談事業のぜん息健康教室についてちょっとお伺いしたいんですが、アクアマリンとか、できないのか。","respondent":"小川健康課長","answer":"こちらのぜん息健康教室ですが、プールだけではございませんで、水泳のほかにも、声楽を用いた機能訓練ですとか、さまざまなことをしています。新しいところでは、ぜん息健康教室につきましては、荏原平塚学園を会場として考えているところです。","id":"exchange-021"},{"speaker":"鈴木（博）委員","kind":"質問","question":"２６１ページの母子保健指導事業費のすくすく赤ちゃん訪問事業等、２５５ページの予防接種費の定期予防接種についてお伺いしたいと思います。わかりやすい説明とパンフレットは、これは訪問指導のときに必須のアイテムと考えますが、いかがか尋ねました。","respondent":"矢野品川保健センター所長","answer":"そこで、ことしは契約更新時に予防接種の講習会を開く予定にしております。訪問時に配る中に、その中に予防接種の予定が入っておりまして、それを用いて現在はお話をしていただくというような形になっております。","id":"exchange-022"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次に２５５ページの予防接種の定期予防接種のほうについてお伺いします。ＢＣＧは４カ月健診時に集団接種が行われておりますが、それぞれ平成２２年度と平成２３年度の予防接種の実績と接種人数についてお伺いいたします。","respondent":"伊津野保健予防課長","answer":"ＢＣＧですが、平成２２年度は２,９６３名受けております。接種者が合計で２,９７８名、接種率としては平成２２年度は１００％近い接種率となっております。","id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今現在、どうも今の状況だと、今週の集団接種で中止になる情勢であります。ＤＰＴの途中の人が４種に切りかえた場合、品川区としては今どのような対策を検討されているのか、その対策に関してちょっとお聞きしたいと思います。","respondent":"伊津野保健予防課長","answer":"委員ご指摘のポリオワクチンの不活化への切りかえですが、それについては大変苦慮しているところであります。国のほうでも、今まさに検討しているところでありますので、区としてもその動きを見守って対応していくことしかできないかなと考えております。","id":"exchange-024"},{"speaker":"鈴木（博）委員","kind":"質問","question":"次にＢＣＧについて、ＢＣＧの接種時期についてお伺いします。今現在４カ月で集団接種で行っているわけですが、現在保健センターで行われている４カ月健診時のＢＣＧプラス、ちょっと簡単にご説明お願いします。","respondent":"伊津野保健予防課長","answer":"ＢＣＧは法定で決められておりますので、接種時期を変えることは難しいと思います。個別化のほうも検討していきたいと考えています。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めて、健康診断を受ける機会がない若者への健康診断の実施を品川区に求めたいと思いますけれども、いかがでしょうか。２０代の方のお話を伺っても、状況が私は一段と深刻になっていると実感するんですけれども、この点についても区の認識を伺いたいと思います。","respondent":"小川健康課長","answer":"それに伴いまして、健康課では、４０歳以上の区民で、医療保険未加入者を対象に品川区健康診査を実施しているものです。区としての若者支援ですが、基本的には、保健センターのほうで若者に対する健康のケアはしているというふうに認識しています。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"この状態が私は増えていると思うんですけれども、その実態についてどうお考えなのか、改めて伺いたい。率直にご意見を伺いたいと思います。","respondent":"小川健康課長","answer":"区といたしましても、現行の健康診査の枠組みの中で今後もしっかり実施していきたいと考えています。職場での健診につきましては、労働安全衛生法に基づきまして、雇用主の責務として実施しているものです。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいのは、若い世代で失業者となった場合、健康診断を受けるにはどうしたらよいのか、現状の制度をご説明ほしいと求めました。こうした若い世代の失業者、また、失業状態にある方が健康診断を受けるには現状どういった仕組みがあるのか、伺いたいと思います。","respondent":"小川健康課長","answer":"先ほども申し上げましたが、現在の健診の考え方は、いわゆる生活習慣病予防対策ということで、４０歳以上を想定しているものです。失業者、例えばぐあいが悪くなったというような方につきましては、直ちに医療のほうに結びつけるということが一番適切かなと考えているところです。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"２０代にその受ける機会がない人を、一体どう考えていらっしゃるのか。そこを改めて伺いたいと思います。","respondent":"小川健康課長","answer":"現在若者への健康ケアの考え方ですが、先ほども申し上げましたけれども、保健センターを中心に相談体制を整えているです。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"まあ、内容が特定健診なら、特定健診の中身と同様の健診が受けられるのかどうか、そこを伺いたいと思います。だれもが、どの年代も、年に１回健康診断を受けることができる、それをしっかりと行うべきだと思うんですけれども、改めて伺いたいと思います。","respondent":"小川健康課長","answer":"保健センターでの相談体制ですが、基本的に国保の特定健診と同じような健診を受けられるわけではございませんが、現行の相談体制、もちろん若者だけに限らず、全世代向けの健康相談の体制を整えているです。","id":"exchange-030"},{"speaker":"中塚委員","kind":"確認","question":"何らかの改善、支援が必要だと思いますけれども、いかがでしょうか。年に１回の健康診断、私はそういう思いも持っているんですけれども、あわせていかがか尋ねました。","respondent":"小川健康課長、福島荏原保健センター所長","answer":"保健センターでは、ご指摘のとおり、健康相談という形で、健康診査というものは行ってございません。品川区の自殺者自体は、確かに３０代、４０代、５０代の働き盛りの人の自殺者が多いということはここ４年間のデータでもわかっております。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"そこをしっかりと改善すべきだと思うんですけれども、いかがでしょうか。いかがか尋ねました。","respondent":"木下健康福祉事業部長","answer":"いわゆる生活習慣病のリスクが高くなります４０歳以降について重点的に実施するということと、そういう機会にしてもらおうと、実施しているものです。そのことを今ゲートキーパーを養成するという形で進めておりますので、相談、その辺については対応をしていきたいです。","id":"exchange-032"},{"speaker":"中塚委員","kind":"提案","question":"私が１つ提案したいのは、保健師や心理士、この配置をぜひ進めていただきたい。そして適切な支援へと結びつけていただきたいと思うんですけれども、このセンターに保健師や心理士の配置を求めますが、いかがか尋ねました。","respondent":"福島ものづくり・経営支援課長、小川健康課長","answer":"品川区就業センターは、あくまでも就業支援という形で進めてまいりますので、保健師等の配置は予定してございません。 品川区といたしましては、高齢者の医療の確保に関する法律ならびに健康増進法にのっとった形で現在適正に健康診査を実施しておりますので、それを今後もしっかりと実施してまいりたいと考えています。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"それを就労だからといって、全く切り離すというのは、実態に即した対応とは思えないんですけれども、改めて設置を求めたいと思います。そして、若い世代の健康診断の実施を強く求めたいと思いますが、いかがか尋ねました。","respondent":"福島ものづくり・経営支援課長、小川健康課長","answer":"答えは一緒になりますけれども、品川区就業センターはあくまでも就業支援のための施設ですので、そのようなことが必要な方につきましては、例えば保健所ですとか、そういうところに勧めていきたいと考えています。 区独自で若者に対する健康診査を実施するという考えはございません。","id":"exchange-034"},{"speaker":"渡辺委員","kind":"質問","question":"私は２５７ページ、各種がん検診、２８７ページ、地域交流支援事業助成について伺いたいと思います。予算書で記載されている７つですか、８つ、それぞれ説明を求めました。","respondent":"小川健康課長","answer":"トータルという考え方での統計のとり方はしてございませんので、申しわけございません。現在実施していますが、毎年実施をしているところではありますが、現況としてはそういったところです。","id":"exchange-035"},{"speaker":"渡辺委員","kind":"質問","question":"今特に低い率という中で、３％台というので、すごく驚きというか、すごい厳しい現実を見た気がします。それに対する現在の対応の状況、対応策、ここ近々の数年で構いませんので、どんな対応を現在行われているか、説明を求めました。","respondent":"小川健康課長","answer":"受診率が伸び悩んでいる背景ですが、区といたしましては啓発に努めているところです。それに合わせて２０％を超えるという受診率になって、ある程度成果が少しずつ見えてきたという、その途上にあると考えています。","id":"exchange-036"},{"speaker":"渡辺委員","kind":"質問","question":"これは多分今のお答えで、意識の問題、区民の方の意識が、それぞれ関心がないわけではないまでも、すごく、何でしょうか、危機感というか。そんなようなケースが多いように思われますが、品川区という中でどのように考えられているか、説明するよう求めました。","respondent":"小川健康課長","answer":"健康大学しながわにおいて、がんをテーマに公開講座を実施するですとか、そういった中での工夫は区としても現状しています。そういった課題もありますが、どういった形でするのが一番いいのかということについて、今後検討してまいりたいと考えています。","id":"exchange-037"},{"speaker":"渡辺委員","kind":"質問","question":"商店街の考え方の中で１つ伺いたいのが、線で例えるならば、１本の線になります。あまり該当するようなものを見かけなかったんですが、結構品川のオリジナルであるのかどうか、伺えればと思います。","respondent":"小川健康課長、米田商業・観光課長","answer":"１点目のがん検診受診率アップのための民間企業の活用につきましては、その可能性も含め、どういった形が好ましいのかということを検討してまいりたいと考えています。地域交流支援事業ですが、平成１７年度より実施しておりまして、商店街活動を幅広く支援するというものです。","id":"exchange-038"},{"speaker":"渡辺委員","kind":"質問・要望","question":"おもしろいことをやっているねというのをよく聞いたものですから、品川区の先進的な取り組みというお触れがあってもいいのかなと思いました。あるいは、需要や要望は、その裏にはもっとあるのかどうかで、どのように把握されているのか、説明を求めました。","respondent":"米田商業・観光課長","answer":"そういった意味では、それ以前からこういう地域での商店街の支援というようなことについては、それなりの需要があったものと考えています。関係団体等と話し合いを進めていきながら、検討してまいりたいと、このように考えてあります。","id":"exchange-039"},{"speaker":"渡辺委員","kind":"質問・要望","question":"役員レベル、あるいは関心のある方は知っていても、知らないというケースを何件か聞いたものですから。制度に対して要望を待つのも１つですが、いろいろな用途もこれからぜひご検討いただければと思って、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"塚本委員","kind":"質問・要望","question":"今まで私が述べたことに関しての事業として何か予定をされていることがあるかということを１点お聞きしたいのと、あと、運営するというんですかね。なぜ事業を継続できなかったのか、この辺につきましての原因というか、承知しているところ、この辺を教えてほしいと求めました。","respondent":"米田商業・観光課長","answer":"どうしたら商店街の利用が増えると思いますかというような問いかけの答えの中の１つに、ある種、取り組みたい。マイスター店等支援事業の中におきまして、いわゆるこれから商店街として取り組んでいくものの中のモデル実施というようなことで、何かしら今年度。","id":"exchange-041"},{"speaker":"塚本委員","kind":"質問・要望","question":"ぜひこれは何とか活路を見出していただきたいと思うんですが、まさに商売のネタがあるということで、早速いろいろ乗り出してきているかと思います。その辺の大手と商店街における宅配の今の状況、どのように認識されているか、お聞かせほしいと求めました。","respondent":"米田商業・観光課長","answer":"画一的な対応になろうかと思いますが、その辺がいわゆる商店街としての差別化、優位性が保てる１つの要因かと思ってあります。商店街連合会、その他商店街とも意見交換を図りながら、これらの取り組みが進められないかということを考えていきたいと思ってあります。","id":"exchange-042"},{"speaker":"塚本委員","kind":"質問・要望","question":"いわゆるすみ分けですかね、１つの進め方としてありだと思いますので、しっかりやってほしいと求めました。そんな中で、ことし、東京都の補助金になるんでしょうか、商店街の活性化支援というものの中で、今まで新・元気出せ！","respondent":"米田商業・観光課長","answer":"これにできればうまく乗れるような形での構築を考えてまいりたいと思いますが、時間との戦いということもあります。東京都のいわゆる募集の仕組み、時期等をまた研究しながら、こちらに乗れるような形での検討を進めてまいりたいと、こう考えてあります。","id":"exchange-043"},{"speaker":"塚本委員","kind":"質問・要望","question":"続きまして、商店街と大型店等の連携・協働支援事業についてお伺いをしたいんですが、ことし２００万円の予算が現状ついております。今主婦層を中心に大変に浸透している、これについて何かしらこの事業の中でかかわるものがあるか、お伺いしたいと思います。","respondent":"米田商業・観光課長","answer":"大型店との連携事業ということで、それから、ふだんとは違うエリアでの販売によってその商店の認知度を高めていただくというものです。ご指摘のありましたようなポイントということについては、現時点ではできていないというようなことでご理解いただければと思います。","id":"exchange-044"},{"speaker":"塚本委員","kind":"質問・要望","question":"１つ、より顧客を獲得していくような仕組みというのは、もしかしたら何かあるんじゃないかなと思っているんですね。その点、どのようにお考えをお持ちなのか、お聞かせほしいと求めました。","respondent":"米田商業・観光課長","answer":"ポイントについても、例えば消費者の方からはある程度ポイントがあると買物の動機づけになるというようなことは聞いてはあります。商業者のほうは、いわゆるアンケートの調査からも出ておりますので、その辺のところは今後の研究課題とさせていただければと思ってあります。","id":"exchange-045"},{"speaker":"木村委員","kind":"質問","question":"２６３ページの健康塾から質問です。７,５２４万円から大きく本年度は減って、約６,０００万円強減っているわけですけれども、もう一度お願いをいたします。","respondent":"小川健康課長","answer":"健康塾ですが、健康塾につきましては、品川区トリム体操連盟に委託しています。もともとございましたふれあい健康塾ならびにしながわ出会いの湯が一般会計から介護保険特別会計に移ったことによる減です。","id":"exchange-046"},{"speaker":"木村委員","kind":"質問","question":"そして、何と最高齢が９７歳ということで、ちょっと驚きましたけれども、今までで健康にかかわる事故などはあったでしょうか。そして、年齢は幾つからこういうものに参加ができるのか、答えるよう求めました。","respondent":"小川健康課長","answer":"１カ所、週１回なんですけれども、２コースずつ実施しているものです。ただ、健康塾に行くまでの間に、足が滑ったというような、そういったことはありますけれども、教室そのものでの事故等はございません。","id":"exchange-047"},{"speaker":"木村委員","kind":"意見","question":"参加するのに抽選会が行われるほど人気があるのであれば、もっともっとメニューを増やすようなお考えはあるのかどうか。そして、その多くの参加者があると聞きますけれども、会場はどこで行っているのか、お答えくださいとの意見を述べました。","respondent":"小川健康課長","answer":"そうでもございませんで、地区によってやはり多少の波がありますので、基本的にはこの状態で今後も実施してまいりたいと考えています。総合体育館を中心に春、また秋には戸越体育館を中心に年２回大きなイベントをトリム体操連盟と共催をして実施しているものです。","id":"exchange-048"},{"speaker":"木村委員","kind":"質問","question":"ＡとＢがあるということですけれども、Ａが１万６,８００円、そしてＢが８,４００円とお聞きしました。これとの差はどうして生じたのか、説明を求めました。","respondent":"小川健康課長","answer":"１カ月で１万６,８００円、Ａコースについては、最初から支度準備等を含めての準備経費代も含めてＡコースのほうが高くなっております。健康塾につきましては、６５５万２,０００円ほど委託料としてお支払いしているものです。","id":"exchange-049"},{"speaker":"木村委員","kind":"意見","question":"１コースの参加人数、そして健康体操２２カ所の会員の総数、年々これが増えているのかどうか。毎週楽しみになった等のことで、お年寄りたちの変化のデータを健康課は把握をしているかどうか、お答えくださいとの意見を述べました。","respondent":"小川健康課長","answer":"参加者の推移ですが、年々若干増している状況です。システム的にデータとしてきちんと把握をしているというものではなく、実際に対面でお話を伺って、把握をしているという状況です。","id":"exchange-050"},{"speaker":"木村委員","kind":"質問","question":"もう一つ、その下にあります中高年運動指導者育成セミナーなんですけれども、これはたかが１９万５,０００円です。１２年もやっているわけですから、毎年度ではなく２年に１回にしたらどうかと思っていますけれども、簡単に、答えるよう求めました。","respondent":"小川健康課長","answer":"こちらにつきましても、トリム体操連盟と共催してございまして、卒後にトリム体操連盟に加入される方が多いと聞いてあります。それなりに成果のある事業と考えていますので、引き続きこのように実施してまいりたいと考えています。","id":"exchange-051"},{"speaker":"藤原委員","kind":"質問・要望","question":"そして、その結果がこの平成２４年度予算にどう生かされているか、教えてください。その理由について教えていただきたいのと、１つ確認は、その辺の確認したいと求めました。","respondent":"工藤生活衛生課長、福島ものづくり・経営支援課長、米田商業・観光課長","answer":"そういった意味では、いわゆる区民の安心・安全を守り続ける重要な役割を担っていると認識しております。耐震工事費約１億８,０００万円ですけれども… 融資制度、特に信用保証協会についてご説明します。２２人を対象とした創業支援塾というものを開いたんですけれども… 区内の消費者、商業者を対象にこの間、グループインタビューと先ほど申し上げましたアンケート調査を実施いたしました。","id":"exchange-052"},{"speaker":"藤原委員","kind":"質問・要望","question":"その辺がどうでしょうかということが１点と、都民は国民であるわけですから、その辺についてはいかがでしょうか。品川区は心広いと思うんですけれども、品川区の税金でやっているわけですから、その辺についてはいかがか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"ただ一方で、事業の継続等が行われていますので、そういったプラスの面も見ていきたいと思います。起業につきましては、品川区内で創業するよう誘導していきたいと考えています。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２点目は、一般区民に向けての健康センターなどで持ち込んだ場合の測定ができるような仕組みをつくっていただきたいんですが、いかがでしょうか。区内の計測を継続的に行っていただきたいことと、地表の１メートルだけじゃなくて、地表５センチの数値の公表も求めますが、いかがか尋ねました。","respondent":"野呂瀬環境課長、工藤生活衛生課長","answer":"確かに０.２３マイクロシーベルト以上、そこの１センチのところではありましたけれども、心配ないんですよということで測定を終わったところです。そういうことで、５センチについて… 出荷流通をとめて、出荷制限という部分がされておりますので、市場には出回ってないというふうに思ってあります。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ台数を増やして、貸し出しも３月３０日で終わるのではなく、ぜひ延長していただきたいんですが、いかがでしょうか。いかがか尋ねました。","respondent":"野呂瀬環境課長、工藤生活衛生課長","answer":"今後も継続的に、高い値であったようでお不満であれば、環境課から測りに行きます。それから、地域センターでも毎日測っておりますので、それにつきましては、表示については、調整します。 ２月には、放射能に関する講演会という部分で、正確な情報等をお伝えしたところです。信頼できるサイト、例えば消費者庁のホームページ等にリンクするなどしまして、そのような啓発を図っていきたいと考えています。","id":"exchange-055"},{"speaker":"山内委員","kind":"質問","question":"私のほうから、衛生費のところで、花粉について伺います。それから、そういった的確な指示をしっかりと出しているかどうかということを伺います。","respondent":"野呂瀬環境課長","answer":"花粉についての放射線のお問い合わせは、今、環境課には来ておりません。","id":"exchange-056"},{"speaker":"山内委員","kind":"質問・要望","question":"体に被害はないということをしっかりと周知をしていただきたいなと、これは要望をします。２８５ページの中小企業ＩＴ化推進事業、それから、２８９ページのものづくり活性化事業費の海外進出のあたりをお伺いをします。","respondent":"福島ものづくり・経営支援課長","answer":"こちらの被災者雇用ですけれども、国、ハローワークが行っています同様な事業に対しまして、その２分の１を品川区として補助するというものです。","id":"exchange-057"},{"speaker":"山内委員","kind":"質問","question":"そういった中で、行政と雇用先との連携というものをどうやってとっているのか。それから、この予算でいくと大体どれぐらいの見込みで相談に来られ、それで就職につなげていけるのかという区の意気込みというものを説明するよう求めました。","respondent":"福島ものづくり・経営支援課長","answer":"ただ、実績としましては、ことしにつきましては、今まで３名の方から実際に雇用があったということで、品川区でも助成をする予定です。さらに問い合わせも何件か来ていますので、年度末までにはもう数件増えるのではないかというふうに予想しています。","id":"exchange-058"},{"speaker":"山内委員","kind":"質問","question":"３名の方が雇用をされたということですよね。まあ、ちょっとわからないんですけれども、そういったときの何か対応とかというものはされているのかなというのを伺います。","respondent":"福島ものづくり・経営支援課長","answer":"サポしながわで、被災者の方が来まして、どこか就職先をという形で相談はございました。それにつきましては、親身になり丁寧に対応しています。","id":"exchange-059"},{"speaker":"山内委員","kind":"意見","question":"平成２２年が４４回、平成２３年が４５回、今回は何回になるのかということ。ところが、まだＩＴ化というものの意識がないというか、そのあたりはいかがでしょうとの意見を述べました。","respondent":"福島ものづくり・経営支援課長","answer":"そういった方々のためにこういったＩＴ化推進事業を進めてまいりました。イラストレーターという、チラシを自分でできるようにということで、そういったものも取り組んでいきたいと考えています。","id":"exchange-060"},{"speaker":"山内委員","kind":"質問","question":"過去にこの事業を経験したというような企業が、また新たにリピーターとしてそういったことをされる、先ほど申し上げたように、技術というものが日進月歩なので、そういった企業というものが結構あるのかどうかということを伺いたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"企業によりましては、複数の人間をこちらに受講させているということで、リピーターはあります。","id":"exchange-061"},{"speaker":"山内委員","kind":"質問","question":"平成２１年からスタートして３回目ですか、１１月にメタレックスですか、そちらに行かれたということであります。そこら辺を伺います。","respondent":"福島ものづくり・経営支援課長","answer":"３年間続けまして、来年につきましては、ことしと同じような形で行っていく予定です。さらにその先につきましては、そういった国に対してどうするのか、その辺のところはさまざまな視点を持って検討してみたいとは思ってあります。","id":"exchange-062"},{"speaker":"山内委員","kind":"質問・要望","question":"そういう要望もあるということ。それからビジネスにつなげていけるような、そういった手だてがとれるのか、そのあたりを伺いたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"週に１日ではありますけれども、国際化対応専門相談員というのを配置しておりまして、支援を行っているところです。私どもとしまして、国際化対応推進ということで、さまざまな東南アジアへの取引について支援していきたいというふうには考えてあります。","id":"exchange-063"},{"speaker":"山内委員","kind":"質問","question":"なかなかこれが減らないのが現状なのかなと考えていますので、そのあたりを伺いたいなと思います。消費者センター内の１階で展示を行っているというんですけれども、年間を通じてどれぐらいなのか、説明を求めました。","respondent":"米田商業・観光課長","answer":"件数的には余り変わっておりませんが、委員おっしゃいましたように、複雑な案件が増えておりまして、１件当たりに要する時間は非常に増えております。それから、１階の啓発展示室につきましては、消費者団体のほうが適宜使っているというようなことになってあります。","id":"exchange-064"},{"speaker":"金野委員","kind":"質問","question":"私のほうからは、２５９ページの環境衛生費、アレルギー等居住環境調査、２つ目に、２６３ページの保健所等管理運営費、この２つをお伺いいたします。これはどのような調査が行われているのか、調査の内容と目的を示すよう求めました。","respondent":"工藤生活衛生課長","answer":"私ども、健康と快適な生活を支える重要な空間だという認識のもと、住まいに起因する健康障害等のトラブルを防止するための支援を行うというものです。","id":"exchange-065"},{"speaker":"金野委員","kind":"質問","question":"それによっていろいろな症状を起こす方のそういう対処の調査をしてくださっているということで、そうすると、その中の１つになるんでしょうか。どのような調査で、どういった対応をされているのか、説明を求めました。","respondent":"工藤生活衛生課長","answer":"化学物質過敏症になりますと、やはり専門機関へ、そういった専門機関に適切につないでいるということで対応しています。いろんなケースがありますので、やはり個々のケースを聞きながら、適切に対応しているです。","id":"exchange-066"},{"speaker":"金野委員","kind":"質問","question":"２点目に、保健所等の管理運営費をお伺いいたします。こちらの管理運営費、まず現状なんですけれども、３保健センターに保健師の方は何人ぐらいずついらっしゃるのか、その内訳をまず説明を求めました。","respondent":"矢野品川保健センター所長","answer":"保健センターの部分ですが、平成２３年４月１日現在の配置状況では、品川保健センターが１２名、大井保健センターが５名、荏原保健センターが１０名です。","id":"exchange-067"},{"speaker":"金野委員","kind":"質問","question":"ものすごい業務が多いんだなというのと同時に、実習生も受け入れていらっしゃるんでしょうかね。その辺の状況を説明するよう求めました。","respondent":"矢野品川保健センター所長","answer":"３保健センターで分担いたしまして、大学によって違うんですが、１週間、２週間というような実習期間がございまして、それぞれのセンターで研修担当保健師というのを毎年決めまして、その者が中心として指導しております。","id":"exchange-068"},{"speaker":"金野委員","kind":"質問","question":"３保健センターでそれぞれで受けていらっしゃるということで、いわゆるこういう実習生を見ての業務が増えるということになるわけですかね。その辺、その業務、実習生を受け入れる業務と保健所の体制というのはどのようにお考えか尋ねました。","respondent":"矢野品川保健センター所長","answer":"それから乳児の部分がトータルで６００人ぐらい増えているということで、なかなか地域を持つ保健師の仕事というのが厳しくなっている現状です。多少困難があっても、人材確保のほかに、人材育成の面についても今後とも努めてまいりたいと考えているところです。","id":"exchange-069"},{"speaker":"金野委員","kind":"質問","question":"人材確保とともに人材育成、大事なことですよね。そして働きやすい環境がより一層その人の向上をされるのではないかなという、そう思うんですけれども、どうか尋ねました。","respondent":"矢野品川保健センター所長","answer":"なかなか保健師というのは大変技術の要る仕事ですが、育成に関しましても、この厳しい状況の中で、工夫して、しっかりと新人を育成してまいりたいと考えています。","id":"exchange-070"},{"speaker":"向委員","kind":"質問","question":"まず２８５ページの中小企業ワークライフバランス支援事業全般と、あと、２５７ページの健康診査費全般でお尋ねしたいと思います。４割ぐらいぐっと減っていると思うんですが、どういう理由で予算がこのように随分変わっているのかなというところをまず説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"中小企業ワークライフバランス支援事業の予算減の要因ですけれども、こちらにつきましては、事業所内育児施設整備補助金です。こちらが、実際に、今年度予定していたよりも少なかったということもございましたので、実績に合わせまして減らしたものです。","id":"exchange-071"},{"speaker":"向委員","kind":"質問","question":"平成２４年度、今度は３００万円ぐらいということで、もともとの予定数としてはどれくらいを考えていらっしゃったのかなと。どうだったのかなと思って、申請数とかが違ったのかなと思うんですが、このあたりはどうか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"こちらの事業につきましては、平成２３年度から初めて行った事業です。平成２３年度につきましては、整備費助成が１００万円の３事業者と予定していたんですけれども、実際の補助金は少なかったというものです。","id":"exchange-072"},{"speaker":"向委員","kind":"質問","question":"シッター代とか、ベビーシッターサービスの助成ということになった経緯とかって、どういうことからベビーシッターサービス。あくまでも単独の事業所が必要だからという、かなり小さな声を反映させるような形になっていると思うんですが、ちょっとこのあたりを説明するよう求めました。","respondent":"福島ものづくり・経営支援課長","answer":"特に中小企業に対してどういうふうにできるのかということを調査検討いたしました。都の検査等がありまして、なかなか中小企業については難しいだろうということでした。","id":"exchange-073"},{"speaker":"向委員","kind":"質問・要望","question":"若者世代の健診についてお話ありましたが、ちょっと私、違う視点でお尋ねしてみたいと思います。なので、そのあたり、ちょっとどういうふうに考えていらっしゃるのか、説明を求めました。","respondent":"小川健康課長","answer":"区独自で若者世代への健康診査というアプローチの仕方は考えてございませんが、区には健康センターという施設が２カ所、荏原と品川にあります。プラスアルファ、また保健センターでも相談体制を整えてありますので、そちらをご利用いただきたいと考えておるところです。","id":"exchange-074"},{"speaker":"渡部委員","kind":"質問","question":"２８９ページのものづくり活性化事業費全般で伺っていきますけれども、平成２３年というのは、成果がすごく上がってきていると思います。特に２つに絞って伺いますが、２８９ページのところの、まず、ものづくり地域企業ネットワーク再生支援。","respondent":"福島ものづくり・経営支援課長","answer":"そのときも好評だったこともありまして、ことしに入りまして、２月にももう１回商談会を実施しました。見込みとしましては２件ほど今年度中には出るだろうと予想しています。","id":"exchange-075"},{"speaker":"渡部委員","kind":"質問・要望","question":"どんどん頑張っていただきたいんですが、この大崎ビジネスクラブのところで１件聞きたかったんですが、コンテストをやっていましたね。２回目の企業に対して進んでいるのかと、この先どういうふうに継続していきそうなのか、あわせて説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"ビジネス創造コンテストですけれども、おととし第１回を行いまして、５０件の応募がございました。その研究会活動から実際の商品化、あるいはビジネス化につながっていけばということで支援しているものです。","id":"exchange-076"},{"speaker":"渡部委員","kind":"質問・要望","question":"そのいろいろなところでさまざまな品川のＰＲとかをしていっています。こんなこと品川でやっているんだというような仕組みに変えていただきたいと思うのが１つと、その２点、お願いします。","respondent":"福島ものづくり・経営支援課長","answer":"その際には、よりわかりやすく、またページが飛びやすいものにというふうに考えてあります。横浜市、この４地域につきましては、今後も連携を持って国際的に進めていきたいというふうに考えてあります。","id":"exchange-077"},{"speaker":"吉田委員","kind":"確認","question":"ユニットの買いかえということをお伺いしたので、ちょっと確認の意味を込めまして、実施回数と年齢を教えてください。そして、この年齢に行う理由を説明するよう求めました。","respondent":"矢野品川保健センター所長","answer":"母子歯科衛生事業に関しましては、３歳未満について保健センターで実施しています。歯科衛生相談の実施回数は、平成２２年度では、３保健センターで合計１２１回、月三、四回実施しているという状況です。","id":"exchange-078"},{"speaker":"吉田委員","kind":"質問","question":"自分たちの住んでいる地元の歯科医院の方ではできないのかなという、ちょっと疑問があるんですけど、その辺をちょっと説明を求めました。","respondent":"矢野品川保健センター所長","answer":"保健センターでは歯科健診としまして、１歳半健診と３歳児健診をしているんですが、その間をとってこの歯科衛生相談を実施しています。３歳未満ですので、やっていただけないようなこともありますので、こちらでも実施しているという状況です。","id":"exchange-079"},{"speaker":"吉田委員","kind":"質問","question":"今お話お聞きしたんですけれども、１６３軒、赤ちゃんのときからお伺いしたらどうかと思います。その辺、もう一度すいません、お願いいたします。","respondent":"矢野品川保健センター所長","answer":"１歳半と３歳半の間に実施しているものですが、これも続けていきたいと考えていますが、地域の医療機関を紹介してまいりたいと考えています。","id":"exchange-080"},{"speaker":"吉田委員","kind":"質問・要望","question":"急いで行きます。環境への思いやりを皆で育てるまちという、この中の私は地球温暖化対策事業についてお伺いしたいんですけれども、ちょっと説明をお願いいたします。","respondent":"野呂瀬環境課長","answer":"環境計画、これは１０年の計画なんですけれども、それが平成１５年に策定したものが計画期間を終えますので、来年度、新たな環境計画として策定していくというものです。","id":"exchange-081"},{"speaker":"吉田委員","kind":"質問","question":"じゃあ、この間一般質問のほうで私挙げさせていただいたんですけれども、前々から品川区では理解していらっしゃるというお答えをいただきました。ちょっとその方向性を聞かせていただいたら、私も明るいなと思うんですけど、。","respondent":"野呂瀬環境課長","answer":"いわゆる森林によって吸収されるＣＯ２がグリーンカーボンに対しまして、まだ国の動向を今後注視していきたいと考えているところです。さまざまなところで周知を図りながら、環境保全に努めていきたいと、こう考えているところです。","id":"exchange-082"},{"speaker":"吉田委員","kind":"質問","question":"明るい将来の世代に引き継いでいけるようによろしくお願いいたします。マイスター店等の支援事業についてちょっとお伺いしたいんですけれども、平成２３年度が１,１８６万円、ちょっとその理由を説明するよう求めました。","respondent":"米田商業・観光課長","answer":"先ほども答弁させていただきましたが、今年度につきましては、商店街のいわゆる実態調査というもので１,０００万円余の予算をかけて行っております。","id":"exchange-083"},{"speaker":"吉田委員","kind":"意見","question":"これからマイスター店にどういうふうに行政はバックアップして、だから、統一化というのはどういうふうにお考えなのかな。広がってばかりいてはどうかなと思うんですけれども、ちょっとその辺はどういうふうな方向性かお教えくださいとの意見を述べました。","respondent":"米田商業・観光課長","answer":"平成１８年度から平成２２年度までの５カ年で、マイスター店の選定を合計で２００店舗行ったものです。この２００店を中心として、事業を展開してまいりたい、このように考えてあります。","id":"exchange-084"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"約６人ぐらいと思っていたんだけれども、今何人あそこで職員が働かれているのか、それをぜひ教えていただきたい。街路樹の維持管理費って、ここの３つの部分と、そういう連携をだれが中心になって品川区の中ではやっているのかというのを教えていただきたい。","respondent":"小川健康課長、太田品川区清掃事務所長、藤田水とみどりの課長","answer":"１点目の水中散歩教室についてお答えいたします。学校利用を中心に、間を縫って区としてもいろいろプログラムの展開を今後も考えてまいりたいと考えていま… それから、そこの作業形態ですけれども、民間に委託をして、６名で運営をしている。直営職員はいません。３名以上の方で１年以上活動される方、こういった方々に登録をいただき、清掃や花植え等を行ってもらっている事業です。","id":"exchange-085"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"漏れ伺うところによると、学校の予定が出てくるのはどうしても１月とか、今回は特に土曜のことがあったから遅かったという話は聞きました。５万円ぐらい出しているだろうけれども、１つになってやっていくことがいいと思うんだけれども、そこら辺の考え方を説明するよう求めました。","respondent":"太田品川区清掃事務所長、小川健康課長、藤田水とみどりの課長","answer":"処理量減少に対応した事業運営を、少しずつですが、そういう活用をしてきてあります。委員ご指摘の点は、重々活用すべき点があろうかと思いますので… いろいろ健康づくりの面から、プールを生かすプログラムについても、これから研究してまいりたいと考えています。東京都、品川区、それぞれでしっかりバックアップしていくことが大切だと考えています。","id":"exchange-086"},{"speaker":"石田（秀）委員","kind":"提案","question":"そこら辺のお考えをもう少し聞きたいなと考えていますので、何かお考えがあれば、ぜひ教えていただきたいなと思います。それに対して、民間活力のもっといろんな頭を使っていただいて、こういうサービスができるんだろうという提案なりプロポーザルを入れ込んでもらうとの意見を述べました。","respondent":"久保田行財政改革担当課長、安藤文化スポーツ振興課長、藤田水とみどりの課長","answer":"東品川清掃作業所につきましては、行財政改革特別委員会等でも何回かご報告をさせていただきましたけれども、なかなか難しい状況にあります。… 学校にまず予定をお伺いしまして、また貸し切り、また健康課で企画します水中散歩等をそれぞれ調整させていただいています。そこら辺とも、スポーツと連携… そういったような、まずは実態をうちとしても把握することが必要だと思ってあります。","id":"exchange-087"},{"speaker":"石田（秀）委員","kind":"提案","question":"最後に１つだけお願いしておきます。そういう形の中で、私はやっぱり提案なり何なりを受ける体制づくりを区のほうにつくっておくべきだと思いますので、それはぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-088"},{"speaker":"稲川委員","kind":"質問・要望","question":"２８３ページ、観光アクションプランに関連してお伺いをいたします。何か沖合クルーズということでやっていることが書いておりますが、ほかにあるのかどうかを説明するよう求めました。","respondent":"山崎マスタープラン担当課長、米田商業・観光課長","answer":"いわゆる我が国経済成長のエンジンとなります産業機能の育成に関する先駆的な取り組みをするということでもって特区が制定されました。まちづくりを考える上で、マスタープランを策定する中におきましても… ７１５万円のうちの１００万円ということで、今年度も、羽田空港国際化対応事業ということで、また、水辺の事業を考えているものです。","id":"exchange-089"},{"speaker":"稲川委員","kind":"質問・要望","question":"ほかのところももし追加指定という、そういう手法があるのであれば、ぜひそういうのにも取り組んでいただきたいと要望しておきます。ですから、Ａから乗船して、東京湾を回りながら、また、乗船所に戻ってくるという不定期航路であります。","respondent":"米田商業・観光課長","answer":"水辺の魅力、日本的な魅力ということで、外国からいらっしゃる方については非常に魅力的に映るというようなことで聞いてあります。それから、もしくは、私どもとしても全力を挙げてこの辺の対応につきまして注視をして働きかけを行ってまいりたいと思ってあります。","id":"exchange-090"},{"speaker":"稲川委員","kind":"質問・要望","question":"品川区単独では無理だと思いますが、ぜひそこは大田区と連携をとって、大田区の上を行っていただきたいと私は思っております。観光性や防災性を考えたときに、この舟運復活プロジェクトというのも品川区でつくったらいかがかなと思いますが、その辺だけお願いします。","respondent":"米田商業・観光課長","answer":"観光協会のほうに舟運の事業者の方も入っております。そういう方々とも連携を十分とりながら、今後進めてまいりたい、このように考えてあります。","id":"exchange-091"},{"speaker":"浅野委員","kind":"質問","question":"最初に温暖化対策事業ですけれども、地域推進計画の進捗状況についてお伺いしたいと思います。２００６年度以降の２００８年度までのＣＯ２の排出量、これはどのような推移になっているのか、品川区の数字を教えてほしいと求めました。","respondent":"野呂瀬環境課長","answer":"品川区の温暖化ガスの排出量推移です。２００８年が２,２３８万トン、１４％、１３％ぐらいのプラスで推移しています。","id":"exchange-092"},{"speaker":"浅野委員","kind":"質問","question":"この差が確かにあるので、そもそも２００６年度で違っているのはなぜかなということ。２０００年度比で８.４％減っていると、該当年度のＣＯ２の排出係数を品川区としては利用するということで規定をしておりますが、お伺いします。","respondent":"野呂瀬環境課長","answer":"しっかりさまざまな啓発を通じまして、温室効果ガスの削減に努めていきたいと、こう考えているところです。これは、大井火力発電所の分を、これをちょっと中身入れたところでございまして、東京都の発表と若干減っているです。","id":"exchange-093"},{"speaker":"浅野委員","kind":"質問・要望","question":"ただ、１０という考え方になっていると思いますが、区民にわかりやすいような形でぜひともこの目標も設定をしていただきたい。平成２４年度、この１年間でそこら辺をしっかりと論議をしながら、この件についてもご答弁をお願いします。","respondent":"野呂瀬環境課長","answer":"ＣＯ２の排出係数につきましては、今後も実排出係数に沿って発表していく、こういう考えです。６２区市町村の中で、検討して、発表されるものだと了解しています。","id":"exchange-094"},{"speaker":"浅野委員","kind":"質問","question":"そしてもう一つお伺いしますが、今回太陽光発電システム等の助成、対象枠を拡大しております。平成２４年度の目玉事業というのは何かあるのかどうか、お伺いします。","respondent":"野呂瀬環境課長","answer":"これは生協なので、ホームページ等々でやっているかと思います。今後とも継続して、やはりただのＣＯ２だけじゃなくて、今後も引き続き取り組んでいきたいと思っているところです。","id":"exchange-095"},{"speaker":"浅野委員","kind":"質問","question":"受診できる医療機関というのはどのぐらいあるのか。こちらからお伺いします。","respondent":"小川健康課長","answer":"こちらの年齢対象者、５０歳から７５歳までの５歳刻みの方に対しましては、直接受診券を送付する予定です。できるだけ、国保の特定健診とも同時受診ということを目指していますので、数としましてはそんなに少なくない数ではないかと考えているところです。","id":"exchange-096"},{"speaker":"浅野委員","kind":"質問","question":"４０％の目標というのもありまして、この３つの受診率が低いものについては４０％の目標ですけれども、この中で胃がんが３.８％とありました。厚生労働省の見解がどこまで出ているか、もし万一これがカウントできるとなった場合、算出した結果があれば説明を求めました。","respondent":"小川健康課長","answer":"今の区の見解といたしましては、平成２４年度については、約３０％の受診率を見込んでいるところです。","id":"exchange-097"},{"speaker":"浅野委員","kind":"質問","question":"胸部Ｘ線、また大腸がん検診、こちらのほう、そもそも無料ですけれども、１つの突破口、具体的な取り組みとして、無料クーポン券を送ってはどうかと。やはり特定健診も平成２４年度は５４％という、大きく前進する取り組みをお願いしたいと思いますが、いかがでしょう。","respondent":"小川健康課長","answer":"このほど、受診率についても、大幅に伸びている状況です。平成２３年度につきましても、かなり伸びている状況ということで認識しています。","id":"exchange-098"},{"speaker":"浅野委員","kind":"質問","question":"６月の補正で介護福祉専門学校の５階、６階の天井改修、完全に復旧したというふうに伺っております。ご答弁お願いします。","respondent":"米田商業・観光課長","answer":"ものづくり・経営支援課のスペース、それから４階のテナントが入っているところ、そちらの天井補強を行わせていただくものです。その工事が２,７２４万円を計上しておりまして、いわゆる中小企業センターの中での小破修繕ということで３００万円確保している、こういうものです。","id":"exchange-099"},{"speaker":"高橋委員","kind":"意見","question":"２８３ページのサポしながわと品川区シルバー人材センターです。平成２１年から２２年、１,１００人から６８０人というふうに５００人減っているんですが、すみませんとの意見を述べました。","respondent":"福島ものづくり・経営支援課長","answer":"こちら、求職者登録数ですけれども、簡単に言いますと、カウントの仕方を変えたというものです。新たに来たものだけを数えるという形にして、合同面接会ですとか、そういうところで来たのはカウントしないという形をとってみました。","id":"exchange-100"},{"speaker":"高橋委員","kind":"質問","question":"それと、サポしながわ、シルバー人材センターは、ハローワークとどのような連絡をとってきているんでしょうか。シルバー人材センターの立場でお願いしたいんですが、調整、そういったことはどのようにされていたのか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"ものづくり・経営支援課とサポしながわ、あるいはシルバー人材センターの連携ですけれども、それについてお答えする。生活福祉課との連携ですが、そこでは一体となりまして生活支援を行っていく、就職支援を行っていくという形で進めていきたいと考えています。","id":"exchange-101"},{"speaker":"高橋委員","kind":"質問","question":"平成２４年度新設される、どのような効果といいますか、今言った連携に関してどのような効果が期待されていくのでしょうか。何か今までの課題がどのように劇的に解決されていくのか、その辺の期待も含めて、お願いしたいんですけれども。","respondent":"福島ものづくり・経営支援課長","answer":"そこでは、１名増強しまして、こちらの就業センターそのものの運営にも携わっていただく予定になってあります。生活保護受給者等に対しての支援等を行っていきたいと考えていますし、一般の就労支援についても、連携を強化していきたいと考えているものです。","id":"exchange-102"},{"speaker":"高橋委員","kind":"質問・要望","question":"今まで縦割りではなかなか解消できなかったことを解消していける、非常に重要であり、かつ期待されるセンターだと思います。その意気込みといいますか、人事的な側面での新たな取り組みといいますか、それをご説明いただきたいんですが。","respondent":"福島ものづくり・経営支援課長","answer":"４月１日から品川区としまして就業支援担当主査という１つの係を設置いたします。あるいは一体的なさまざまな支援、中小企業に対する支援も含めてですけれども、支援を行っていきたいと考えています。","id":"exchange-103"},{"speaker":"高橋委員","kind":"質問・要望","question":"２３区内でも温度差があると伺っています。２３区として、広域的な就労問題についてどのような取り組みができていくのでしょうか、その点をお願いします。","respondent":"福島ものづくり・経営支援課長","answer":"基礎自治体として直接就業支援、ハローワークの端末を、全国的な端末を用いまして就業支援を行います。その他、中小企業の雇用支援、そういったものにつきましても、力を入れていきたいと考えています。","id":"exchange-104"},{"speaker":"高橋委員","kind":"質問・要望","question":"頑張ってほしいと求めました。そのことに関してどのような対応を想定されているのか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"確かに、想定では１００人程度増えるのではないかということで、にぎわいも増えるというふうに私どもは考えてあります。ただ、混乱が生じないようにということで、受付の者を１名雇いまして、それによりまして十分流動させていきたいと考えています。","id":"exchange-105"},{"speaker":"南委員","kind":"質問・要望","question":"区内には１０８の商店街がありますけれども、１０年前と比べると、ちょっとそのあたりを教えてほしいと求めました。それと、生鮮品を扱うお店のない商店街は幾つあるのか、ここについても説明を求めました。","respondent":"米田商業・観光課長","answer":"平成９年のときは３,８５０ということになっておりますので、商店の数は減っているものと認識をしています。それから、生鮮を扱っていない商店街ということですが、こちらのほうにつきまして、詳細は私どものほうでははっきりしたものはつかんでございません。","id":"exchange-106"},{"speaker":"南委員","kind":"質問","question":"魚屋さんがなくなった、肉屋さんもなくなったというところは実感するところでありますので、その辺についての認識を改めて伺いたいと思います。そして、なくなった背景は何なのかということを、区としての見解を説明するよう求めました。","respondent":"米田商業・観光課長","answer":"商店街の数ですが、平成２２年、１０８でしたが、平成１２年のときに１０５という数字になってあります。それによって最寄りの商店の利用頻度が減っているという中で、生鮮品についても減少をしているんだろうというふうに想像しています。","id":"exchange-107"},{"speaker":"南委員","kind":"質問","question":"１つには、私も以前の質問の中で申し上げてきましたけれども、情報交換の場だというふうにね。高齢化社会の中で、そこもあわせてお考えを伺いたいと思います。","respondent":"米田商業・観光課長","answer":"安心して買物ができる商店街というものが不可欠であるというようなことで、これまでさまざまな商店街の支援の施策を行ってきたものです。","id":"exchange-108"},{"speaker":"南委員","kind":"質問・要望","question":"２０、１５人乗りぐらいのものでいいと思う、補助金を出して検討していただきたいなと思っています。じゃあ、この点について、１点だけ答えるよう求めました。","respondent":"米田商業・観光課長","answer":"商店主の方がご自身の商機、それから、あるいは地域の役に立つというようなことで事業の展開を行うことがあるかと思います。区といたしましては、そういう商店の商店主、あるいは商店街の動きを引き続きこれまでと同様に支援してまいりたいと考えています。","id":"exchange-109"},{"speaker":"伊藤委員","kind":"質問","question":"２６９ページの環境対策費に関連をして、それから、２７１ページのマイガーデンに関連をして、それから２８３ページ、観光施策に関連して質問します。品川区の考え方をお伺いしたいんですが、公園の照明灯を一定程度暗くして、結果として区民サービスの低下を招くということ。","respondent":"野呂瀬環境課長","answer":"それぞれ計画的に節電をしているということで、去年は逆に、ある意味緊急避難的な面もあったかと思います。それについては、今後も取り組みの中で、やはり環境課だけでなくて、区が一体となってこれからも節電等には取り組んでいく考えです。","id":"exchange-110"},{"speaker":"伊藤委員","kind":"質問","question":"国政の話ですから余り踏み込みませんけれども、私は、本来はそういうところに責任があると思っていますので、これは意見として述べします。例えばいつぐらいまでに全校に入れていくとか、そういう計画があると思いますので、そのことについての説明答弁をお願いいたします。","respondent":"野呂瀬環境課長","answer":"それはそうだと思いますけれども、できるだけむだなエネルギーは使わないという意識の中で、やはりこれからも取り組みは必要かなと考えています。環境課を含めてですけれども、庁内の中でいろいろ検討会を開いて、連絡調整を図りながら進めていっているところです。","id":"exchange-111"},{"speaker":"伊藤委員","kind":"質問","question":"成功例がどこの区施設もあるわけでしょうから、今度こうしようとか、そういうふうに具体的に展開をしていく考え方についてお聞かせください。お願いいたします。","respondent":"野呂瀬環境課長、岩田都市環境事業部長","answer":"来年度、新規に環境計画等が策定されるところです。地球温暖化の区の実行計画というのもあわせて策定していきますので、その中で明確な目標を定めていきたい、このように考えているところです。こういったときに合わせて、その時点での非常に高効率の機器に今でも変えてきておりますので、今後もそういう形になろうかと思います。","id":"exchange-112"},{"speaker":"伊藤委員","kind":"質問","question":"経年をしていくとか、それから、区の区有施設の表彰を何で考えないんですかね。多くの区民の皆さんの先頭に品川区は立っていますよということになるわけでありますから、そのことについてあわせて答弁をお願いいたします。","respondent":"野呂瀬環境課長、岩田都市環境事業部長","answer":"引き続き平成２４年度につきましては、区の商店街連合会と連携しまして、これは取り組んでいく考えです。周知等をして、引き続き継続して周知を図っていきたい、このように考えているところです。 表彰の件がちょっと抜けておりました。職員を表彰する制度もありますので、こういった制度を使いながら、さらに一般職員が頑張ってもらえるように考えていきたいと思います。","id":"exchange-113"},{"speaker":"伊藤委員","kind":"質問","question":"私が指摘したのは、品川区のことです。皆さんもすごく納得するんじゃないですか、それをしたらどうですかということの質問ですので、答弁をお願いいたします。","respondent":"野呂瀬環境課長","answer":"これもいろいろ検討しながら、その中でＰＲ等をこれから考えていきたい、このように考えているところです。","id":"exchange-114"},{"speaker":"伊藤委員","kind":"確認","question":"その後の確認で、要は今後も有効な土地があれば、活用に向けて検討を進めていきたいと考えていますというふうに答弁いただいています。去年の決算特別委員会でご答弁いただいていますから、その後、検討を進めた結果どうなったんでしょうかという確認をお願いいたします。","respondent":"藤田水とみどりの課長","answer":"そういう検討も行ってありますけれども、なかなかやはりああいう土地の中で、安全性を確保しながらやるのは難しいということも考えてあります。引き続き有効な土地を探していきたいと考えています。","id":"exchange-115"},{"speaker":"伊藤委員","kind":"確認","question":"確認したいのが、これは定期的に掲載するんでしょうかということの質問と、どうしても浜川砲台のことが出てきます。大井競馬場、羽田空港の観光ルートはできないと思うので、そのことについてのあわせて答弁をお願いいたします。","respondent":"米田商業・観光課長","answer":"今後もその辺のところにつきましては、考慮に入れつつ検討を行ってまいりたいと思います。","id":"exchange-116"},{"speaker":"井上委員","kind":"質問","question":"２７３ページのリサイクル推進費の資源回収事業の中の拠点回収、それから、観光アクションプラン推進事業について伺います。２点目は、拠点回収ですが、受付等委託費ということで、８８０万円ありますが、これの内訳と委託先を伺います。","respondent":"野呂瀬環境課長、太田品川区清掃事務所長、米田商業・観光課長","answer":"それと、９００万円の内訳ですけれども、大きなものとしましては、区の商店街連合会に対しての補助金、これが大体です。それとあとは… そのほかに、不用園芸土の処理委託費が１１０万円ほど入っているです。それから、拠点回収の委託先は、シルバー人材センターです。それから、事業といたしまして、観光まち歩き事業ということで、年３回。","id":"exchange-117"},{"speaker":"井上委員","kind":"提案","question":"それと同じページのところに、ちょっと補助金についての考え方もあわせてお伺いしたいんですけれども、ここでは２,３００万円になっています。","respondent":"野呂瀬環境課長、太田品川区清掃事務所長、米田商業・観光課長","answer":"商店街に置いてある空き缶回収、いわゆるエコスポットの回収についてのお尋ねです。今設置してあるものが老朽化によって、区の補助とか… 現在２９カ所を設置して、大体７００メートル、これでほぼ施設の拡充については一通り区切りがついたかなと考えているところです。したがいまして… 今回も被災地支援ツアーを、観光情報センターのスペースでのミニイベントの実施、今後さまざまな活動を行っていくというようなことで聞いてあります。","id":"exchange-118"},{"speaker":"井上委員","kind":"質問・要望","question":"やっぱりこれは最終年度にこの報告を求めるべきではないかというふうに思っていますが、お考えをお伺いしたいということが１点。１４条を適用する可能性のある団体への補助が何団体あって、今までに近況報告や実績報告などを求めた件数があれば、件数を説明するよう求めました。","respondent":"太田品川区清掃事務所長、米田商業・観光課長、榎本企画財政課長","answer":"一方、拠点回収で回収している量は１１万８,０００キロということで、やはり拠点回収の必要性というのはあるのではないかと思います。それから… お尋ねの件ですが、補助金ですので、最終的にはその実施の内容について報告を求め、必要に応じて精算も行っていく、このような考えです。補助金全般ということなので、補助金の場合、団体についてはすべて実績報告をもらって確認をした上でやっているということ。","id":"exchange-119"},{"speaker":"井上委員","kind":"質問","question":"わかりました。要因というか、どういうふうに分析をされているのか、ちょっとそのことだけ説明を求めました。","respondent":"太田品川区清掃事務所長","answer":"回収する団体の皆さんが品目等を決めて、実際に回収をしていただいて、業者も見つけていただくというところかと思います。その部分でなかなか団体によっては、集団回収自体が維持していくのが難しいというところがあるのかなと思っているところです。","id":"exchange-120"},{"speaker":"井上委員","kind":"質問・要望","question":"限りなくごみの、こういったもののリサイクルを推進するということは同じ目的だと思いますが、内容を精査してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"},{"speaker":"西本委員","kind":"質問","question":"１点目は、２６８ページのところに入るんでしょうか、放射能に関する講演会をするというふうに聞いております。今、放射能に対するいろんな考え方あるものですから、どういう形のものをしようとしているのか、お聞きします。","respondent":"野呂瀬環境課長、工藤生活衛生課長、藤田水とみどりの課長、米田商業・観光課長","answer":"平成２４年度、平成２３年度もそうなんですが、放射能についての講座というのは環境課主催としてはやっておりません。予算書でいいますと２５３ページ、こちらのほうに来年度講座の費用が組み込まれておりまして、２０万円ほど予算として計上しています。… 現在、そういった方々が毎日水やりをやるというのはなかなか厳しいかなと考えています。","id":"exchange-122"},{"speaker":"西本委員","kind":"質問・要望","question":"区民の方々の要望が多いものですから、ぜひとも、これを適用できるかどうかというのをちょっと検討していただきたいなと考えています。皆さんにいいものを選んでいただくとかという形で、なぜ防災センターだとそういうものができないのかということの理由をお聞きしたい。","respondent":"工藤生活衛生課長、米田商業・観光課長、藤田水とみどりの課長","answer":"放射線に関するさまざまな情報があふれている中で、やはり今後私たちはこの問題に向き合って暮らしていかなければいけないと考えています。そういった中で… 庁舎の管理の規則にのっとってやはり運営すべきだろうと、このように考えてあります。消費者センターの啓発展示室の中と外でこの２週間展示を行って… 建物の上の活用ということは、違う制約もありますので、そういった点もしっかり検討しなければいけないかなと思ってあります。","id":"exchange-123"},{"speaker":"西本委員","kind":"質問・要望","question":"消費者センター、最後にお聞きしますが、なぜ防災センターの中じゃだめなんですかということなんです。そこが変える、考える余地あるのかどうかをお聞きしたいと思います。","respondent":"米田商業・観光課長","answer":"庁舎管理規則にやはり従って、物品等の販売はふさわしくないだろうと考えています。消費者団体からもそういう声も聞こえております。","id":"exchange-124"},{"speaker":"武内委員","kind":"質問・要望","question":"３点目が２８５ページの商店街活性化事業費、４点目が２５５ページの任意予防接種、子宮頸がんについて伺います。新しい検診の内容と、また導入の背景、経緯について教えてほしいと求めました。","respondent":"小川健康課長","answer":"その２つについて、Ｃ、Ｄまでの検査結果が４つの総合判定の仕方をされるものです。血液検査という比較的受診者にとっても、体にとっても簡便な検査方法ということで、このほど導入に至ったです。","id":"exchange-125"},{"speaker":"武内委員","kind":"質問","question":"この次の質問でまた伺いますけれども、何ですかね、つかんできたというのがあると思うんですね。年齢を今まで３５歳以上だったのを４０歳に引き上げた、じゃあ、あわせて説明を求めました。","respondent":"小川健康課長","answer":"こちらにつきましては、国のガイドラインで４０歳以上ということでうたわれてきたものを、区では３５歳ということでやってきた経緯があります。","id":"exchange-126"},{"speaker":"武内委員","kind":"提案","question":"もう１回お話をいただきたいのと、うちの阿久津副委員長が、ピロリ菌関係の若い世代への検診の拡大ということでお話をご提案させていただきました。ほぼ１００％、５０歳から、もうちょっと若い世代に拡大していく考え方と先ほどのとあわせて説明を求めました。","respondent":"小川健康課長","answer":"もともと３０歳代の受診率というのは、本当にわずかの人数ですので、受診率には直接反映しないというふうに考えておるところです。","id":"exchange-127"},{"speaker":"武内委員","kind":"質問","question":"比較的胃がんに比べていいわけですから、しかも、年齢が４０歳からになっています。これを活用していくという考えはあるのかどうか、ちょっと見解を説明するよう求めました。","respondent":"小川健康課長","answer":"今、区で導入しようとしておりますのは、ピロリ菌とペプシノゲンをあわせた形のリスク検診を考えているものです。大腸がんの検便キットでの手法というご提案ですが、こちらについては今のところ考えてはございません。","id":"exchange-128"},{"speaker":"武内委員","kind":"質問・要望","question":"じゃあ、ぜひ今後検討してほしいと求めましたので、要望します。平成２３年度の予算書には電力量測定機器貸し出しというものがあったんですけれども、それとも、そこだけちょっと確認したいと思います。","respondent":"野呂瀬環境課長","answer":"それとあわせて、そこに書いてありますけれども、国産間伐材の有効利用を考えるということで、これもあわせて、新しい取り組みとしてやっていくです。継続事業ということで、あとは貸し出しするだけということで、購入金額等はここに載せていないです。","id":"exchange-129"},{"speaker":"武内委員","kind":"質問","question":"いろいろ効果は、後でまた伺えれる時間があれば、教えてもらいたいと思います。区民の方々に対する節電というのは、もっと厳しくなってくるのかどうか、そこだけ方向性をちょっと見解を説明するよう求めました。","respondent":"野呂瀬環境課長","answer":"ということもありますので、ことしにつきましては、去年の意識を持ったまま取り組んでいく。ただし、無理をしない範囲でということで考えているところです。","id":"exchange-130"},{"speaker":"武内委員","kind":"質問","question":"１つぐらいしかできないと思いますけれども、私も平成２２年の三定で買物弱者の支援の話をしたときに、こういうお話があったんです。やると決めたわけじゃないとは思うんですけれども、こことの連携とか、今後の考え方というのだけちょっと説明を求めました。","respondent":"米田商業・観光課長","answer":"品川第二のほうでそういうやりとりがあるということは聞いてあります。こちらのほうの情報もしっかり取得しながら、今後の商業・観光課としての政策に結びつけていきたい、このように考えてあります。","id":"exchange-131"},{"speaker":"武内委員","kind":"質問・要望","question":"最後要望ですけれども、もちろん商店街振興といわゆる高齢者対策というんですかね、二重にならないように積極的に進めていただきたいと。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"松澤委員","kind":"質問","question":"それともう１点、２８７ページ、小規模商店街活力づくり支援事業についてお伺いしたいと思います。１点目、被災地観光促進経費、これの事業目的と内容について説明を求めました。","respondent":"米田商業・観光課長","answer":"そうすると、少しでも区として応援をしていこうというような観点から、昨年７月に地域活動課で応援ツアーというものを実施しています。被災地域の観光等による経済的な復興支援、こういうようなことを行っていこうと、こういうことで実施するものです。","id":"exchange-133"},{"speaker":"松澤委員","kind":"質問","question":"初年度の地域活動課から、今度観光協会に委託して、３０万円委託費が出ていますよね、観光協会。この委託費というのはどのような形になっているのか、使い方というんですかね、そこをちょっとお聞きしたいと思います。","respondent":"米田商業・観光課長","answer":"１,０００円の区内共通商品券をお渡しして、お帰りになった後に区内の商店街等でお買物をしていただこうということでお渡しするものです。そちらの１件につきまして、１,０００円につき１００円相当を委託費としてお渡ししていく、そういうような仕組みです。","id":"exchange-134"},{"speaker":"松澤委員","kind":"質問","question":"南三陸町の防災センターですか、あそこも行ってきました。ですから、この施策は、できれば来年も再来年も、費用的には安いものですから、続けていきたいなと思っているんです。","respondent":"米田商業・観光課長","answer":"被災地の支援ということで、物産展、あるいは観光大使等による交流を行ってきたところです。そういうような趣旨も踏まえて、今年度実施に至りますが、参加状況等勘案しながら、今後検討してまいりたい、このように考えてあります。","id":"exchange-135"},{"speaker":"松澤委員","kind":"質問・要望","question":"これは一応要望と今言っておきます。１５０万円の事業費助成というのはどこにもないので、その辺、ちょっとお聞きしたいと思います。","respondent":"米田商業・観光課長","answer":"従前小規模商店街再生モデル事業ということで実施をしてございました。そういった中で、過去に３商店街ほど実施をしてまいりまして、一定の集客効果を見込める方策等がある程度判明してきたということがあります。","id":"exchange-136"},{"speaker":"松澤委員","kind":"質問","question":"もう本当５０メートル以内にまいばすけっとがあるんですから。本当にこれからの商店街活性化策なんていうのは、まいばすけっと、そういうのを見ずに、語らずにできないと思うんですから。","respondent":"米田商業・観光課長","answer":"一切その場で調理、加工等は行わず、そこで倉庫から運んできたパッケージのものをそのまま売るというようなことです。そういった品質のよさというようなことで、まいばすけっととの差別化が図れる、このようなこともあるのではないかと考えています。","id":"exchange-137"},{"speaker":"松澤委員","kind":"質問・要望","question":"これからせっかく小規模商店街活性化資金、つくったんですから、しっかりと活用していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-138"},{"speaker":"須貝委員","kind":"質問","question":"共通商品券発行事業もあり、一定の区内経済への波及効果はあると思いますが、たくさんある商店街振興にはつながっているんでしょうか。それについてご見解を説明するよう求めました。","respondent":"福島ものづくり・経営支援課長、米田商業・観光課長","answer":"特に新製品・新技術促進事業では、これは今度メードイン品川ＰＲ事業につながると、支援したものがさらに製品として売れ、さらに広がっていく。そのように認識しています。商店街、特に個々の商店の方々、現在の経済状況におきまして厳しい状況に置かれているということは認識しています。","id":"exchange-139"},{"speaker":"須貝委員","kind":"意見","question":"区内経済の発展につながっていけるように努力してほしいんですが、大変だと思いますが、ちょっと効果はこれから見します。そうすると、抜本的に何か考えなきゃいけないんじゃないかなと思うんですが、その辺についてもう一度ご見解を説明するよう求めました。","respondent":"米田商業・観光課長","answer":"さまざまな事情、苦しい経済事情にある中で、それこそ血のにじむ思いをしてご努力をされているものと認識しております。これは継続的に支援をするものにつきましては、引き続き継続して支援をしてまいりたいと考えておりますし、このように考えてあります。","id":"exchange-140"},{"speaker":"須貝委員","kind":"質問・要望","question":"ところで、ここで、品川区、余り出てこないんですが、品川区内の企業はどうなんですか。廃業、解散している企業数、こういうものについてちょっと数字を説明するよう求めました。","respondent":"福島ものづくり・経営支援課長","answer":"品川区内の事業所の数ですけれども、こちら、全事業所で、平成２１年に行いました経済センサス基礎調査におきまして、２万２,５８４社です。平成１８年に行いました事業所・企業統計調査では、品川区内の事業所は増えている傾向にあるのではないかというふうに理解しています。","id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"区内でちゃんと営んでいる企業の数というのは、私は一番直近であるんだから、やっぱりきちんと調べるべきだと思うんですね。これからやるのかどうかわかりませんが、その辺について、今まできちんとした報告がないんですが、それについてどのようにお考えか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"品川区内では事業所数自体は増えているというふうに考えてありますので、あるいは、そういう方が数多くいるのではないかと考えています。平成２４年度に区内、悉皆調査をする予定ですので、その中で実態を十分把握していきたいと考えています。","id":"exchange-142"},{"speaker":"須貝委員","kind":"質問・要望","question":"いや、いいようですよ、倒産減っていますよと言うんだったら、ちょっと議論のしようがないじゃないですか。そういう実態を調べて、そしてこういう予算の議論とか、そういうものに対して生かしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-143"},{"speaker":"阿部委員","kind":"質問","question":"２９１ページの西大井および天王洲の創業支援センターについて、その後時間がありましたら、品川ビジネスクラブ等についてもお伺いしたいと思います。いつまでこのような形でやっていくのかというお考えを伺いたいと思います。","respondent":"米田商業・観光課長、福島ものづくり・経営支援課長","answer":"その中で、理事会で諮った結果、品川区の商業・観光課としてはこれだけ負担してくださいというようなことでの細目についてのご提示があったものです。それから、その他の権利者の方々も、面積に応じた修繕積立金を行っていくものです。創業支援センターへのお尋ねですけれども、天王洲が平成１７年、そして武蔵小山が平成２２年という形でオープンしてまいりました。","id":"exchange-144"},{"speaker":"阿部委員","kind":"質問","question":"要は、どこからどういう名目で、何て聞いたらいいんでしょうか。いろいろ入っている団体のものをすべて消費者対策費の中でくくってしまうというのはどうなんだろうかと、そこら辺もう少し伺いたいと思います。","respondent":"榎本企画財政課長、福島ものづくり・経営支援課長","answer":"住宅が３分の１持っているということで、実際に社協が使用している部分は１５％ぐらいということで、かなり少ない部分です。そういった意味で、大きく２つのところで修繕積立金を計上しているものです。 創業支援につきましては、こういった施設での支援以外にも、融資あっせんですとか、あるいは、経営相談の中で起業相談等を行っておりますので、そういったことも含めまして、区内での起業について支援をしていきたいと考えています。","id":"exchange-145"},{"speaker":"阿部委員","kind":"質問・要望","question":"残った時間で端的に伺います。今後のこの２つの事業の方向性について説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"ただ、平成２７年に施設ができたときに、実際にそれをどうするのか。それについては今後も検討は必要かと考えています。","id":"exchange-146"},{"speaker":"若林委員","kind":"質問・要望","question":"障害者に対してはこういう検診をしますんですよという説明になるのか、例えば誤植であるとか、そこら辺のご説明をほしいと求めました。","respondent":"小川健康課長、米田商業・観光課長","answer":"障害者歯科検診の「検」の字ですが、健康の「健」という字に訂正します。心からおわびを申し上げます。プランの策定を来年度速やかに行い、プラン策定費ということで２５０万円、事業費ということで１５０万円計上させていただいてあります。","id":"exchange-147"},{"speaker":"若林委員","kind":"質問・要望","question":"昨年の決算でも質問して、この共通商品券が来年度も３億円の３億円、合計６億円というふうになります。調査、分析、ちょっとお聞かせいただきたい。","respondent":"米田商業・観光課長","answer":"そういった意味では、完全なものではないかなというふうには思っておりますが、どこで購入されたか。こういうようなものについては、商店街連合会で統計をとっているものです。","id":"exchange-148"},{"speaker":"若林委員","kind":"意見","question":"商店街、約１０８の商店街があります。今どのような評価、存在なのかというのをお知らせくださいとの意見を述べました。","respondent":"米田商業・観光課長","answer":"子どもの通学等の時間帯における見守り、あるいはそこを通られる方のいわゆる何かしらの事故があったときのすぐの対応というようなことで。あるいは、こちらについても、いわゆる地域の核としての商店街の方々のご活躍というものを十分認めするものです。","id":"exchange-149"},{"speaker":"若林委員","kind":"質問・要望","question":"もし具体的なことがあれば、教えていただきたいし、今後の考え方をお聞きしたいと思います。毎年、平成２３年度でも５回の共同催事に終わっていますけれども、今後大型連携店との商店街とのこういった期待についてもお聞かせいただきたい。","respondent":"米田商業・観光課長","answer":"不勉強で大変申しわけございませんが、防災協定については、私のほう認識してございません。互いの連携をするというようなことにとどまってございまして、その回数が今最大限やっているというようなことでご理解いただければと思います。","id":"exchange-150"},{"speaker":"若林委員","kind":"質問・要望","question":"大型店の連携、ぜひ防犯、また防災の点で、お互いにまたＷｉｎ－Ｗｉｎの関係になれるように、しっかりと知恵を出してほしいと求めました。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-151"},{"speaker":"須藤委員","kind":"意見","question":"２７３ページのリサイクル活動支援事業に関連して、先ほどご答弁いただいた廃油、油は拠点回収で回収してリサイクルしているというのは聞いたと思っているんだけれども、どのくらいの量が回収されているのかな、ちょっと説明を求めました。","respondent":"太田品川区清掃事務所長","answer":"廃食用油です。年間で平成２２年度の実績で約５,９００キロぐらい、平成２１年度で同じく５,３００キロ、こういうことで推移をしてきているところです。","id":"exchange-152"},{"speaker":"須藤委員","kind":"質問","question":"それとも、一般家庭で下水の中に流しちゃっているよというのもかなりあるよというような考え方で見といていいのかな。５,３００キロと５,９００キロという数字がどうかなというような思いがあるんだけど、いかがか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"申しわけございません。全体の量というのは把握しきれませんので、廃食用油として出てくるのは一部かなです。","id":"exchange-153"},{"speaker":"須藤委員","kind":"意見","question":"東京都で下水道で、ミドリムシを養殖してどんどんきれいにするとかというような話をちらっと聞いたので、ちょっと言明したんです。それから、２８９ページの海外進出推進事業で、これはどういうことをどういうふうにやっているのか、説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"国際ビジネス支援講座の開催、ならびに実務セミナー、さらには品川バンコクビジネスサポートセンターの運営等を行っているものです。あわせて、国際化対応専門相談員を配置しまして、各種相談に乗っているものです。","id":"exchange-154"},{"speaker":"須藤委員","kind":"質問","question":"ことしはそのあたりは入っているのかどうかと、向こうからの人から言わせると、その辺の連携がきちんととれているのか。毎年２回ぐらいタイに行っているのがいるので、また違う仕事ができるのかなと思っているんだけれども、いかがか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"こちらの支援につきましては、別途うちのほうで契約した現地のスタッフが支援をしているというものです。区のＯＢ、よく行かれるＯＢの方を使ってですが、この場ではどういう事業ができるのかよくわかりませんので、今後研究、あるいは考えたいと思います。","id":"exchange-155"},{"speaker":"須藤委員","kind":"質問","question":"それが２つに分かれてきて、例えば伝統の技と味展なんていうのは、技のほうはものづくりだよね。そのドッキングをどこかでまた組み合わせてやる必要があると思うんだけれども、その辺はいかがか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"難しい面は、１つの課がやはり小さいということもありますので、なかなか人的な問題では難しい面もあるというのも事実です。そうしたときに、産業振興のあり方をどういうふうにダイナミックに展開していくのか、その辺のところは今後研究していきたいと考えています。","id":"exchange-156"},{"speaker":"須藤委員","kind":"質問","question":"もう一つ、工場協会連合会に補助をされているんだけれども、工場協会というのが品川でやっぱり３つに分かれていると思うんですよね。やはり３つの条件というかな、３つが了解しないと前へ進まないよというようなところがあろうかと思うんだけれども、なかなか難しいか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"これの一本化の問題ですが、何年か前から検討を重ねておりまして、来年には一本化されるのではないかというように聞いてあります。一本化して、また私どもとの関係も新たにしまして、より品川区の産業の育成のために努力していきたいと考えています。","id":"exchange-157"},{"speaker":"須藤委員","kind":"質問・要望","question":"それから最後に、ものづくりと製造業というのが予算書の中にいろいろ両方書いてあるんだけど、どういうふうに見ればいいのかなというところ。予算書には仕分けしてこう出てきているんだけど、何か理由があるのかどうか。","respondent":"福島ものづくり・経営支援課長","answer":"ものづくりと製造業ですが、製造業だとより限定されたものだというふうに考えてありますし、ものづくりの場合は、ことづくりも含めたさまざまな仕組みをつくっていく、産業の仕組みをつくっていく言葉だというふうに理解しています。","id":"exchange-158"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/918450?Template=document&Id=972#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":116391,"voices":385}},{"id":"h24-20120313-3","meetingId":"h24-c-budget","date":"2012年3月13日","dateIso":"2012-03-13","committee":"予算特別委員会","time":"午後５時３９分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を160件整理しています。","topics":[{"id":"topic-01","title":"平成２４年度品川区一般会計予算","agenda":"平成２４年度品川区一般会計予算","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"２９４ページ、道路維持費、それから、３２３ページ、避難道路機能強化事業について、お伺いします。庁舎の電気代も８億円で、１７％増えるかもしれないという中で、今の段階での変更等はありますか尋ねました。","respondent":"稲田道路公園課長","answer":"区が進めている省エネ型街路灯と、２０年間のトータルコストと比較したり、やや改善されてきております。それから技術面を検討しながら、今後も、アンテナを張ってやっていきたいと思います。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"昨年度は５,１５４万２,０００円という予算でありましたけれども、今年度は４,７４０万円余ということで、減額されている。災害強化をしていくという中で、減額をされたという、その理由について、まずお伺いさせてほしいと求めました。","respondent":"品川防災整備担当課長","answer":"減額のほうの理由ですが、やはり来年度に向けて、用地、どの場所を取得できるかという見込みによって、予算計上はしております。それぞれの土地の広さ等がありまして、その辺の関係で、今回は減額ということになっている状況です。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"３年間の整備状況、７.２ｍを１０ｍにするという中で、今の整備状況についてお伺いしたいんです。実際に、その対象物件が何件あって、この３年間で何件セットバックが行われたのか、そういう状況について、教えてほしいと求めました。","respondent":"品川防災整備担当課長","answer":"対象物件は、１３５棟になります。今現在できていますのが、平成２１年からやっておりまして、現状で、３棟となっております。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"７年という期間は、見通しがどうだったのかなということが、ちょっと気になるんです。７.２ｍあって、その政策的な優先はどうなっているのか気になるんですけれども、ちょっと教えてほしいと求めました。","respondent":"品川防災整備担当課長","answer":"ですので、今後、この事業を進めていくうちに、こういう交渉の件数も増えてくるのではないかと考えております。どちらが優先というものでもなくて、すべてのことについて、徐々に進めていかなければいけないという事業と考えております。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"５０年かけても、やっていくと。特に期限を区切らないで、計画道路ということで進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"鶴委員","kind":"確認","question":"それから３１５ページの公園・児童遊園維持管理費とあわせて、３１９ページの公園バリアフリーについて、お尋ねいたします。そうした効果が確認されたことを受けて、またその効果がどうだったのか、まず説明を求めました。","respondent":"稲田道路公園課長","answer":"第二駐車場で実施しました、それから中延六丁目３番、この４カ所の準歩道に実施しました。合わせて５３９m2、実施しております。","id":"exchange-006"},{"speaker":"鶴委員","kind":"質問・要望","question":"それぞれ４カ所で、平均６℃ということだったのでしょうか。平成２３年度の予算書を見ると「標示」、どっちが正しいか、その辺もあわせて教えてほしいと求めました。","respondent":"稲田道路公園課長","answer":"今年度やった準歩道の遮熱性塗装を計測していくというところで、一応、来年度は予定は組んでおりません。それから、先ほどのお答えの中で、４カ所で６℃のことで、これは平均です。","id":"exchange-007"},{"speaker":"鶴委員","kind":"質問・要望","question":"私も、ネットで言葉を調べたら、標示のほうなのかなと思いましたので、それで合わせてほしいと求めました。ちょっと私もお聞きしていて混同してしまって、その辺をちょっともう１回、教えていただきたい。","respondent":"稲田道路公園課長","answer":"一般的に、交通安全施設である準歩道のカラー標示というのは、ニート工法という遮熱性塗料ではない、別の交通安全用の舗装剤です。それにかえて、遮熱性塗料で準歩道をやっていこうというのが、今年やったものです。","id":"exchange-008"},{"speaker":"鶴委員","kind":"質問","question":"わかりました、理解しました。表現の仕方が正しいかどうかあれなんですけれども、すべてカラー標示になっているのかどうか、その辺を説明するよう求めました。","respondent":"稲田道路公園課長","answer":"スクールゾーンが準歩道のカラー標示に、すべてなっているかというところですが、すべてなっているというわけではございません。","id":"exchange-009"},{"speaker":"鶴委員","kind":"提案","question":"省熱塗装といったものも提案したことがありますけれども、また公園の周辺、そして通学路だとか。ヒートアイランド対策の一環ということで始まったと思うんですけれども、この辺あわせて実施できないか、その辺の可能性をお伺いしたいと思いますとの意見を述べました。","respondent":"稲田道路公園課長","answer":"準歩道の遮熱性塗装というところですが、今、実験中でございまして、費用対効果等を今後検証したうえで、また検討していきたいと思います。","id":"exchange-010"},{"speaker":"鶴委員","kind":"質問・要望","question":"そのうえで、３１９ページの安全・安心の公園づくりとありますけれども、その財源と事業内容を、簡単で結構ですので、教えてほしいと求めました。平成１９年から始まったのかなと思いますが、毎年２カ所ずつの整備実施なんですけれども、説明を求めました。","respondent":"稲田道路公園課長、榎本企画財政課長","answer":"平成１９年には西の森公園、滝王子公園といきまして、年２カ所ずつやっております。平成２３年度は葦山公園、広町公園です。 財源のほうの話ですけれども、都の福祉のまちづくりのほうの包括補助が入っております。","id":"exchange-011"},{"speaker":"鶴委員","kind":"確認","question":"公園については、ちょっとまた改めて確認します。それぞれ２カ所ということで、理由は、今の財源との絡みなのか尋ねました。","respondent":"稲田道路公園課長","answer":"これは、私ども全公園をチェックいたしまして、計画的にやっていっているものです。財源はもちろんあるんですけれども、バリアフリーとあわせて、年間２カ所程度やっていくという計画で進めているものです。","id":"exchange-012"},{"speaker":"鶴委員","kind":"質問・要望","question":"自転車とか車に接触する危険性が伺えるようなところ、数字的に押さえているのかどうか、この辺を教えていただきたい。平成１９年度から２カ所ずつなんですけれども、整備を実施するにあたっての優先基準みたいなものがあるのかどうか、その辺を説明するよう求めました。","respondent":"稲田道路公園課長","answer":"大きい道路に面した公園におきましては、そのような飛び出しの危険とかが考えられます。２カ所ずつの少ない数とは思われますが、そういう交通安全上の危険な場所というところを選んでいきながら、やっていっている次第です。","id":"exchange-013"},{"speaker":"鶴委員","kind":"質問・要望","question":"先ほど、ほんとうに子どものいろいろな角度での安全、そして安心を与えるということを充実させてほしいと求めました。そうしたところをよく検証していただいて、的確な整備を進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"木村委員","kind":"質問","question":"これは、平成２３年度、大井町駅のホームドアに９,３３０万円の予算が組まれていたために、１億円以上の計上になっていました。簡単に、ユニバーサルデザインの意味をご説明ください、お願いします。","respondent":"山崎マスタープラン担当課長","answer":"いわゆるバリアフリー新法ものですが、こうした法律の中に、先ほどご説明したユニバーサルデザインの考え方が根幹に入っているです。心のバリアフリーを含むソフト施策の充実も必要という考えのもとに、平成２０年３月に、ハードの施策を展開してまいってきたといったことです。","id":"exchange-015"},{"speaker":"木村委員","kind":"質問","question":"そちらのほうに８基、そのいすがしながわお休み石ということで、よろしいでしょうか。何か行政のほうでは、これがやさしいまちづくりには必要だろうというものがあれば、説明を求めました。","respondent":"山崎マスタープラン担当課長","answer":"この間に５カ所、２基ということで、トータル１０基設置しております。こうしたものをトータルで組み合わせることによって、総合的にやさしいまちづくりの推進をさせていただいているというようなことです。","id":"exchange-016"},{"speaker":"木村委員","kind":"質問","question":"反対側の歩道にはありませんけれども、そういうところにも、障害を持った方々が歩く機会もあると思うんです。どうして反対側の歩道に設置していないのか、何か訳でもあるのか、説明を求めました。","respondent":"山崎マスタープラン担当課長","answer":"連続的な設置を行う箇所については、１経路とすることがガイドライン上、望ましいこととされております。そうした観点で、原則１経路に基づいて設置をしているです。","id":"exchange-017"},{"speaker":"木村委員","kind":"質問・要望","question":"飯沼委員から質問があったんですけれども、どうして横断歩道上には、２カ所の横断歩道上に点状ブロックがありました。そして、もしないのであれば、これからぜひ、前向きに検討をほしいと求めましたが、いかがか尋ねました。","respondent":"岩田都市環境事業部長","answer":"したがって、大井町につけてもう２年経ちますけれども、この是非について、この懇談会の中で、今、議論をしている最中です。今後、積極的に進めるにあたっても、この７団体の方々の意見をよく聞きながら、設置場所等については、厳密に選定していきたいと考えております。","id":"exchange-018"},{"speaker":"木村委員","kind":"質問","question":"なぜならば、急行が通過する駅というのは、特に先につけるべきではないかと思います。いろいろな対策がとられておりますが、そういう通過する駅こそつけたいと思いますが、いかがか尋ねました。","respondent":"山崎マスタープラン担当課長","answer":"ホームドアの設置に関しましては、現在、国のほうでもホームドアの整備促進等に関する検討会というもので、いろいろ議論をされております。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問・要望","question":"今までの実績を教えていただきたいのと、なぜか、三件入ったんですね。今まで全くなかったんですけれども、この辺、区もどういう状況であるか、教えていただきたいのと、理由があったら、説明を求めました。","respondent":"藤木交通安全担当課長、武藤都市整備下水道課長、品川防災整備担当課長","answer":"１点目の、２年間を迎えましてという件ですが、最近は大変問題です。どちらもすぐに解決できない問題で、しかも身近な問題だと思いますので… 委員ご質問の２点目の件、補助２０５号線における、いわゆる東京浴場前の交差点の信号設置に関するお尋ねです。強く認識しているところでございまして… 耐震シェルターのほうですけれども、今までの実績では、品川シェルターが３件、それから一般のシェルターのほうで１件です。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問","question":"その辺について、どうですか、ということ。その辺について、お伺いします。","respondent":"藤木交通安全担当課長、品川防災整備担当課長","answer":"はじめのご質問の、自転車に乗らずに歩きましょうということに対して、矛盾は感じなかったかというご質問についてです。区内のこのような狭隘な道路状況を考えて、安全ということを第一に考えますと… 月曜日までで、品川シェルターの問い合わせだけでも約１００件近くありました。そういった方々も関心が強いということで、品川シェルターも、これからどんどん啓発活動を進めて、普及をしていきたいと考えています。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"このシェルターをつけるかというのは、また数字的に出てくると思いますので、また出てきた時点で質問をします。場面的にあったと思うんですけれども、その辺については、いかがか尋ねました。","respondent":"藤木交通安全担当課長","answer":"警視の階級で区市町村に２人いるのは品川区だけで、品川区というのは大変進んだところで、大多数の区市町村は警部補あたりがきております。ときには無理なお願いをすることも多々ありますので、その点、警視の階級のほうがスピーディに進むのではないかと考えています。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問","question":"３２１ページの武蔵小山駅周辺地域整備事業について、お伺いします。こういった環境悪化は問題ではないでしょうかと質問させていただいたんですが、これもあわせて。","respondent":"三宅都市開発課長","answer":"例えばお隣と壁を共有しているとか、店舗の場合ですと、狭隘道路に並んでいるところで、単独で理想的な建替えができないというような状況もあります。こちらは、今まだ具体的な環境影響の評価はやっていない段階ですので、その状況の説明はまだできる状況にないです。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"武蔵小山も、その副都心のような開発を進めていくのかどうか、その点もお伺いをします。進めてはならないと、私は思いますが、いかがか尋ねました。","respondent":"三宅都市開発課長","answer":"市街地整備基本方針で定めております拠点には、必要性があって、それから具体的な計画の中で高さが決まってくるものです。日照につきましても、建築基準法などそういう法令は、当然守って、こちらもできる限りの配慮をして、計画していくことになるかと考えております。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"こういった計画は直ちにやめるべきであると思いますし、何よりも、地域の人の総意で進めるといった観点が必要です。ぜひ、今回の方針、皆さんに説明会を開いて意見を聞いてほしいと求めましたが、いかがか尋ねました。","respondent":"三宅都市開発課長","answer":"環境が悪化するようなまちづくりはすべきでないという１点目のお尋ねですけれども、風害という形のものは基本的には発生していないと考えております。従前の土地利用のやり方と比べれば、変化するものですが、そのように考えております。","id":"exchange-025"},{"speaker":"渡辺委員","kind":"質問・要望","question":"私は、３１５ページ、公園・児童遊園維持管理費のところで伺ってまいります。公園の基本原則で、いつでも、だれでも自由にという、この確認、まず公園の基本原則の定義を伺いたい。","respondent":"稲田道路公園課長、井浦土木管理課長","answer":"委員おっしゃいました、公園の基本的な考え方なんですが、いつでも、だれでも自由に、これは大原則として、私どもも考えております。犬を入れないように表示をさせていただいている公園が１９８公園、それから… 犬等で利用者に迷惑がかかるというものについては、公園の管理に支障がある行為をすること、ということで明文で定めている。このような根拠に基づいて、円満な利用調整に努めているところです。","id":"exchange-026"},{"speaker":"渡辺委員","kind":"質問・要望","question":"公園の観点に絞って、幾つか伺います。罰則強化の必要性、また、都市公園法においても、該当する、あるいは適用できる、あるいは参考になるものもあるのかどうか、伺いたいと思います。","respondent":"岩田都市環境事業部長","answer":"検討させておりますので、所管からの結論が出てまいりますので、皆さんにご報告したいと思います。子どもたちがすくすくと遊べるような公園環境を、どうしたらつくれるか、これは十分に検討させていただきたいと思います。","id":"exchange-027"},{"speaker":"渡辺委員","kind":"質問・要望","question":"もう１点だけ、直近で要望として多いところ、国文学研究資料館跡地が整備される。共存の可能性を探っていただきたい一つの例というか、象徴的な場所でもありますので、これはぜひお願いしたい要望なんです。","respondent":"武藤都市整備下水道課長、稲田道路公園課長、岩田都市環境事業部長","answer":"我々も一定の配慮を考えておりまして、地元の説明会の中で、犬を入れることを予定しております。例えば、公園に掲示します掲示板につきましては… 硬いボールで本格的に投げ合ったり、その柔らかいボールでキャッチボールをやるところにおきましては、基本的には禁止をしているものではございません。例外的に鳥かごのようなものが設置してあるところが何カ所かあるんですけれども、そこ以外は、基本的に禁止です。","id":"exchange-028"},{"speaker":"渡辺委員","kind":"意見","question":"時間による区分け、子どもの放課後は一定時間です。遊び方も必要かと思いますので、その点で、一言お願いしますとの意見を述べました。","respondent":"岩田都市環境事業部長","answer":"この問題も、先ほどの犬と同じようなことですので、今、検討している中で、十分に議論していきたいと思います。そういう大人としての常識をどう取り戻させるかということも、我々土木の部署も、これからいろいろ手を出していきたいと考えています。","id":"exchange-029"},{"speaker":"塚本委員","kind":"質問","question":"時間がありましたら、３３１ページの借上型区民住宅管理費の借上料について、お伺いしたいと思います。どういうメッシュというのですか、どういう単位というのですか、お伺いしたいと思います。","respondent":"品川防災整備担当課長","answer":"２点目の整備地域ですが、東京都が出しております防災都市づくり推進計画というものがあります。地域危険度が５に相当し、これが４５％以上、それから平均不燃化領域率が６０％未満というものです。","id":"exchange-030"},{"speaker":"塚本委員","kind":"確認","question":"どうされているかということを、もう一度、確認でお聞きしたい。その辺はどういう地域をもとにしての７０％という目標を言われているのか、そこの２点を、お伺いしたいと思います。","respondent":"品川防災整備担当課長","answer":"品川区全体で不燃化領域率を出しますと、ほぼ７０％近くにはなっております。ということで、７０％を目指しているというものは、あくまでも整備地域だったり、一つの町丁目の地域だったり、そういうところを考えております。","id":"exchange-031"},{"speaker":"塚本委員","kind":"質問","question":"東京都の木密地域１０年プロジェクトとかという中でも、非常に細かい単位で出るというのか、見ていらっしゃる。そういった形での不燃化政策というのでしょうか、その辺について、どのようにお考えか尋ねました。","respondent":"品川防災整備担当課長","answer":"これを約何％上げていくかとか、そういった形の一つの指標として、不燃化領域率のほうは使っております。品川区としても、エリア内に限っての不燃化領域率を出しまして、一つ不燃化の進んでいる状況というものを見ております。","id":"exchange-032"},{"speaker":"塚本委員","kind":"質問・要望","question":"同じく３２３ページなんですけれども、樹木が大変古いので、かえって危ないのではないかというような話をされる方もいらっしゃいます。樹木が防災林という言い方が正しいのかどうか、どういうふうにとらえていらっしゃるのか、お話しほしいと求めました。","respondent":"品川防災整備担当課長","answer":"当然、火は危ないんですが、その周りにいてもかなりの熱量になります。広域避難場所の人数の計算をする中でも、そういう算定に入れているような状況です。","id":"exchange-033"},{"speaker":"塚本委員","kind":"質問","question":"わかれば、実際に、どの程度の数を植えていらっしゃるのか。植える、植えないの考え方というんですか、前提というのは、どういうところで決めていらっしゃるのか、そういったところをお伺いしたいと思います。","respondent":"山崎マスタープラン担当課長","answer":"防災部門とも連携しながら、そうした防災性の向上に資する都市緑化という観点で、いろいろ検討しているところでおります。街路の樹種としたものも、マスタープランを策定するうえで、防災に資する都市緑化の位置づけを明記してまいるというようなことで検討をしております。","id":"exchange-034"},{"speaker":"塚本委員","kind":"質問・要望","question":"大変に効果があるですので、効果を最大限に発揮できるような形で、防災公園における樹木の活用というものも考えていってほしいと求めました。ちょっと時間がないので、以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"稲川委員","kind":"質問・要望","question":"３０１ページの細街路拡幅整備事業について、３１９ページの市街地整備事業費の大井町駅周辺の整備について、お伺いをいたします。は相談の実績で、その件数、そして、その中で具体的に住み替わったというのでしょうか、移り住んだ事例があるのか。","respondent":"柏原住宅担当課長","answer":"住み替え相談センターの相談の中から、現在のところは８件、住み替え予定になっているところです。ちょっとまだ確認が取れてないところでございまして、相談は、そういった形で受けているところです。","id":"exchange-036"},{"speaker":"稲川委員","kind":"質問・要望","question":"別々につくるべきだと思うんですが、その辺、区のお考え。多分、密集整備の担当と住宅の担当で分かれると思うんですが、各々の課長から思いをお聞かせいただきたいんですが、。","respondent":"柏原住宅担当課長、品川防災整備担当課長","answer":"どこか地域を限定したということではなく、住み替えについては、広くご相談をお受けしていきたいと考えています。ただ、政策の喫緊の課題となっている部分が、八潮にはございましたので… 家を引っ越したりとか、そういうことは難しいというようなお話は、よく聞きます。こういった事例を参考にしながら、密集地のほうでもどういった形で進めていったらいいかということは検討していきたいと考えています。","id":"exchange-037"},{"speaker":"稲川委員","kind":"質問・要望","question":"じゃあ、その方が密集市街地整備地域とか、新防火地域における荏原地域のことをよく知っているかというと、多分そこまでは詳しくないと思います。地域の不動産関係の方と連携をとって窓口をつくるべきだと、これは要望も含めて、お願いします。","respondent":"品川防災整備担当課長","answer":"それとも区独自でやっていくか、助成金を出していくか、いろいろ手段はあると思います。そういった面は、地域の状況によって、いろいろ総合的に考えて、今後検討していきたいと考えています。","id":"exchange-038"},{"speaker":"稲川委員","kind":"質問","question":"３２３ページ、密集住宅市街地整備促進事業について、お伺いいたします。具体的に言いますと、私の近くだと二葉三丁目でしょうか、そこは全く公園がない。","respondent":"品川防災整備担当課長","answer":"火災危険度で今ナンバー１とされています豊町五丁目とか、そちらについては、区としても防災広場を何とか設置していきたいと考えております。こういった一定の用地が見つかれば、区としても積極的に購入していって、防災広場をつくっていきたいと考えているところです。","id":"exchange-039"},{"speaker":"稲川委員","kind":"質問・要望","question":"そして、それに関連してもう１点、二葉公園の北側というのでしょうか、暫定整備をした７５０m2ぐらいの土地があります。積極的に事業を進めていただきたいのですが、どうなるのか、どこの代替地として利用するのか説明を求めました。","respondent":"品川防災整備担当課長","answer":"二葉公園の南側、約７００m2近くある用地なんですが、今のところ、委員おっしゃるとおり事業用地ということで確保しております。こういったところを、まだいろいろ検討しながら、どうやって使っていくかということを、現状としては、考えているような状況です。","id":"exchange-040"},{"speaker":"稲川委員","kind":"質問・要望","question":"整備をするその７００m2近くのところ、もしくは道路の出入り口をつくるとか、道路付けをしっかりとしてほしいと求めました。そこを簡単に、ご答弁をお願いします。","respondent":"品川防災整備担当課長","answer":"こちらは、委員おっしゃるとおり、まちの状況、それからどのような手法で考えていったらいいかというところも、十分に検討しまして、そういった状況によりまして、道路の整備だとか、そういった方向も考えていきたいと考えています。","id":"exchange-041"},{"speaker":"稲川委員","kind":"質問","question":"３０１ページ、細街路拡幅整備事業について、お伺いいたします。平成２２年度中の助成の中で、２２件が生け垣助成ですか、細街路の拡幅整備とあわせ技で行っております。","respondent":"中村建築課長","answer":"それから、協議が進みましてから着工するまでの間、約半年から１年ぐらいありますが、そういったずれの差もあるかと思います。それから、新防火地域の件数なんですけれども、平成２１、２２、２３年度で、それぞれ２７、２２、１６件です。","id":"exchange-042"},{"speaker":"渡部委員","kind":"確認","question":"３２７ページ、午前中に藤原委員のほうからありました、耐震シェルターのことで、ちょっと確認します。一つ確認は、どうなのか、ちょっと確認。","respondent":"品川防災整備担当課長","answer":"品川シェルターにつきましては、幅広く広めていきたいということもありまして、商標登録のほうは、してございません。","id":"exchange-043"},{"speaker":"渡部委員","kind":"質問・要望","question":"逆に、しっかりと商標登録等をすることによって、一番大事なのは安全性ですよね。すぐにお出しできて、正確なものができるように努めてほしいと求めましたが、その辺はどうか尋ねました。","respondent":"品川防災整備担当課長","answer":"その辺は、開発した日本大学と、施工していただいた業者ともいろいろ話し合いをして、今後、どういうふうにしていったらいいかということは、検討してまいりたいと思います。","id":"exchange-044"},{"speaker":"渡部委員","kind":"質問","question":"公園用地取得費、５億円。お話をちょっと伺ったときに、どのような考えで５億円と挙げられているのか、説明を求めました。","respondent":"武藤都市整備下水道課長","answer":"鮫洲運動公園というものを整備してまいりましたけれども、さらに積極的に進めていくためにも、公園用地の取得を考えているところです。しかし、現時点では適地がないことから、用地の情報等を見ながら検討をしている状況です。","id":"exchange-045"},{"speaker":"渡部委員","kind":"提案","question":"予算が出ていますので、適地が出てきて、平米５０万円としても、僕はそこそこの広さはあると思います。新たな提案とか受けてないと思うんですが、もっと啓発をしていただきたいと思うんですが、その辺はどうか尋ねました。","respondent":"武藤都市整備下水道課長","answer":"すばらしい、大人の思いつかないような具体的なアイデアをいただいて、プランとして打ち上げております。用地情報等、幅広くアンテアを張りながら、今後も検討してまいりたいと考えています。","id":"exchange-046"},{"speaker":"渡部委員","kind":"質問","question":"それから、ページ数がちょっと当てはまらないのかもしれませんが、一般質問でもありましたが、空き家の対策についてお伺いしたいと思います。なくても、ふだんからチラシ等が投函されていて、片づいているような様子がないというような話を伺う。","respondent":"柏原住宅担当課長","answer":"区としての対応です。警察や消防との連携等々でございまして、こういったことで、お話しいただいたところで対応しているという状況です。","id":"exchange-047"},{"speaker":"渡部委員","kind":"質問・要望","question":"１件ご相談があったときに、深くお伺いしたときに、やはりそのご家庭の複雑な事情で、ご主人が亡くなった。何をどういうふうに手を打っていったらいいのかわからないというときに、行政としてできるアドバイスというのがあれば、教えてほしい。","respondent":"柏原住宅担当課長","answer":"ただ、そうは申しても、防犯上、防災上、いろいろ問題があるのは認識しています。は弁護士であるとか、個別の対応にはなってこようかとは思いますけれども、そういったところを中心にお話をすることになろうかと思います。","id":"exchange-048"},{"speaker":"渡部委員","kind":"質問","question":"これからも、それを続けていただいて、何か方策があれば、新たな方策を、国等々を絡めて練ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"山内委員","kind":"質問","question":"３１８ページ、都市開発費の中から、主に再開発について伺います。このＪＲを含めた鉄道事業者の再開発に関する際の関わりといったものを、どんな感じでされているのかという点を、伺います。","respondent":"三宅都市開発課長","answer":"そして、一体的な事業になってまいりますと、敷地の共同化というようなケースでは、補助支援をする場合もあります。必ずしもあるわけではありませんけれども、駅から直結するというような形での歩行者デッキを、鉄道事業者と調整をしたというものがあります。","id":"exchange-050"},{"speaker":"山内委員","kind":"質問","question":"どうも開発といったことを一つ例に挙げますと、どうしても新しいものに目がいくではないけれども、ちょっと懸念されるかなという思いがいたします。何か手段をとっているのか、そういう話し合いがされているのかといったところを、お伺いしたいと思います。","respondent":"山崎マスタープラン担当課長","answer":"そうした田町側、港区側の動きに合わせるように、この地域のまちづくりを考えていこうということで動いております。それで、まちづくりのビジョンを策定するというような動きに結びついているというようなことです。","id":"exchange-051"},{"speaker":"山内委員","kind":"質問","question":"ですから、品川区でこういった機運が高まって、これからやろうとしているんだといったことをアピールしていかないといけないと思います。そのあたりを、リニアの新駅と結びつけて、どのように考えているのか、伺います。","respondent":"山崎マスタープラン担当課長","answer":"あるいは港区、品川区、それからＪＲも含めた検討会ができています。その検討会の中におきましては、先ほど申し上げたような品川区としての考えを、発言しております。","id":"exchange-052"},{"speaker":"武内委員","kind":"質問・要望","question":"私は、２９７ページの街路灯建替事業について、関連してお伺いします。その辺の状況について、教えてほしいと求めました。","respondent":"稲田道路公園課長","answer":"青色防犯灯につきまして、平成２２年１０月４日から平成２２年１１月１７日にかけて、試験設置して調査を実施してきました。その結果なんですけれども、９０名の方にアンケートを実施しまして、青色照明の印象をお聞きしました。","id":"exchange-053"},{"speaker":"武内委員","kind":"提案","question":"平成１８年の予算特別委員会等で、防犯の観点から提案させていただいた経緯もありましたので、薄暗いということでした。こういうことについて、区のほうは何かつかんでいますか尋ねました。","respondent":"稲田道路公園課長","answer":"その辺を考えることもできるというところでございまして、青色防犯灯につきましては、科学的実証を待ってからということになると思います。","id":"exchange-054"},{"speaker":"武内委員","kind":"質問","question":"原踏切は、私も１０年ぐらいの間に、やっぱり同じようなことが起きているということを知っています。そういった意味で、例えば、こういったことをＪＲのほうに訴えていくというようなことは、いかがか尋ねました。","respondent":"稲田道路公園課長","answer":"ＪＲのほうでそのような実績があるというお話ですので、その辺は、ＪＲのほうに、どのような状況で、どのようなことで設置したのかという調査等をやっていきまして、青色については注視して、研究していきたいと思います。","id":"exchange-055"},{"speaker":"武内委員","kind":"提案","question":"これは私の提案ですけれども、また踏切を渡ったほうに両方あるのかもしれませんけれども、区の街路灯も近くにあるんです。これは質問ですけれども、４月６日から１５日まで、これはやっぱり理由があるんか尋ねました。","respondent":"藤木交通安全担当課長","answer":"交通安全協議会のほうには、特に委員となっておりませんが、毎年度の交通安全計画を策定する交通安全対策会議のほうには、鉄道事業者も委員として入っておりまして、年間の踏切も含めました安全対策など、計画を立てて一緒に策定しているという状況です。","id":"exchange-056"},{"speaker":"武内委員","kind":"質問・要望","question":"決して入ってないからどうのこうのというわけではないんですけれども、ちょっと危惧したものですから、鉄道のほうとも連携をとっていただきたい。それからもう１点、答弁がなかったんですけれども、区独自で、その近くにある街路灯について検討するというのは、いかがか尋ねました。","respondent":"稲田道路公園課長","answer":"私ども、昨年度の実施結果におきましては、効果がそれほどないですので、他の自治体等の情報も得ながら、その辺は研究していきたいと考えています。","id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３０３ページの私道整備事業と、それから、３２３ページの密集住宅市街地整備促進事業について、お聞きしたいと思います。それから、２.５ｍ未満の私道が私道のうちで何割ぐらいを占めるのかということについても、お聞かせほしいと求めました。","respondent":"中村建築課長","answer":"それから、今年度申請がありました４９件ですけれども、そのうち９割助成、つまり地元が１割負担しましたのが６件です。全体の話をしますと、申請の数から見合って、大体１割から２割ぐらいになっているのかなと考えております。","id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１割負担があるために、一度、見ておいてほしいと求めました。既に２３区中８区が、２３区の中で、わかったら教えてほしいと求めました。","respondent":"中村建築課長","answer":"毎年、徐々に解消されていくのではないかという考えで、計画的に行っていきたいと考えております。それから、２３区内の１００％補助をしている区ですけれども、今、私どもで把握しておりますのは、港区のみ１区だけです。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"積極的にそこの私道の整備を促進する必要があるということで、幅員要件をなくして、すべての私道も全額区の負担でやるということになったんです。ほんとうに１０年以上そのままになっているという道路も、区の負担で整備できるように求めたいんですけれども、いかがか尋ねました。","respondent":"中村建築課長","answer":"こちらのほうにさらに手を加えるということになりますと、やはり何らかの負担というのが、現状ではやむを得ないかと考えています。やはりこの私道の所有者が１名だけということは少なくて、あるいは関係権利者の方々に説明に伺って、少しでもこの整備が進めばと考えております。","id":"exchange-060"},{"speaker":"吉田委員","kind":"質問","question":"３２３ページの防災広場整備工事費について、お尋ねいたします。水が３分の２ぐらい入っておりまして、それが疑問だったんですが、まずその単純な疑問を。","respondent":"稲田道路公園課長","answer":"それから、水の入った原因なんですけれども、マンホールのふたがありますが、開け閉めするために、ふたのところにやっぱり若干の隙間があります。そこを雨水等が伝って入ってきているです。","id":"exchange-061"},{"speaker":"吉田委員","kind":"質問","question":"そういう意味で、ポンプがなければ、便槽がつくってあるところは使えないのかという単純な疑問なんです。そういう意味で、パッキンの耐久性なども、ちょっとお伺いしたいんですけれども、その辺はどうなんか尋ねました。","respondent":"稲田道路公園課長、岩田都市環境事業部長","answer":"マンホールトイレなんですけれども、基本的には、そのように満杯になるほどたまるというふうには考えてございませんでした。パッキンにおきましては、一度開けてしまいますと、戻っていかないです。 ちょっと原因がわかりませんので、大至急原因を追究いたしまして、改善方、検討してまいります。雨水の侵入というのは考えにくいのですが、そこら辺は、調べたいと思います。","id":"exchange-062"},{"speaker":"吉田委員","kind":"質問","question":"具体的に、またはちょっと対策をお伺いしたいけれども、それを調べて、変えるということですか。ちょっとその辺のところを、もうちょっと詳しくお願いいたします。","respondent":"岩田都市環境事業部長、稲田道路公園課長","answer":"いろいろなところに設置しておりますので、実態調査を全カ所やりまして、不備があったところはすべて直してまいります。基本的には、雨水が侵入しないような完全防水型のマンホールを設置しておりますので… 防災広場、公園等におきましては、数なんですけれども、１６公園、７８基あります。","id":"exchange-063"},{"speaker":"吉田委員","kind":"質問","question":"その後、防災レンガ等を張っていただいたんですけれども、このレンガもはがれてしまうような感じなんです。何も使えないと思うので、そういうところは検証済みなのか、どうかお伺いしたいです。","respondent":"稲田道路公園課長","answer":"かまどベンチ、壊れているですが、これもちょっと大至急原因を調べまして、対応したいと思います。","id":"exchange-064"},{"speaker":"吉田委員","kind":"質問","question":"こういうお話なんですけれども、チェックの報告は受けているはずなんですよね。そういう連絡等のカリキュラム等はないのか、お伺いしたいので、お願いいたします。","respondent":"稲田道路公園課長","answer":"巡回点検、毎日、回っておるんですけれども、ちょっと見逃したです。以後、気をつけたいと思います。","id":"exchange-065"},{"speaker":"吉田委員","kind":"確認","question":"電気料なんですけれども、確認の意味でお願いいたします。どういう事業なのか、どうしていきたいのか、方向性をお願いいたします。","respondent":"稲田道路公園課長","answer":"これは、前年度実績に基づいて算出しております。通常は５０％の明るさでついているんですが、人が来ると１００％になるような効率的な照明の仕方など、考えていきたいです。","id":"exchange-066"},{"speaker":"吉田委員","kind":"質問・要望","question":"明るさの検証なんですけれども、やはり地域の方々によく聞いていただきまして、自転車に乗っている方、または歩いている方、高齢者、子どもがいらっしゃる方に、ご意見をぜひ聞いてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"大沢委員","kind":"質問","question":"３２９ページの分譲マンションの管理支援ということで、４点、端的に聞かせてください。最初に、工事請負費と原材料費、二つ、節のところに区分をしてありますけれども、そもそも工事請負費と原材料費というのは何なのか、説明を求めました。","respondent":"稲田道路公園課長","answer":"工事請負費ですが、これは、道路の維持管理で行う舗装工事とか、側溝改修工事、そういうものの工事発注をして行う工事の費用です。そのときに使うモルタルとか、アスファルトの簡易なもの、そういう原材料を入れているものです。","id":"exchange-068"},{"speaker":"大沢委員","kind":"質問","question":"道路公園課長ですから、河川、そして公園ということであります。材料費がないところがあるんですけれども、この違いはどうなのか、説明を求めました。","respondent":"岩田都市環境事業部長","answer":"当時は大量の原材料費が計上されておりまして、直営のうちの職員によって、道路の維持補修をしておりました。トラックで巡回をしておりまして、そのときに見つけた簡単な補修工事に使う材料費、この原材料費の中から購入して支給をしているです。","id":"exchange-069"},{"speaker":"大沢委員","kind":"質問・要望","question":"ちょっと質問が適当かどうかわかりませんけれども、そこのところは可能なところなのか、教えてほしいと求めました。","respondent":"岩田都市環境事業部長","answer":"採石とか、砂とか、アスファルトは物品ですので、原材料費で買うしか、予算上はあり得ないんです。区内の業者は小さな業者が多いものですから、そのような負担をかけられないということで、区内業者向けに原材料費で個別に材料を提供しているです。","id":"exchange-070"},{"speaker":"大沢委員","kind":"質問","question":"この件に関しては、土木工事のみならず、区内業者の発注ということ、いろいろな経済的なものも含まれているということの理解でよろしゅうありますでしょうか、お願いします。","respondent":"岩田都市環境事業部長","answer":"他の施設管理の方法は、ちょっとここでは申し上げられませんけれども、道路、公園、河川、こういったものの維持補修については、常にこういう二通りのやり方を使い分けながら維持管理をしているです。","id":"exchange-071"},{"speaker":"大沢委員","kind":"質問","question":"道路面積ということで、２００万m2余ということで書いてあります。平成２３年３月１８日に、この点はどのようにお考えになっていらっしゃるか、説明を求めました。","respondent":"稲田道路公園課長","answer":"区の道路におきまして、ある程度交通量のあるところ、それから、そうではないところといろいろあるんですけれども、地盤の支持力等を検討してやっておりますので、舗装等の構造は大丈夫だと認識しております。","id":"exchange-072"},{"speaker":"大沢委員","kind":"質問","question":"４年以内に大地震が起こるだろう確率が７０％以上ということで、どういうふうに持っていかれるのか、あったら説明を求めました。","respondent":"稲田道路公園課長","answer":"土の柱みたいなものをつくったりとか、そういう対策が効果的だと、一般的に言われております。専門家も入れていろいろ検討しているようですけれども、液状化に対する答えというのは、私どものほうで考えておりません。","id":"exchange-073"},{"speaker":"大沢委員","kind":"質問・要望","question":"東京都の指定道路の条例制定を受けて、品川区でも検証、検討をしていただきたいと考えています。これについて、何か対策を既に打たれているようなことがあったら、説明を求めました。","respondent":"稲田道路公園課長、岩田都市環境事業部長","answer":"私ども、年に１回、全体的な街路灯の点検調査をやっております。常時、巡回点検で回っておりますので、その辺で発見していこうということでやっております。 柱の一番道路に面するところから上１ｍまで、肉厚にして、一定程度の腐食圧をあらかじめ余分に見ていくという形で補強をしております。","id":"exchange-074"},{"speaker":"大沢委員","kind":"質問・要望","question":"ですから、そこのところは、すみませんけれども、検証、検討を重ねていただきながらやってほしいと求めました。私が申し上げました２０１８年ぐらいに、築４０年以上、説明を求めました。","respondent":"柏原住宅担当課長","answer":"築４０年以上ですけれども、ただいま、住宅市場動向調査というのをやっておりまして、その結果を整理しています。細かい数字につきましては、ちょっと今、手元にございませんので、何棟というのは、ちょっと今、お話しすることはできません。","id":"exchange-075"},{"speaker":"大沢委員","kind":"質問・要望","question":"その辺について、今後、どのように対応をされていくのか。この予算の中で、直近においては、どのように対応され、また考えていかれるのか、ご披露ほしいと求めました。","respondent":"柏原住宅担当課長","answer":"今後の対応ですが、４月から東京都のほうから事務移管ということで、マンションの建替えの円滑化等に関する法律で事務が移管されてまいります。","id":"exchange-076"},{"speaker":"大沢委員","kind":"意見","question":"３分の１、５分の幾つ助成するということでありますけれども、促進のために大事な問題になってくるのではないかと考えますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-077"},{"speaker":"大倉委員","kind":"質問","question":"私からは、３２１ページの武蔵小山駅周辺地域整備事業に関連して、お伺いします。その１カ所、そこがどうしてそうなっているのか、ちょっとお伺いできればと思います。","respondent":"井浦土木管理課長、岩田都市環境事業部長","answer":"武蔵小山駅のロータリーのところの２カ所のバス停ですが、区道の上を道路法の占用許可ということで、鉄道事業者に貸しています。鉄道事業者の負担で傘をつけてくださいということを条件としておりまして、現在… したがって、オープン時は１カ所です。もう１路線欲しいということで、２年経っておりますけれども、交渉しているところであります。","id":"exchange-078"},{"speaker":"大倉委員","kind":"質問・要望","question":"次に、３０３ページの私道整備事業について、お伺いしたいと思います。どういった優先順位があるのか、基準があるのか、そこを教えてほしいと求めました。","respondent":"中村建築課長","answer":"ただ、先ほど委員もおっしゃられました、防災上、あるいは、安全上といったことをかんがみて優先させるところもあります。枡のふたが割れて落ちて、足が挟まれてしまうような、こういった緊急性が非常に高いものは早急に優先してやるという形です。","id":"exchange-079"},{"speaker":"大倉委員","kind":"質問","question":"区道よりも長いというお話も伺ったことがある中で、安全性という部分でも、利用しやすい環境づくりが必要なのではないかと考えています。公共性をかんがみながら、持っている方の私有財産ということで、しっかりと負担額を取っていくのかというお考えをお聞かせほしいと求めました。","respondent":"中村建築課長","answer":"当初、５０％、そこから８５％、９０％と、９０％になったのは平成１６年です。この幅員要件によって、１割負担というのは、今のところ、継続をしていきたいと考えております。","id":"exchange-080"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひ早めに整備の申請を出していただきたいとか、そういった考えがもしあれば、教えてほしいと求めました。砂利道とかさまざまな道があると思いますので、どういった道には、ぜひ早めの整備をお願いしたいか、お聞かせほしいと求めました。","respondent":"中村建築課長","answer":"傷んでいるようなときには、ぜひとも、私どもに申請をいただければと考えております。それから、先ほど、ちょっと申し忘れましたけれども、幅員要件のもう一つの理由としては、やはり公共性というところもあります。","id":"exchange-081"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひとも、今後も、計画的にやっていただきたいと考えています。予算もどんどん増えていっておりますので、その熱い考えがあれば、最後にお聞かせほしいと求めました。","respondent":"中村建築課長","answer":"私道といいますと、お年寄りから体の不自由な方まで、さまざまな方が利用されております。ほんとうに困って申請をいただいているものと考えておりますので、私道を問わず、安全性の確保のために頑張っていきたいと考えております。","id":"exchange-082"},{"speaker":"浅野委員","kind":"質問","question":"３０９ページ、３１７ページの旧荏原平塚中学校跡地多目的広場整備工事について、お伺いします。この理由について、お伺いしたいと思います。","respondent":"中村建築課長","answer":"排水ですけれども、こちらの予算といたしましては、来年度行うべき計画の中で、排水工事の内容が多くなっているのが理由です。","id":"exchange-083"},{"speaker":"浅野委員","kind":"質問・要望","question":"件数からしても、何か中身が違うのではないかなという感じがしたので、その点、変化があれば、後で、再度教えてほしいと求めました。私道というのは、一体、区内に何件という言い方が適切かどうかは不明ですけれども、総延長とか、数字がわかれば、説明を求めました。","respondent":"井浦土木管理課長、中村建築課長","answer":"私道の延長につきましては、品川区は現在、１０万５,１０８ｍ。面積数にしますと、２６万５,５７８m2と、このように把握しています。 その中に一部含まれておりますけれども、管をそっくり入れ替えるというようなところで、非常に大きな工事になります。毎年、規模が大分上下するというところがありますので、こういった大きな開きになったかと考えております。","id":"exchange-084"},{"speaker":"浅野委員","kind":"質問","question":"勘定すると１０５km余もあるということですけれども、知らなかったというケースも、私も聞いております。それとも、やはり個人が家を建て替えるとか、そういうときにしか関与できないのか、そこら辺についても、お伺いできればと思います。","respondent":"中村建築課長","answer":"建築確認申請のときに、セットバックをしていただいたりする場合、舗装の整備が絡んでまいります。その所有者を突きとめて、整備を働きかける、あるいは注意を促すといったこともやっております。","id":"exchange-085"},{"speaker":"浅野委員","kind":"質問","question":"この総延長を、再びお伺いしたい。もしくは、名前はあるけれども、どぶでなくなったというのでしょうか、そういうものがあれば、どのぐらいの距離があるか、説明を求めました。","respondent":"井浦土木管理課長","answer":"延長につきましては、１万１,９４６ｍということで把握しています。現在、把握しているのが１２路線ございまして、延長で１,０６０ｍです。","id":"exchange-086"},{"speaker":"浅野委員","kind":"質問","question":"もし利用されていないところがある場合には、どのような役立て方があるのかということについて、お伺いします。ローテーションでやっているのか、壊れたらやるのか、お伺いします。","respondent":"稲田道路公園課長","answer":"２カ所やるんですけれども、現在は水が流れていないということで、埋めて通路化する。現場を見に行って、それを整備するというところで、改修工事等をやっていっているところです。","id":"exchange-087"},{"speaker":"浅野委員","kind":"確認","question":"昨年９月に、確認申請の際にＰＲしたりとか、またオーケーはいただいたのか。それから、平成２４年度の予算も出ておりますけれども、事業としての目標値というのは、果たしてあるのかどうか、これをお伺いしたいと思います。","respondent":"武藤都市整備下水道課長","answer":"公道部分における枡の雨水浸透枡化という事業を進めておりまして、昨年９月から事業を進めておりますが、相談にきている状況です。具体的には、降った雨の１割程度を浸透させていくという考えのもと、事業を進めているという状況です。","id":"exchange-088"},{"speaker":"高橋委員","kind":"質問","question":"街路灯管理費は、大井町のきゅりあんの前のデッキと、大井町の線路沿いに坂があるんですが、あそこの街路灯が、朝７時半ぐらいでしょうか。明るくなってからも点いていたということで、俺は大田区民だけど」というふうに言われたんですけれども、この街路灯のつき方の状況を説明するよう求めました。","respondent":"稲田道路公園課長","answer":"大井町駅東口ペデストリアンデッキの部分なんですけれども、一般的な感知報知式で点けたり消したりというものです。あそこは、自動点滅器というものを壁面につけておりまして、明るさを感じて、消えるというようなシステムです。","id":"exchange-089"},{"speaker":"高橋委員","kind":"質問","question":"では、７時半になってもついていたという状況は、そのセンサーの問題だったのでしょうか。ほかの街路灯も、そういった形で起き得ることなのか尋ねました。","respondent":"稲田道路公園課長","answer":"ほとんどの区の街路灯が、この自動点滅器というもので行っておりまして、ほかでも、自動点滅器のセンサーが汚れたりすると、あり得るです。","id":"exchange-090"},{"speaker":"高橋委員","kind":"質問","question":"では、ほかの街路灯、センサーの汚れのチェックでしょうか、せっかく多くのところで節電をしたり、省エネをされているわけですので、センサーの汚れを定期的にチェックするようなことは、やられているのか尋ねました。","respondent":"稲田道路公園課長","answer":"巡回の点検作業班がおりまして、そちらで、昼間つきっ放しのところはよくわかるんですけれども、そういうものがありましたら、その周辺をチェックしてみる、同じようなことがないかチェックしてみるという具合で、巡回点検の中でチェックしています。","id":"exchange-091"},{"speaker":"高橋委員","kind":"質問・要望","question":"今後も、節電や省エネの状況から、街路灯については必要なチェックだと思いますので、万全にお願いしたいと思います。次に３１５ページの、契約の内容等を含めて、ご説明ほしいと求めました。","respondent":"井浦土木管理課長","answer":"設置管理許可という制度の仕組みを使いまして、それから一方で、一定の歳入の確保という仕組みをとってあります。民間の専門のノウハウというものを活用いたしまして、区と業者との間で協定を結び、一定の収入を得ているというような仕組みです。","id":"exchange-092"},{"speaker":"高橋委員","kind":"質問","question":"款があれですけれども、三つのこれらの駐車場の料金収入は、三つ合わせて幾らぐらいになるのでしょうか。そして、今、契約されている仕組みは、何年間というのでしょうか、どういったスパンで契約されているのか尋ねました。","respondent":"井浦土木管理課長","answer":"三つまとめまして、年間で、収入ベースで見ますと、２,５００万円余です。初期投資という部分の費用、あるいは耐用年数という部分もありますので、５年を区切りに運用しています。","id":"exchange-093"},{"speaker":"高橋委員","kind":"確認","question":"その確認です。２,５００万円というのは、お尋ねしましたが、その辺の比率も教えてほしいと求めました。","respondent":"稲田道路公園課長","answer":"駐車場運営費は雑入の節、雑入です。","id":"exchange-094"},{"speaker":"高橋委員","kind":"質問","question":"ですから、先ほどの比率のところで、見直しが図れる状況を働きかけていってほしいと考えています。こちらの管理運営の仕組みと、駐車場収入がどのような形で入ってきているのか、お尋ねします。","respondent":"井浦土木管理課長","answer":"やはり都市公園法の設置管理許可という仕組みを使いまして、収支については、シルバー人材センターに取っていただく。この指定団体であるシルバー人材センターに対して、公園をお貸しして、一定の運用をお任せしているという仕組みです。","id":"exchange-095"},{"speaker":"高橋委員","kind":"質問","question":"２人もいるんだけれども、先ほどの天王洲とかは、全部機械でやっているのに、何でそうなっているんだろうというお話があって、今、伺ったんです。高齢者の雇用確保のためにシルバー人材センターで、というような決定というか、そういうことはあるのか尋ねました。","respondent":"井浦土木管理課長","answer":"昭和６２年に開設した当初から、シルバー人材センターに、駐車場についてはお任せするというような形で行ってまいりました。法律的な権限としましては、土木管理課です。","id":"exchange-096"},{"speaker":"高橋委員","kind":"質問","question":"シルバー人材センターのほうに、そういうふうに働きかけていくことが、果たして可能なのでしょうか。スタートは、しながわ区民公園の駐車料金なんですが、そういうふうに、シルバー人材センターのほうに働きかけることはどうなんか尋ねました。","respondent":"岩田都市環境事業部長","answer":"区として、私ども公園管理者として、シルバー人材センターに貸す根拠がなくなるわけです。今と同じように、高齢者の方がきちっと労働していただいて、対価を受け取っていただくという形でよろしいかと考えています。","id":"exchange-097"},{"speaker":"高橋委員","kind":"意見","question":"もちろん雇用確保という側面もありますけれども、さまざまな面から、収入の手だてを見つけていくことは必要だと思います。品川区は、駅周辺の開発にどのぐらい意気込みを持ってかかわっていくおつもりであるか、その辺のご説明をお願いいたしますとの意見を述べました。","respondent":"山崎マスタープラン担当課長","answer":"マスタープランを検討する際に、市街地形成の歩みということで、歴史的な観点で、いろいろ今、検討しております。こうした観点で、この地域のまちづくり、新しさと歴史が調和した、風格のあるまちを目指して努めてまいりたいと、このように考えてあります。","id":"exchange-098"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"伺うところによると、これが合っているかどうかわかりませんが、活用できる空き地ができるんだという話を聞きます。これは合っているのか、現状はどうなっているのか、教えてほしいと求めました。","respondent":"武藤都市整備下水道課長、久保田行財政改革担当課長","answer":"今の交差点につきましては、大崎のほうからきたときに右折ができないという状況もあります。歩道も非常に狭いという状況もありますので、これにつきましても、早期に事業認可を取得して整備を進めていきたいと考えております。２点目の、地元のほうにも教育委員会からご説明があったかと思いますけれども、そこが空き地になるです。","id":"exchange-099"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"補助１６３号線から伺います。さまざまな要望を聞いていただいて、ぜひ考えていただきたいと思うんですけれども、改めて説明を求めました。","respondent":"松代都市計画課長、久保田行財政改革担当課長","answer":"そういった中で、私どもの補助１６３号線整備の手続に入ってまいります。お互いに齟齬がないような調整を図って、工事を進めたいと、このように考えておるところです。 どういう活用ができるかということが課題だと認識しておりまして、今後、検討していきたいと考えています。そうした点も視野に入れながら、今後、引き続き検討を進めていかなければならないだろうと考えています。","id":"exchange-100"},{"speaker":"石田（秀）委員","kind":"意見","question":"開通するときというか、広くなるときと言ったほうがいいのか、そこだけはやっぱり同じ時期でやるべき。それはやっていくべきだと思うんですけれども、そこだけ最後、もう一度聞かせてくださいとの意見を述べました。","respondent":"武藤都市整備下水道課長","answer":"委員ご指摘のとおり、鉄道事業、道路事業ということで、今現在も、十分に協議をしながら、同時期に事業を進められるよう調整を図っているところです。引き続き、調整をしていきたいと考えています。","id":"exchange-101"},{"speaker":"中塚委員","kind":"質問","question":"つまり、この路線がないことによる地域住民の弊害について、お考えを伺いたいと思います。２９号線、３１号線の計画路線上についてですが、公園は幾つあるのか伺いたいと思います。","respondent":"松代都市計画課長","answer":"商店街のほうで言いますと、２９号線が、これは縦方向、横方向いろいろとかかわりがありますけれども、１０商店街です。３１号線の商店街はございません。","id":"exchange-102"},{"speaker":"中塚委員","kind":"質問","question":"しかし、問題は、なぜそれが２９号線、３１号線なのかということです。住民の反対を押し切って進めることは間違っていると思いますが、いかがか尋ねました。","respondent":"松代都市計画課長","answer":"区民の安全、生命を守るという点で、必要な防災上の施策を打っていきたいということを考えてあります。これが私どもが進める２９号線、３１号線の道路整備、都市計画道路の目的です。","id":"exchange-103"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めて伺いたいんですけれども、この二つの路線は、次に起きる首都直下型大震災に向けての対策なのでしょうか。次に起きる首都直下型大震災に向けての実効性ある対策だと、そういう位置づけなのかどうか、伺いたいと思います。","respondent":"松代都市計画課長","answer":"ここにきてさらに高まったですし、区長の施政方針でも、防災ということを重ねて申し上げております。私どもも、この点、さらに２９号線、３１号線実現に向けて取り組んでまいりたいと思っているところです。","id":"exchange-104"},{"speaker":"中塚委員","kind":"質問","question":"しかし、そうならば、延焼遮断として道路をつくるだけでは、区民の生命は守れません。生命は守れないと思うんですけれども、そういう計画をどのようにお持ちなのか、伺いたいと思います。","respondent":"松代都市計画課長","answer":"私どもは、その防災上の観点からも、道路が必要だと考えています。そういったことから、道路の必要性というのは強く感じているところですし、その必要性は、改めて、私どもは進めていきたいと思っているところです。","id":"exchange-105"},{"speaker":"中塚委員","kind":"質問","question":"そこをどう考えているのか、伺いたい。そこをしっかりと位置づけなければ、それこそ最悪の想定に対応できないと思いますけれども、いかがか尋ねました。","respondent":"片田防災まちづくり事業部長","answer":"区のほうとしては、それぞれのまちづくりをバランスよく進めなければいけないと考えております。道路をつくるだけではありません、それにより利便性がきちっと高まるといった中で、バランスを取って耐震もあわせて進めていきたいと考えています。","id":"exchange-106"},{"speaker":"中塚委員","kind":"意見","question":"とりわけ、災害弱者の方々へは特段の支援が必要です。そこをしっかりと位置づけるべきだし、この２路線はやめるべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-107"},{"speaker":"山元委員","kind":"質問・要望","question":"最初に、２９３ページの交通安全啓発費の中に、普及啓発経費ということで、さまざま書いてあります。それから同じく３歳児の母親交通安全教室とが新規事業となりましたけれども、どのような事業なのか、具体的にお教えほしいと求めました。","respondent":"藤木交通安全担当課長","answer":"最近、開発されたということで、購入いたしました。そこで、保健センターでの３歳児の健診の機会などを活用しまして、このようなお母さん方に安全教育をやっていこうというものです。","id":"exchange-108"},{"speaker":"山元委員","kind":"質問・要望","question":"シミュレーターは、そうしますと、個人的にというか、町会とか、自治会とか、そういう貸し出しとかは可能なのか、どうか。先ほど保健センターの３歳児健診の母親とおっしゃっていましたけれども、予定というか、教えてほしいと求めました。","respondent":"藤木交通安全担当課長","answer":"いろいろな町会ですとか、そういうところへの貸し出しも計画していきたいと考えております。見込みですけれども、計５４回程度で、２,０００名程度の方に交通安全教育ができればと考えております。","id":"exchange-109"},{"speaker":"山元委員","kind":"質問・要望","question":"幼児用交通安全絵本７,０００部ということがあるんですけれども、いつも、どのぐらい配付されているのか。そして、幼児というのは、大体何歳ぐらいまでの方たちに配付をしているのか、その辺も教えてほしいと求めました。","respondent":"藤木交通安全担当課長","answer":"部数につきましては、約７,０００部でございまして、区立、私立を問わず、保育園、幼稚園の３歳から５歳児全員にお配りしているものです。","id":"exchange-110"},{"speaker":"山元委員","kind":"質問","question":"昨日ですか、自転車安全利用五則というのですか、周知徹底というのが各実施機関に載っているんですね。みたいなことができると、もっと自転車の乗り方が変わってくるのではないかと思うんですが、その辺はいかがか尋ねました。","respondent":"藤木交通安全担当課長","answer":"区のほうでも、やはりそのような形で啓発を考えております。その中に自転車の安全利用五則みたいなものを盛り込んだり、それから、各種いろいろなチラシなどにも盛り込むようにしています。","id":"exchange-111"},{"speaker":"山元委員","kind":"質問・要望","question":"同じページなんですが、その下の放置防止指導啓発のことで、ちょっとお伺いいたします。そして決算は２,０００万円余ということで、この数があまりにも違いすぎているのはどういうことなのか、ちょっとご説明ほしいと求めました。","respondent":"藤木交通安全担当課長","answer":"平成２３年度から平成２４年度にかけまして、場所を絞って、重点的に指導を行わせていただこうと考えているために減少しているものです。２,０００万円を超えたんですが、改修に関する費用が５００万円以上計上されましたので、このときは金額が上がったです。","id":"exchange-112"},{"speaker":"山元委員","kind":"質問","question":"人数とか、それが３分の１ぐらいに減ってしまうのですが、やり方は、そういうものは変わらなく、今までどおりというわけにはいかないと思いますが、今までどおりやれるのか尋ねました。","respondent":"藤木交通安全担当課長","answer":"実態としまして、日数などが減少したり、駅数も、今までよりも減らす方向で、ただいま考えておりますので、若干、人員のほうも減少すると考えております。","id":"exchange-113"},{"speaker":"山元委員","kind":"質問・要望","question":"しかし、去年の決算では４５０ｍ設置をしたということで、設置方法というか、これはどのように決めるのか、教えていただきたいということ。それから、ブロック１枚幾らぐらいするのか、教えてほしいと求めました。","respondent":"稲田道路公園課長","answer":"その中で、１００ｍと計上していますが、実績としましては、維持工事も合わせまして、そのような数値が挙がってきているです。大体、１枚１万５,０００円ぐらいです。","id":"exchange-114"},{"speaker":"伊藤委員","kind":"質問","question":"３０３ページの立会川雨水放流管建設関連整備に関連して、３０９ページ、津波・高潮対策事業に関連して質問します。ですから、あえてここで質問させていただいた意図というのは、このことについての答弁をお願いいたします。","respondent":"稲田道路公園課長","answer":"幾度か、私どものほうにも苦情が入りまして、再三、国道のほうには、その都度申し入れをしています。都道であろうが、現場を確認して、その管理者に強く申し入れていくというスタンスで臨んでおります。","id":"exchange-115"},{"speaker":"伊藤委員","kind":"提案","question":"こちらの質問の意図としては、こういう事例は、だれだって避けたいわけですよ。そういう新たな行政の仕組みづくりを検討してはどうですかという提案ですので、改めて、答弁をお願いいたしますとの意見を述べました。","respondent":"井浦土木管理課長","answer":"東京都、あるいは国に働きかけて、結果を実現させるという方向で努めてまいりたいと考えております。","id":"exchange-116"},{"speaker":"伊藤委員","kind":"提案","question":"こういう提案をさせていただいて、もう少し、答弁をいただきましょうか。今のことを加えて、答弁をお願いいたしますとの意見を述べました。","respondent":"岩田都市環境事業部長","answer":"こういう生活をしているかという根本的な部分に入り込んで、生活再建を誘導していかない限り、ホームレス対策というのは成り立たないわけです。生きてくださいと、こういうことで、品川区の場合はやっております。","id":"exchange-117"},{"speaker":"伊藤委員","kind":"質問","question":"そういうことを踏まえたうえで、これは地域の皆さんは非常に感謝していることをお話ししておきます。将来的な水辺の環境整備等について、長年このことに対応していただきました都市環境事業部長にお伺いします、答弁をお願いいたします。","respondent":"岩田都市環境事業部長","answer":"水門設置にあわせて、立会川の底をかさ上げし、せせらぎの川に復活させるという計画を描いております。その実現が、もうあと１０年ちょっとで、先が見えてきたということで、私としては非常に嬉しい思いがしております。","id":"exchange-118"},{"speaker":"伊藤委員","kind":"意見","question":"１０年かかるかもしれませんけれども、ゴールが見えてきたということは、地域の皆様は非常に感謝しておりますので、改めてお話をしておきます。地域の皆さんは非常に心配をされていますので、そのことについての見通しをお聞かせください、お願いいたしますとの意見を述べました。","respondent":"武藤都市整備下水道課長","answer":"その一部を、区が連携して協力するために、受託して進めるものです。それにつきましては、着実に整備を進めていきまして、その後というふうに聞いております。","id":"exchange-119"},{"speaker":"伊藤委員","kind":"質問","question":"これは、確かに正しいことなんだけれども、一面、我が党の石田秀男委員も一般質問しましたが、地域の方々にとっては不安を増強することもある。そのことについて、品川区の基本的な考え方をお聞かせください、お願いいたします。","respondent":"武藤都市整備下水道課長","answer":"つまり、まず、津波が来たときの避難行動に移る最初のきっかけになったと認識しております。逃げる場所として、津波の避難ビルの指定につきましても、企業と連携して対応場所を検討するなどの対策を考えていきたいと考えています。","id":"exchange-120"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これは、ぜひ区長に答弁をいただきたいんですが、ある意味、区民の生命、財産に直接かかわる話ですので、区長の意気込みといいましょうか。お願いいたします。","respondent":"濱野区長","answer":"一定の対応をするということが必要だということで、それぞれが住んでいるところの地盤高を調査したわけです。いざというときは、落ち着いて行動ができると考えていますので、そういった作業を着実に進めてまいりたいと思っているところです。","id":"exchange-121"},{"speaker":"西本委員","kind":"質問","question":"この対応をどうされるのか、街路樹の目的とあわせて、今後の対策についてお聞きします。全体的な計画も見直しをするということが、もしかしてあるのかなと考えられるわけですが、その点に対して、お答えをお願いします。","respondent":"稲田道路公園課長、武藤都市整備下水道課長、品川防災整備担当課長、山崎マスタープラン担当課長","answer":"街路樹はまち中におきましては、景観上、それから憩いのものというところで考えております。控え木をつけて補強するというような形をとったりして… 耐震整備を進めておりまして、平成２５年度には、避難所の下水道管の耐震化を終える予定です。平成２０年度末の実績で… 広域避難場所の件につきましては、津波、それから液状化等により避難ができない状況もあるかと思います。その状況に応じて… 平成２４年度予算名、おたがいさま運動等推進費です。","id":"exchange-122"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、地域の皆様方の要望もあるかと思うんですけれども、今後どういう形で道路事業を進めていくのかということを聞きたいと思います。大井は、やはり海に向かって避難していくんですかということが、非常にあるんです。","respondent":"藤田水とみどりの課長、原高齢者福祉課長、中山防災課長、武藤都市整備下水道課長、品川防災整備担当課長","answer":"その中で、歩道の歩きやすさとか、そういったことも当然考慮しなければいけないと考えています。品川区らしい樹種を選んでいきながら… 今後、平成２４年度以降は、それをさらに発展させるということで、一つはユニバーサルデザイン研修をさらに進めていく、これが一つです。","id":"exchange-123"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、これから平成２４年度はしっかりと取り組みをされると思いますので、それにあわせて説明等々をしていただきたいと考えています。これはなぜあるのか、予算の中で、もう滞納というのを予測して計上されているのかというところについて、お答えをお願いします。","respondent":"柏原住宅担当課長","answer":"納付促進委託です。なかなか職員等々では回収が難しいということで、弁護士に委託をしまして、その分を回収するという委託です。","id":"exchange-124"},{"speaker":"井上委員","kind":"質問・要望","question":"１カ所のほうの、前回も要望しておりますが、施設を拠点に点字ブロックを考える視点があるということで再三要望しております。こちらのほうの検討は、全然進んでいないのか、どうなのか、お伺いをいたします。","respondent":"山崎マスタープラン担当課長","answer":"区役所通りにあります社会福祉協議会への動線とエスコートゾーンの設置です。はっきり設置ということは決まっておりませんけれども、反対側に向かっての横断歩道に、設置前提で検討させていただいているというような状況です。","id":"exchange-125"},{"speaker":"井上委員","kind":"質問・要望","question":"歳入の款でもお伺いいたしましたけれども、メンバーは任期が２年ということで、再任に触れていないということで大変評価をしています。実際に２年任期で要綱どおり適切に行われているかどうか、伺います。","respondent":"山崎マスタープラン担当課長","answer":"現員４４名の構成ということで、ふれあいサポート活動会議の代表、各地域というようなことで選出をされています。それから、例えば、警察関係につきましては、毎年、地区の警察の方々、地区ごとに交代するような形で振り分けをやっているというようなことです。","id":"exchange-126"},{"speaker":"井上委員","kind":"提案","question":"４５人の委員がいて、年１回しか行われていないということなんですが、この協議会で推進にもう少し力を入れていただきたいという要望があります。２年任期でどんどん委員が変わって、もう少し住民がかかわれる仕組みが必要と思いますが、いかがか尋ねました。","respondent":"山崎マスタープラン担当課長","answer":"普及啓発の専門部会も設置していこうということで、そこの専門部会の構成について、これから検討するようなこともあります。そうしたことを勘案して、いろいろ検討、研究してまいりたいと考えております。","id":"exchange-127"},{"speaker":"井上委員","kind":"意見","question":"そういうことこそ、コンサルタントがいても構わないけれども、職員の方たちがもっと積極的にかかわる必要があると思います。２３年、どうもやり方がちょっと違うのではないかと思っていますが、課題はありますかとの意見を述べました。","respondent":"山崎マスタープラン担当課長","answer":"それぞれの職場で実施する事業において、事業を行うことが可能なような研修を行ったりというようなことで工夫をしてまいったところです。そうしたところ、もうひと工夫、高齢福祉のソフトの部分とさらなる連携をしながら、本件につきまして、進めてまいりたいと考えています。","id":"exchange-128"},{"speaker":"井上委員","kind":"質問","question":"次に、照明灯明るさ検証なんですけれども、プレス発表の資料では、８４万円で、地域住民にも参加してもらうとなっていますが、実際にどのように地域住民が参加をして、この検証を行うのか、具体的に説明を求めました。","respondent":"稲田道路公園課長","answer":"それともちょうどいいのか、そういうところを住民の皆さんと一緒に考えて、適切な明るさ検証をやっていきたいと考えています。","id":"exchange-129"},{"speaker":"金野委員","kind":"質問・要望","question":"そして、早期設置の要望というか、進捗状況をお聞きしたいと思います。進まない原因というのでしょうか、何か壁があるのですか、そこら辺を説明するよう求めました。","respondent":"武藤都市整備下水道課長","answer":"設計図面を検討し、具体の協議を行って、それについては了解を得られているところです。何かハードルがあるというわけではなくて、向うの検討段階として、まだ明らかになっている段階ではないというふうな状況です。","id":"exchange-130"},{"speaker":"金野委員","kind":"質問・要望","question":"これはどういうふうに理解をすればいいんでしょうか。なので、ほかのところも何とか頑張っていただきたいという思いなんですが、いかがか尋ねました。","respondent":"柏原住宅担当課長","answer":"実施設計の段階で、実施設計をやる中で、それが出てきたです。現段階では、ほかの住宅については、細かい設計をしておりませんので、現段階では難しいです。","id":"exchange-131"},{"speaker":"金野委員","kind":"質問・要望","question":"設置をしていただきたいという思いで、これは確認をしながら、要望するということで、今回、質問を挙げさせていただいているんです。耐震化工事が行われましたけれども、やはり設置が不可能だというところでしたけれども、これは何が原因だったのか尋ねました。","respondent":"柏原住宅担当課長","answer":"エレベーターがつけられないかということで、施設部門だけではなくて、関係課が集まりまして協議をしました。そこの部分が一番のネックだったというところで、つけられないという判断ということで、つけなかったです。","id":"exchange-132"},{"speaker":"金野委員","kind":"質問","question":"区として、どのように考えていこうと、どういう対策をとっていこうとお考えでしょうか。今後は、区としては、どのようにお考えか尋ねました。","respondent":"柏原住宅担当課長","answer":"法の規制等々がありまして、ハード的なところでは、なかなかやっぱり難しいというところがあります。ハードだけはなくて、ソフトの面もいろいろ駆使しながら、そういったところに対応していきたいと思ってあります。","id":"exchange-133"},{"speaker":"金野委員","kind":"意見","question":"住み替えもあるということですけれども、それだけではなかなかできないという状況もあるのかなと思いますので、今後も研究していただいて、どうかこの対策をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-134"},{"speaker":"松澤委員","kind":"質問","question":"３１３ページ、まちづくりマスタープラン策定費、１,６０７万７,０００円。このほど、全体計画の骨子案が発表されましたけれども、今後の予定についてお聞きしたいと思います。","respondent":"山崎マスタープラン担当課長","answer":"来年度につきましては、その地区に応じたまちづくりの基本方針を定めていくというようなスケジュールになっております。公表は、来年度の末というようなことで予定しているものです。","id":"exchange-135"},{"speaker":"松澤委員","kind":"質問","question":"実は、木密地域不燃化１０年プロジェクトというのが、緊急的に入ってきました。品川区が手を挙げて、これからできるかどうかわかりませんけれども、その辺の考え方というものをお聞きしたいと思います。","respondent":"品川防災整備担当課長","answer":"もう少しより充実した形でやっていこうというものですが、これがまず、先行としてモデル地区３地区を用意しております。品川区も、ぜひ、ここの３地区にエントリーされるように、今、いろいろ研究をしてやっている状況であります。","id":"exchange-136"},{"speaker":"松澤委員","kind":"質問","question":"課長から、どうしても必要なんだという大変に力強い、延焼遮断帯についての２９号線のお話を伺いました。２０年間検討をするつもりなんか尋ねました。","respondent":"山崎マスタープラン担当課長","answer":"戸越公園の踏切の除却という表現と、高架化です。より幅広く今後の検討をしてまいりたいという思いで、いろいろ検討する中では、高架化の要望がもちろん多いということは承知しています。","id":"exchange-137"},{"speaker":"松澤委員","kind":"質問・要望","question":"武蔵小山の２６号線のアンダーもそうですよね、東武線の曳舟と業平橋間、墨田区が高架化を区施工でやるんですよね。当然、お話が入っていると思いますので、どのようなことでやるのか、ちょっと説明してほしいと求めました。","respondent":"山崎マスタープラン担当課長","answer":"墨田区の事例につきましては、東京スカイツリーができまして、周辺の交通環境等々が大幅に変わるということがございまして、そうした状況をもとに、墨田区のほうが、区において連立事業を実施する、区施工の事業に踏み切ったというようなことで、話は伺っております。","id":"exchange-138"},{"speaker":"松澤委員","kind":"質問","question":"一方、戸越公園の場合はどうですかね。すぐそばに戸越公園周辺の避難所があって、そこに行けないじゃないか尋ねました。","respondent":"松代都市計画課長","answer":"２９号線も、３１号線も、働きかけているところです。そのことがはっきりしたうえで、２９号線と鉄道の立体化というのが次に出てくる話だと考えています。","id":"exchange-139"},{"speaker":"松澤委員","kind":"質問・要望","question":"６月の選定に向けて眠れない夜が続きそうですけれども、先ほどの２９号線のことについて、今回は歯切れが悪かったですけれども、歯切れのいい答弁を、今度の質問のときには聞かせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-140"},{"speaker":"南委員","kind":"質問・要望","question":"説明会を開くこと、区民意見を聞く場をたくさんつくっていただきたいということについてなんですが、ちょっと確認をさせてほしいと求めました。ここの違いは、どういうふうなことだと見ておられるのか、それもちょっと伺いたいと思います。","respondent":"武藤都市整備下水道課長、柏原住宅担当課長","answer":"もう１点の液状化に絡みまして、同様の埋立てということで、比較的液状化しやすい地域ということで認識しております。地下水の状況だとか、それぞれ個々に状況が違うと認識しております。 区営住宅、総戸数ですけれども、１３団地で４３９戸です。今回の１月募集では、空き住宅が４戸に対して、応募者が３７５世帯です。","id":"exchange-141"},{"speaker":"南委員","kind":"質問・要望","question":"先だっても質問させていただいて、改めてちょっと確認をしたいと思っているところを、事務的に教えてほしいと求めました。空き家になっている住宅がどういう種類の住宅で、入れるような仕組みをしていただきたいと思っていますが、その点についての見解も伺います。","respondent":"中村建築課長、柏原住宅担当課長","answer":"前半のほうのご質問、建物の耐震関係ですが、品川清掃工場、その前のご質問は、東京電力火力発電所という認識で、お答えをいたします。建物の耐震性につきましては、最新の確認申請が出てきましたのが平成１７年あたりという認識ですが… これだけ空いているというところがありますので、こういったところを利用すべきであるというのは、すごく当然の考え方ではないかと思ってあります。","id":"exchange-142"},{"speaker":"南委員","kind":"質問・要望","question":"つくっていただきたいと、このことは研究していただきたいと、要請を強くさせてほしいと求めました。ちょっと質問した八潮のところなんですが、安心感を与えていただきたい、時間がきましたので終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、今現在、平成２４年度内にこの事業が執行される見通しがあるんでしょうか。現在もう、そういう計画が出ているんか尋ねました。","respondent":"品川防災整備担当課長","answer":"耐震補強をするときに設計図を書くものなんですけれども、こちらのほうが、平成２６年度まで助成をやるようになっております。実際の改修ですが、こちらは、平成２７年度まで予定しておりますので、まだ期間が十分にあるかと考えております。","id":"exchange-144"},{"speaker":"須貝委員","kind":"質問","question":"ところが、ここは、相当容積率が高い建物が建つわけですから、１年以内にこの予算が執行できるという見込みはかなり薄いと思うんです。平成２７年度まで持っていくというのはわかりますが、最初から１０億円という金額をぽんと出すのは、説明を求めました。","respondent":"品川防災整備担当課長","answer":"それから、１０億円のほうなんですけれども、こちらは、耐震診断をやるだけでも、１棟当たり大体５００万円から１,０００万円前後かかります。そう考えてみると、１０億円という数字も、そんなに大きくないというふうに、私のほうは考えております。","id":"exchange-145"},{"speaker":"須貝委員","kind":"質問・要望","question":"これだけの震度７という想定がある限り、ちょっとここはどうなのかなという心配がありますので、よろしくお願いいたします。これは燃えにくい住宅、そして、延焼しにくい住宅に誘導するということか尋ねました。","respondent":"品川防災整備担当課長","answer":"これについては、委員おっしゃるとおり、まさに燃えないまちをつくるといっても、さすがにやはり難しいという点があります。燃えにくいまち、これからつくっていくということです。","id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"それも、隣接する建物と建物の間が４０cmから５０cmという間隔しかありません。木造住宅密集地域を解消しようとする区の政策と相反するものではないかと思うんですが、どうなんでしょうか、答えるよう求めました。","respondent":"品川防災整備担当課長","answer":"木造住宅の密集地域の中で、地区計画というものを進めております。ここの中で、最低の土地の制限とか、そういったものをかけて、この辺の対応は行っている状況です。","id":"exchange-147"},{"speaker":"須貝委員","kind":"質問","question":"でも、やはり、中は木造ですから、その辺もし何か新しい方策、対策とかできましたら、よろしくお願いしたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-148"},{"speaker":"阿部委員","kind":"質問・要望","question":"２９３ページの五反田駅自転車等駐車場増設・改修工事、３１７ページ、簡単に伺いたいと思います。あの辺を歩いていると、ほんとうに２週間にいっぺんぐらいのペースで、「駅までどうやって行くんですか」と聞かれます。","respondent":"山崎マスタープラン担当課長、三宅都市開発課長、久保田行財政改革担当課長","answer":"学校内部のほうで説明会を行うというような、条例上の義務づけまでは、現時点では必要ないかなと考えています。不特定多数が利用する施設に対して説明を負… 実は、都市再生ビジョンというものをつくっておりまして、その戦略５というところで持続的なまちの発展ということをうたっております。… 先ほどもご説明しましたように、今後、どういう活用が可能か検討していきたいと考えているところです。","id":"exchange-149"},{"speaker":"阿部委員","kind":"質問","question":"その分だけ時間的に遅れて、トラブルのもとになってしまうから、最初からいかがですかということです。私の質問は、敷地と、その隣の地区外の地域と一体的に整備を行うんですかということです。","respondent":"久保田行財政改革担当課長","answer":"先ほどもお答えしましたように、今、私どものほうで考えているのは、既存校舎のある場所を、あれが移転した後に、その跡地について活用を検討するですので、御殿山小学校ではないというところとは、現在のところでは別というふうに考えております。","id":"exchange-150"},{"speaker":"阿部委員","kind":"質問","question":"この先どの程度必要であるか、その適性な規模というのを考えていらしたら、教えてください。少し福祉団体というのとは性格が違ったカテゴリになってきているのではないかと考えているんですけれども、その辺は、どのようにお考えか尋ねました。","respondent":"藤木交通安全担当課長、榎本企画財政課長","answer":"今のところ、計画では、２００台程度増設を予定しております。おおむね今回のが適性規模ではないかと考えておりますが、今後の状況を見まして、またいろいろと見直す可能性はあります。 就業支援ということで、サポしながわが就業センターとくっつくということが、まず一つあります。福祉よりは産業振興という面が強くなったということで、今回、こういう形で移行したものです。","id":"exchange-151"},{"speaker":"阿部委員","kind":"意見","question":"福祉団体だから区が貸し付けて、それでお仕事をしてもらうというくくりの中で、しながわ区民公園の駐車場の管理をしてもらっていると。もし、ちょっとそれが当たらなくなるのではないかという疑問だったので、その辺のお考えを説明するよう求めました。","respondent":"井浦土木管理課長","answer":"シルバー人材センターにしながわ区民公園の駐車場を管理していただいているということの背景の説明としまして、高齢者雇用安定法に基づく指定団体であるということも踏まえまして、社会政策的な観点からお貸ししているです。","id":"exchange-152"},{"speaker":"阿部委員","kind":"質問","question":"１個だけ、その筆頭に戸越公園というのが出ておりまして、非常に何か怖いなという感じだったんです。多分、あの記事は読まれていらっしゃると思うので、反論があれば、説明を求めました。","respondent":"品川防災整備担当課長","answer":"反論というよりは、戸越公園付近は、大分、密集地域であることは確かだと思います。戸越公園周辺不燃化事業、それから防災生活圏事業を通じて、少しでも戸越公園が安全な避難場所となるように日々努力しているという状況です。","id":"exchange-153"},{"speaker":"若林委員","kind":"質問・要望","question":"河川管理費と下水道合流改善施設整備工事をまとめて伺います。品川区が考えられている全体像、そこら辺を、ちょっとお聞かせほしいと求めました。","respondent":"藤田水とみどりの課長","answer":"管理者が東京都であるということから、その分を区が担ってやる分については、都から特例交付金としていただいて行っているものです。その内訳といたしましては、清掃や汚泥の浚渫、それから、立会川等の護岸の補修等で使っているものです。","id":"exchange-154"},{"speaker":"若林委員","kind":"質問","question":"わかりにくい質問だったんでしょうか、すみません。いい方向にという意味で、そこで、全体像をちょっとお聞きしたいということです。","respondent":"藤田水とみどりの課長","answer":"先般、品川区長、目黒区長とともに、東京都のほうにも要望いたしまして、都としても、これから一緒に取り組んでいこうという形になっております。荷揚げ用のクレーン等を設置して、こういったことを活用していこうということで考えておりまして、考えているところです。","id":"exchange-155"},{"speaker":"若林委員","kind":"質問・要望","question":"１月２５日に区長が都庁に伺って、ちょっとこれは担当の方に確認ですが、今後も。力強く進めてほしいと求めましたが、まだ非公式なんですか、どういうふうに考えられているのか。","respondent":"藤田水とみどりの課長、三宅都市開発課長","answer":"それから、目黒川の利活用を進める協議会ですけれども、協議会については、正式に１２月に立ち上げを終わってあります。さまざま、これから調整を進めて、なるべく早い段階でこういった動きがとれればと考えています。 これは、北品川五丁目第１地区の再開発事業の費用を頂戴して、区のほうで整備するということになってあります。都市再生特別地区という都市計画を適用されておりまして、地区外貢献として、これを整備することになっているものです。","id":"exchange-156"},{"speaker":"須藤委員","kind":"質問","question":"２年間見ていて、屋根がつかないので、４月に許可を取り消しますみたいな話があったんですけれども、ちょっと私の聞き方が違っているのかどうか。だけれども、２年間そのことが守られていない、ですから、４月になったら、そこを打ち切ると、そういう話になるんか尋ねました。","respondent":"岩田都市環境事業部長","answer":"もう１バースは、使わないバスバースということで、空間を設置していたものです。今のバースを使わなくても、利用者にとっては何ら不自由がなく使えるバス停ですので、そういうふうに強く言ってみたです。","id":"exchange-157"},{"speaker":"須藤委員","kind":"意見","question":"２９７ページの道路擁壁安全点検委託８７カ所というような形があるけれども、そういうものも、そういう仕組みをつくっているのかどうか。予算が１２億円ぐらいあるんですが、それなりの補てんをしていきますという考え方があるかどうか、説明を求めました。","respondent":"稲田道路公園課長、品川防災整備担当課長","answer":"２９７ページ、道路擁壁安全点検委託につきましては、既に台帳等があるんですけれども、今回、もう一度点検してみようということでございまして、さらなるその先というのは、現在のところは、まだ予定しておりません。まだ１回もオーバーしたことがないので、どういうようにやるかはあれなんですが、それぞれの枠で予算のほうを整えております。","id":"exchange-158"},{"speaker":"須藤委員","kind":"質問","question":"ですから、そのあたりのＰＲのほうも、よろしくお願いします。私は、国全体でやろうということなので、品川区でもそういうパワーがある人がいれば、ぜひと思っていますが、いかがか尋ねました。","respondent":"濱野区長","answer":"品川区は、２３区の中でも最も積極的に復興支援に乗り出していると自負をしています。単に復興支援ではなくて、品川区のためにも役に立つ支援というふうに考えているところで、今後も積極的に行ってまいりたいと考えています。","id":"exchange-159"},{"speaker":"須藤委員","kind":"質問・要望","question":"ほんとうに使えるかどうかというのを、こうなったというのでは遅いと、私は思うんです。今後、やっていただけますでしょうか、すべてについて。","respondent":"岩田都市環境事業部長","answer":"東京消防庁が使っている４０ｔ以上は別にしまして、年に１回、毎年きちっとした管理をしていきたいと思います。","id":"exchange-160"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/918450?Template=document&Id=974#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":117990,"voices":383}},{"id":"h24-20120314-3","meetingId":"h24-c-budget","date":"2012年3月14日","dateIso":"2012-03-14","committee":"予算特別委員会","time":"午前１０時００分～午後５時２８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を160件整理しています。","topics":[{"id":"topic-01","title":"平成２４年度品川区一般会計予算","agenda":"平成２４年度品川区一般会計予算","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"それから３３７ページのまちの人々に学ぶ授業経費についてと、市民科の中かと思うんですが、防災教育についてお伺いさせてほしいと求めました。これはどういったことをするのかということと、また実際これをもう受けた方とかはいらしたのかということをお聞かせほしいと求めました。","respondent":"齋藤庶務課長","answer":"３年前が１０人、去年が１０人、今年が６人というふうに減っております。「健康診断を受けなさい」と、こういうことを徹底しておりますので、意識改革が図れてきたのだというふうに考えております。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"これは今、岡山県などでやられているというお話でしたけれども、教職員の方々のストレスというのが一体どういったストレスなのか。そういった要請があるからだと思うんですけれども、この教員のメンタル対策という意味について、改めて説明を求めました。","respondent":"冠木指導課長","answer":"東京都全体でみますと、ストレスの原因となっているのは、子どもたちへの対応というところでのストレスが１つあります。３番目にありますのが保護者との対応ということで、保護者との対応はまだ東京都全体で１０％未満というような全体の傾向です。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"次ですけれども、まちの人々に学ぶ授業についてお伺いします。どのようなことをやられているのかということと、この授業の必要性と、区としての評価はどういう形になっているのかということを説明するよう求めました。","respondent":"冠木指導課長","answer":"中身としましては、茶道であったり、品川音頭の指導をいただいたり、お花や生け花、クラブ活動、俳句等々、多面にわたっております。それぞれの学校で年間２０回ぐらい、そういった機会を持ってありますので、それ相当の成果が上がっているという報告を受けているところです。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"そういったことで、まちの人々に学ぶ授業というのは大切だと思うんですけれども、ちょっと今勘違いしていたのですが、これは市民科の授業の中で、いろいろ専門家の方に来ていただいたりする授業もそれに入っているのかなと、その辺も確認させていただきたいので、それをお願いします。","respondent":"冠木指導課長","answer":"市民科でも、地域の皆様に講師になって授業をしていただくとか、そういった機会にもこの制度は使っていただいているところです。もちろん入っております。","id":"exchange-004"},{"speaker":"沢田委員","kind":"意見","question":"さらに最近、ＣＳＲに積極的に取り組む企業が増えていますし、こういった企業にとってもニーズがあるということだと思うんです。授業の中で、どういうふうにお考えになるか、そういった中で取り上げていくということはできるのかということを説明するよう求めました。","respondent":"冠木指導課長","answer":"これまでも品川区内の企業の皆様のご協力を得て、職場を体験させていただいたりというような取り組みを市民科でしています。地域のお力の得られやすい曜日というふうにも認識しておりますので、今後もそういったところへもお力を借りていく、そういうような考え方でおります。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問・要望","question":"先生もともに、事前の打ち合わせとか、そのあとの確認まで一緒になってできる体制をぜひつくってほしいと求めました。地震が起きてから各小中学校で新たにいろいろな防災教育を行っていると思いますが、どういったことを行ってきたのか内容を説明するよう求めました。","respondent":"冠木指導課長","answer":"今、委員のお話のように、品川区では防災教育ということで、市民科の中で今まで取り組んでまいりました。登米市の子どもたちがどういうふうなことを考えているのかというようなことを伝えていく授業などを行い、また、そのプログラムの中でも実施しました。","id":"exchange-006"},{"speaker":"沢田委員","kind":"意見","question":"品川区の場合は、避難所になることとかそういうことを考えると、これから品川区の学校教育の中での防災というのはすごく重要だと思うんです。毎年これからどのように扱っていくのかということ、それを毎年そういった形で授業としてやっていかれるのか、その辺のことを説明するよう求めました。","respondent":"冠木指導課長","answer":"今回の震災を受けまして、学校がやるべきこと、まずすぐにやるべきことということで、防災計画の見直しについては全校で実施をいたしました。やるべきことについて、今、議論をともにして検討しています。","id":"exchange-007"},{"speaker":"沢田委員","kind":"質問・要望","question":"その避難所としての機能ということで両面あると思うんですが、やはり子どもたちへの防災教育も大切な教育だと思いますし、いざというときの対応ができるよう今後とも積極的に指導していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"鶴委員","kind":"質問","question":"教員の英語力アップへの取り組みなど、熱い思いをお聞きする一方で、今後の課題等についてもお伺いしました。まず品川区全体としての英語教育の評価、また校長先生が指摘する課題に対してどのようにお考えになっておられるか、そのあたりをお尋ねいたします。","respondent":"冠木指導課長","answer":"品川区全体の英語教育の考え方ということから説明をさせてください。年間２４回の英語の実技研修をやっておりまして、模擬授業やクラスルームイングリッシュの指導技術の向上というようなところに努めているところです。","id":"exchange-009"},{"speaker":"鶴委員","kind":"質問・要望","question":"区長の施政方針においても、教員に対しては言葉の達人になってほしいとおっしゃっておられました。見計らい配付という形で、それを選定するというふうにちょっと伺っているのですが、まずこのあたりをお聞きしたいと思います。","respondent":"中元品川図書館長","answer":"児童部門につきまして０門の総記から９門の文学までの収集の要綱、それに沿いまして、そのご指示も仰ぎながら購入をしているところがあります。","id":"exchange-010"},{"speaker":"鶴委員","kind":"質問・要望","question":"毎年７万冊近く、ちょっと調べる中で確認できなかったのですけれども、それがホームページのニュースで出ていました。もしなければ、本の選別の仕方というのがいろいろあると思うんですけれども、図書の寄贈といったお考えはいかがか尋ねました。","respondent":"中元品川図書館長","answer":"２点目の、被災地への支援のことですが、現地へ図書館の職員も何人か交代で行かせていただいておりました。その中で、もちろん相手様からそのようなご要望がありましたら、品川区立図書館としてもぜひご支援、ご協力をさせていただきたいと存じます。","id":"exchange-011"},{"speaker":"鶴委員","kind":"質問・要望","question":"本当にそうした図書、良書を充実させる、こういったことをより一層また深めてほしいと求めました。どういった内容なのかということと、この辺の変化がどうか、この辺を説明するよう求めました。","respondent":"冠木指導課長","answer":"そういった人権テーマに基づいてさまざまな取り組みをしていて、そういうようなところで子どもたちの人権意識を育てているところです。そういった中で、ポスターの中にも、差別についてストレートに表現をできるようになってきたというような成果が上がってきているところです。","id":"exchange-012"},{"speaker":"鶴委員","kind":"質問","question":"〔「ずっと」と呼ぶ者あり〕ずっとですか。内容なんですけれども、具体的にどういうことを、また、教材とかその辺についても教えてほしいと求めました。","respondent":"冠木指導課長","answer":"いろいろな取り組みをしているところではありますけれども、食に対する思いをもう一度改めて、感謝の気持ちを育てるというような授業をしています。","id":"exchange-013"},{"speaker":"鶴委員","kind":"質問","question":"大阪府立柴島高等学校というところで、この間、その取り組みをされている先生に直接お話をお伺いしました。いわゆる研究材料として、教材のＤＶＤを取り寄せてぜひ検討してみたらどうかなというふうに思いますけれども、いかがか尋ねました。","respondent":"冠木指導課長","answer":"こういった身近な材料を人権教育に生かしていくという取り組みはそれぞれの教員もやっておりますし、非常に大切なことだと思ってあります。この件につきましては、私も勉強します。","id":"exchange-014"},{"speaker":"鶴委員","kind":"意見","question":"その辺があるので、そうしたところも含めてぜひご検討ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"向委員","kind":"質問","question":"私からは３３３ページの教職員健康管理費の中の、それに関する教育とか情報リテラシー教育全般の実施状況等についてお尋ねできればと思います。トライアルですかね、今回本格的に実施されることになったというようなことも伺っているのですが、そのあたりを説明するよう求めました。","respondent":"齋藤庶務課長","answer":"教職員については東京都教職員組合での健康診断のときに簡単なストレスチェックを行います。そういった細かい７０項目ぐらいのチェックがあって、かなり詳細な燃え尽き度がわかる、こういう中身になっております。","id":"exchange-016"},{"speaker":"向委員","kind":"質問","question":"保護者との関係、本当に実に多くの仕事をこなさなければならないなと、こちら側から見ていてもそのあたりは大変心配に思っています。９人、６人ということで、教えていただけますか。","respondent":"齋藤庶務課長、冠木指導課長","answer":"１点ちょっと大きい間違いをしてしまいましたので訂正をさせてください。失礼しました。 全体の職員の数から行くと１％ぐらいということになります。進路変更でご家庭に入られるであるとか、あるいはもう少し勉強したいということで大学院に進まれるというような方が品川区の傾向としてはあります。","id":"exchange-017"},{"speaker":"向委員","kind":"意見","question":"最後に１つ、１つの課題としては、頑張ってしまう方が結構いらっしゃると思うんです。このあたりの意気込みというか効果を上げていくために、どのように考えていらっしゃるか、そのあたりをお願いしますとの意見を述べました。","respondent":"齋藤庶務課長","answer":"この３年間、健康診断の受診率が７８％から９８％に上がりました。副校長会と十分連携をしていく中で、そういう意味で風通しのいい職場が品川区の小中学校ではあるということでご理解をお願いいたします。","id":"exchange-018"},{"speaker":"向委員","kind":"意見","question":"子どもたちのソーシャル・ネットワーキング・サービスについて、ちょっと簡単になると思いますけれども、お尋ねしたいと思います。指導のベースになるようなお考えというのは、品川区としてはどのようにお持ちなのか、お尋ねしたいと思いますとの意見を述べました。","respondent":"冠木指導課長","answer":"だいたい各学年５時間ぐらいを設定しまして、全体で９年間で子どもたちの状況に応じた情報モラル教育をしています。ネチケットであるとか、あるいは不良サイトに近づかないというような指導をしています。","id":"exchange-019"},{"speaker":"向委員","kind":"意見","question":"けれども、私もちょっと検索してみたのですが、明らかに小中学生とわかるようなプリクラとかが平気でネット上に掲載されているのをよく拝見します。なので、全体的に力を伸ばしていってほしいと求めましたので、今後ともどうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"鈴木（博）委員","kind":"質問","question":"３５５ページの児童・生徒健康管理費、時間があれば３３７ページの市民科・各教科充実経費までお伺いしたいと思います。最初に３４１ページの国際理解教育についてお伺いいたします。","respondent":"冠木指導課長","answer":"東京のこと、日本のことを理解していくかというようなスタンスで、国際人として生きていくための資質を伸ばしていくということが１つあります。","id":"exchange-021"},{"speaker":"鈴木（博）委員","kind":"質問","question":"先ほどの質疑で、これはオプションではなく全学年で、正規の単元として幅広く多様に実施する必要があるのではないでしょうか。それらをはぐくんできた我が国と郷土を愛する、その教育の取り組みと推進について、いま一度品川区のお考えを伺いたいと思います。","respondent":"冠木指導課長","answer":"郷土を愛する、すべての子どもたちにそういった品川区の歴史であるとか、今品川区がやろうとしていることを伝えているところです。こういった取り組みを通して、子どもたちを国際人として育てていくことも私たちの使命です。","id":"exchange-022"},{"speaker":"鈴木（博）委員","kind":"質問","question":"３５５ページの児童・生徒健康管理費の各種検診等委託についてお伺いいたします。品川区としても無意味な寄生虫卵の検査を外すように国に働きかけるべきと思われますが、担当者のご見解はいかがか尋ねました。","respondent":"和氣学務課長","answer":"委員ご指摘のとおり、昨年平成２３年度で保有者は４名だけです。今のところ、私どもも専門家ではございませんので、十分に学校医と協議をしながら対応については考えさせていただきたいというふうに考えてあります。","id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問","question":"３３７ページの市民科・各教科充実経費に含まれるかどうかわからないのですが、メディアリテラシー教育について簡単にお伺いしたいと思います。その項目がどこにもないのですが、これに対する対策、取り組みというのはなされているのか尋ねました。","respondent":"冠木指導課長","answer":"あるいはインターネット上の情報については、その中で不必要なもの、悪質なものもあるというような授業をそれぞれの学年で実施しています。これは市民科の一環として実施しています。","id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは武道の必修化についてお聞きしたいんですけれども、３３９ページのスポーツ教育推進事業等になるんでしょうか。それから年間何コマやるのかを説明するよう求めました。","respondent":"冠木指導課長","answer":"それに合わせて私どもが支援をしていくということになります。品川区の場合は小学校５、６年生は主に３～５時間ぐらい、体育の授業として年間で１０時間ぐらいです。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"代表質問のときの答弁でもあったんですけれども、小学校３８校中２６校、中学校１５校中１３校と、ここで柔道が行われるということですけれども、今まで必修化される以前に柔道をやっていた学校はどれくらいあるのかを教えてほしいと求めました。","respondent":"冠木指導課長","answer":"品川区においては平成１８年度に小中一貫教育要領をスタートさせまして、剣道、それから相撲を各学校で取り組んでいただいているところです。例えば平成２３年度、今年度につきましては、小学校においては柔道が２６校、相撲が２校、剣道が１０校です。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"どの辺までを考えているのか教えていただきたいのと、あと、どの程度の指導経験を持たれているのかなと。ただ見て、教えたことがありますという程度ではちょっと心配だなと思うんですけれども、説明を求めました。","respondent":"冠木指導課長","answer":"基本は礼に始まって礼に終わるという、そういった指導、日本の武道についての精神をしっかりと学ぶというところで実施しています。安全面については一切問題がございません。","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問","question":"２０００年から２００９年のデータですけれども、年間４人の子どもが亡くなり、１０人の子どもが重い障害の事故に遭っている。こういった状況は保護者の方にも知らせた上で必修化されるのか尋ねました。","respondent":"冠木指導課長","answer":"そういうようなところでやる授業ですから、これはもう安全を第一に進めていくです。授業でそういった事故につながったというのは全国で１件というふうに把握しておりますけれども、そういった部分での事故と理解しております。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"５０年前に起きた死亡事故をきっかけに、多岐にわたって子どもの命を守るということで、それほど徹底して対策をとっているということなんですよね。あまり専門性が少なければ、それこそ起きやすいのではないかなとすごく心配をするんですけれども、いかがか尋ねました。","respondent":"冠木指導課長","answer":"７年生以上についても、受け身が十分に身についていない場合は投げ技は扱わないことというような内容で指導を徹底しているです。２６日に実技研修会を行いますけれども、講習を受けていただき、安全の徹底をしていくです。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問","question":"この指導員の研修なんかは、どれぐらい、どんなレベルで行われるのでしょうか。どこでも起き得ることですので、万全な指導員体制、研修方法、あと中身はどのようになっているのかを示すよう求めました。","respondent":"冠木指導課長","answer":"そういったことのないように、十分に指導の内容を徹底していきましょうというのが、この研修会の内容です。これは１回にとどまらず年間に繰り返し、実施することによって、指導を徹底していきたいというふうに思ってあります。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"もうちょっと研修内容を具体的に教えていただきたいと思うんですけれども、左足がここみたいな、そんな程度の説明だったんですよね。そういったことを、どの程度のどれぐらいの時間をかけてやっていくのか、もう一度説明を求めました。","respondent":"冠木指導課長","answer":"そういった意味合いの中で、子どもたちが安全に授業を受けていただけるように内容について指導していくという研修会です。それは当然実技ですから、写真にあるだけではなくて実際にやってみるという研修会です。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"不安を抱えたままお互いがやるのでは、そういった精神なども養われないと思うので、もう一度研修の時間とマニュアルなんかもあるんですよね。そういったものもあれば説明を求めました。","respondent":"冠木指導課長","answer":"回数を増やして、できるだけ多くの方に参加していただけるようなことで、指導の体制をとっていきたい。やはり１人で指導するということでは不安が残るというお声も聞いておりますので、必ず複数体制で指導をするということで指導の徹底をしています。","id":"exchange-032"},{"speaker":"渡辺委員","kind":"質問","question":"私は３４９ページ、３４７ページ、３３５ページの中学校進路指導費のところで伺います。あれば、その割合、そして特に顕著なケースをどのように把握されているのか、まず伺います。","respondent":"齋藤庶務課長、冠木指導課長","answer":"今、委員からご指摘がありましたが、雪の関係で学校の校庭が使えずに授業に影響があった学校があるというふうには聞いておりません。 この２月、３月、東京も雪がかなり降りまして、校庭の利用を自粛したという報告は聞いております。授業ができなかったというようなスタンスではございません。","id":"exchange-033"},{"speaker":"渡辺委員","kind":"質問","question":"予算額でいうと学校の校庭の全改修に比べたら１０分の１、２０分の１で、上層部だけ定期的に手を入れられているように思います。本来やはり体験すべきこと、その点、全体像としての考え方も説明を求めました。","respondent":"齋藤庶務課長","answer":"中規模、小規模ですが、表層土の部分的な取り替えは５年程度いろいろ状況を見ながら行っております。学校の校長、学校にも令達している予算もありますので、十分学校と調整しながら整備を進めてまいります。","id":"exchange-034"},{"speaker":"渡辺委員","kind":"質問","question":"次に、学校ホームページ経費と、合わせて学校別パンフレット作成で伺いたいと思います。１校当たりの経費と用途をまず聞きたいのと、１校当たりの経費、そういうことがあれば説明を求めました。","respondent":"和氣学務課長","answer":"まず最初に導入するところで２８４万円ほどかかる予定ですが、今、順次そこをかえていきたいというふうに考えているところです。地域や町会の方にお配りをしたり、各学校それぞれで対応しているところでございまして、私どもで詳細には把握してございません。","id":"exchange-035"},{"speaker":"渡辺委員","kind":"質問","question":"パンフレットのほうなんですが、１３万円の予算という基準があるにしても、これは差がどうしても出るところかなと感じています。ちょっとこう深入りというんですか、あるいはこれからの拡充、拡大の必要性を伺いたいと思います。","respondent":"和氣学務課長","answer":"これは各ページ１ページずつで構成されているもので、どうしても限られた情報になってあります。この辺はまた学校とも相談しながら拡充を図ってまいりたいというふうに考えてあります。","id":"exchange-036"},{"speaker":"渡辺委員","kind":"質問","question":"次の項目の中で、中学校の進路指導費のところ、この１２９万円余の予算の内訳、あとは制度の仕組みを簡単に伺いたいと思います。","respondent":"冠木指導課長","answer":"特に９年生ですけれども、相談員の謝礼をお払いしたりということで、この予算計上になっているところです。","id":"exchange-037"},{"speaker":"渡辺委員","kind":"質問","question":"というのは１つの学校の中で、進路指導の主任の方、責任者の方がいらっしゃる。何もデータベースがどうのこうのではないんですが、高い能力を共有する手段として、お考えはいかがか尋ねました。","respondent":"冠木指導課長","answer":"それを上手に子どもたちあるいは保護者に伝えていくというのは重要なことだと思ってあります。あるいは地域の方であれば、より広い協力者の方々に、子どもたちのためにご活躍いただければありがたいなと思っているところです。","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問","question":"それから３４７ページのインターネット通信経費でいいのかどうか、インターネット等の学習関係についてちょっとお伺いしたいと思います。この体制が２名から１名と減っていく中で、どのように変わったところがあるのか、この点についてまずお伺いしたいと思います。","respondent":"和氣学務課長","answer":"例えば指定校変更制度１つで見ますと、平成２３年度は１３７人、逆に少なかったりもしています。安全の問題であったり、あとは自分の子どもの教育上の配慮の問題であるとかさまざまありますが、一番多いのは指定校変更です。","id":"exchange-039"},{"speaker":"塚本委員","kind":"質問","question":"いろいろな形で気になるということで、グレーゾーンというか、そういう方々も含めて非常に増えてきているのではないかと思います。その辺の相談の状況、また児童のそういう不安を抱えるお母さんたちの人数の増加というところについての認識をお伺いしたいと思います。","respondent":"和氣学務課長、冠木指導課長","answer":"近年、そういった相談、なかなかお子さんが集団生活についていけないというご相談もあります。今度は指導課の特別支援係のほうの相談につなげたり、まず私どもが窓口になった上で、次の段階へという形で進んでいるところです。 ９４件、９３件、１０３件ということで推移しております。あるいは特別支援学級に入られる方、私どもの課のカウンセラーであるとか、その後の学校生活をサポートしています。","id":"exchange-040"},{"speaker":"塚本委員","kind":"質問・要望","question":"大変に、相談をされた親御さんからの話では、なかなかやはりもうちょっと要望に沿った形でというような話も時々聞くことがあります。一層充実した体制の拡充でありますとか、あるいはより専門性のあるところへの連携ですとか、そういったことはどのようにお考えになりますか尋ねました。","respondent":"冠木指導課長","answer":"私ども１００件を超える相談をしておりますと、すぐ私どもの考え方と、お母様の考え方が一致するというのは全体の６０％程度です。それ以外の４０％のお子さんについては、最終的に４月の就学先を考えていくというような状況です。","id":"exchange-041"},{"speaker":"塚本委員","kind":"質問","question":"今後とも取り組みのほうをよろしくお願いしたいと思います。習得を目指している学習目標というんですか、どういうパソコンのスキル的なものというのを学習目標として、その辺をちょっと説明を求めました。","respondent":"冠木指導課長","answer":"子どもたちに、リスクは回避できるような資質能力を育てる、よいものはきちっと自分の考え方に基づいて使い込んでいくというような指導をしていく。そういうようなところを市民科の年間計画の中で実施しています。","id":"exchange-042"},{"speaker":"塚本委員","kind":"質問","question":"そういうことで、宿題を解いたりするときに、インターネットを使ってぱっぱっと答えを得てしまうというようなこともあるかもしれません。いわゆる教育の中でいろいろなことを知を育むということで教えていくという中での利用の節度というんですか、ちょっとお聞きしたいと思います。","respondent":"冠木指導課長","answer":"インターネットについては１つのツールだという考え方をしていかないと、のめり込んでしまったり、その弊害が大きくなってくるのかなと思います。","id":"exchange-043"},{"speaker":"塚本委員","kind":"質問","question":"もうちょっと詳しくお聞きしたいんですけれども、いろいろな情報を得て使っていく、こういうことは実際にはやっていらっしゃるのですか。それとも学校の中ではやらないのか尋ねました。","respondent":"冠木指導課長","answer":"学校の中でも、技術家庭科だけにとどまらず、数学や理科においてもそういった授業は行われております。","id":"exchange-044"},{"speaker":"塚本委員","kind":"質問・要望","question":"小学生たちは本当に大人が感心するような内容を発表されていました。正しい利用、有益な活用ということにしっかりと方向を導いていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"木村委員","kind":"質問","question":"この授業は本来の授業にない授業と解釈していいのでしょうか。このことは、この授業の回数がこれから増えるということを意味することでしょうか、お願いします。","respondent":"冠木指導課長","answer":"特に品川区が実施している目玉の授業でございまして、ぜひ私どもとしても地域の力をお借りして子どもたちを育成したいという思いでつくった授業です。","id":"exchange-046"},{"speaker":"木村委員","kind":"質問・要望","question":"そして日本舞踊というようなことがありましたけれども、それ以外のことが何かありましたら、また教えていただきたいんですけれども。それからお願いします。","respondent":"冠木指導課長、齋藤庶務課長","answer":"その種目のご専門の方に来ていただいて、野球であるとか、サッカーの専門の方に来ていただいて行う授業などもこの中に入ってくるところです。お医者様においでいただいて、歯科衛生の授業をしてもらうとか… すまいるスクールでは伝統文化についての教室を持っております。こういった講座を年間で１,３４３回実施しておりまして、小学生の方、延べで２万１,７３０人の児童が学んでいるです。","id":"exchange-047"},{"speaker":"木村委員","kind":"質問","question":"そういう意味で何か特殊な職業の方、また変わった経歴の持ち主などがいましたら、説明を求めました。","respondent":"冠木指導課長","answer":"ヤクルトの古田選手もおいでになったような記憶が私はあるのですが、そういうところで学校の子どもたちに専門家の経験であるとか、技術を見せていただくという授業をやっておりました。","id":"exchange-048"},{"speaker":"木村委員","kind":"質問","question":"子どもたちにしてみれば、さまざまな職業の体験談や、また経験話が聞けるわけですから、大変興味深い授業になると思います。その講義というんでしょうか、また全員で話し合って反省会というんでしょうか、説明を求めました。","respondent":"冠木指導課長","answer":"６年生に料亭をやっていらっしゃる板前さんに学ぶ授業というものを実施いたしまして、板前さんの技や、そういった感想が多く集められております。２年生では、非常に子どもたちが、実際に体験してよくわかったというような報告なども受けているところです。","id":"exchange-049"},{"speaker":"木村委員","kind":"質問・要望","question":"社会に出て恥ずかしくない礼儀作法を教えてくれる学校、また親になり代わってしかってくれる学校、これも十分特色のあることだと思います。今後品川区の子どもたちには、心身ともに成長できる教育、あらゆることに対して社会に貢献できるように頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"渡部委員","kind":"質問・要望","question":"学校給食費のところで伺っていきますが、中学校合わせますと１１億８,０００万円余ですか、ここでお伺いしたいのは。調理師のＯＢの方ですとかを配置するということだったんですが、その方々、どこに含まれていて何人いらっしゃるのかというところを説明するよう求めました。","respondent":"和氣学務課長","answer":"調理代行をする中で、来年度は２３人の配置を予定をしておりまして、そちらのほうで記載されているというふうに考えております。消火器を使う訓練であるとか、実際に消火器の位置を確認して、いつどう動くかを含めて、かなり頻度高く訓練をしていただいているところです。","id":"exchange-051"},{"speaker":"渡部委員","kind":"質問","question":"今ほかの部分の問題で食の安全が言われていますが、根本はそこだと思いますので、しっかりお願いしたいと思います。今伺いました１１ブロックで９社、これは１社当たり１億円以上の契約案件ですが、その辺をちょっと説明を求めました。","respondent":"和氣学務課長、阿部経理課長","answer":"各ブロックごとに契約していますので、１億円を超える契約があれば、もちろん報告はしていると思います。 議会への報告案件の中に、委託は含まれておりません。今回は委託ですので、議会への報告はしてございません。","id":"exchange-052"},{"speaker":"渡部委員","kind":"意見","question":"これから先も続けていくという中で、細かい数字を追っているわけではないのですが、ざっくりで結構です。今までで直営でやっていたときと比較して、これから先、どのようなメリットがあるのか、お教えほしいと求めました。","respondent":"和氣学務課長","answer":"ざっくりですが、これまでずっと委託にしてきて約２０億円の削減効果がございまして、平成２４年度以降は毎年４億８,０００万円ほど削減効果を見込んです。","id":"exchange-053"},{"speaker":"渡部委員","kind":"質問・要望","question":"時間が余ったので、１件お伺いしたいと思います。できれば全校でかぶってほしいなと思うんですが、いかがか尋ねました。","respondent":"和氣学務課長","answer":"詳細には把握してございませんが、数校ない学校がございまして、最近またつくる傾向もありまして、この間、ＰＴＡに全小学校の制帽一覧というパンフレットをつくっていただいたのですが、その中で数校だけ、ない学校がありました。","id":"exchange-054"},{"speaker":"渡部委員","kind":"意見","question":"まだ数校ない学校がやはりあるんですね。地域にとってもいいですし、これっていいことがいっぱいあるなと思っていましたので、ちょっと聞かせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"原委員","kind":"質問・要望","question":"どういう人たちなのかというのを教えていただきたいということ、３５１ページ、図書館ですね。品川区総合実施計画の第２次の真ん中ということで、広い意味で、図書館についてお伺いしたいなと考えています。","respondent":"冠木指導課長、中元品川図書館長、和氣学務課長、齋藤庶務課長","answer":"私のほうからは、まず外国人英語講師による学習指導ということで、状況を説明します。なお、単価につきましては… 来館者の数ですが、この中で、一番多いところはやはり規模が大きい品川図書館になります。数字でいいますと品川図書館が４６万４,６０１人… 中学校は平均しまして１万１,０００円、ここも安いところでは９,０００円で、高いところで１万６,０００円というところがあります。… 耐震改修工事の設計と委託ですが、５年に１度、プロポーザル方式で１社に決めております。","id":"exchange-056"},{"speaker":"原委員","kind":"質問・要望","question":"これが今後の品川区において、かなりのステイタスとかクオリティとか、そういう面においてプラスになってくるのではないかなと思うものですから。ですからそれは教育委員会だけではなくて、当然、その辺についてのご意見をほしいと求めました。","respondent":"中元品川図書館長、齋藤庶務課長","answer":"現在大井町行政サービスコーナー、武蔵小山行政サービスコーナーのほうも、他区の方ももちろん利用されているところです。そういうようなことができる場所とか人員等の部分が整いましたら… ガラスの耐震改修工事につきましては、設計とも監理委託とも同一の業者です。","id":"exchange-057"},{"speaker":"原委員","kind":"質問・要望","question":"一緒の流れであるわりには、逆にこの単価というのは安いのかなという、僕は別々だと思ったものですから。やはりどんどん外国の方も来られる、それからどうしても場所場所によって限定、ぜひとも駅のそばに考えていただきたいなという思いがあるんですね。","respondent":"中元品川図書館長","answer":"繰り返しになりますが、もちろん駅の近くでとすると、なかなか地価の高いこともありますし、そういう場所が本当に確保できましたらということで研究させていただきたいと思います。","id":"exchange-058"},{"speaker":"金野委員","kind":"質問","question":"３３７ページのまちの人々に学ぶ授業経費、あるいは３３９ページの特色ある教育活動経費という、この２つのところから２点お伺いいたします。２つこのことをお聞きいたしますが、この事業はどういう補助金なのか、詳しく内容と目的を示すよう求めました。","respondent":"冠木指導課長","answer":"この教育研究奨励等補助金というのは、キャリアアップしたいかというような視点で、いろいろ先生方は研究したいなという思いがあります。そういった先生方の需要に対応するために私どもで事業をつくりまして、団体でいうと２団体ぐらい、つけているところです。","id":"exchange-059"},{"speaker":"金野委員","kind":"質問・要望","question":"これらの研修は現在どのように行われているかということをお聞きしたいんですけれども、しているものなのか、具体的にご紹介ほしいと求めました。合わせて生活指導面という、こうした研修はどのようにされているのか示すよう求めました。","respondent":"冠木指導課長","answer":"この生活指導主任については毎月１回研修会、全学体の場を設けて研修をし、各学校の情報交換であるとか関係諸機関との連携などの研修をしています。","id":"exchange-060"},{"speaker":"金野委員","kind":"質問","question":"現状よくわかりました。この研修会のあり方というか充実についてお聞きしたいんですけれども、その課題があった場合、その辺を簡単で結構です。","respondent":"冠木指導課長","answer":"特に、先ほど主催者というお話もありました。あるいは民間に委託するという方法はないものだろうかと、さまざまな形を検討しながら、それぞれの研究会が実を上げるように毎年検討しています。","id":"exchange-061"},{"speaker":"金野委員","kind":"質問・要望","question":"こうした能力というんでしょうか、資質というところを高めていただくことも必要ではないかなと、このように考えております。より一層続けていただきたいですし、そうでなければ、こういうものを取り入れていくというお考えはいかがか尋ねました。","respondent":"冠木指導課長","answer":"先ほど申し上げましたけれども１０年経験者研修の中でこうした事例研修をしています。今のお話、十分にわかりますし、これは子どもたちにとって重要なことだと思いますので、さらにそういった取り組みを進めてまいりたいと思います。","id":"exchange-062"},{"speaker":"金野委員","kind":"質問・要望","question":"それが働く楽しさなんだというところも教えていらっしゃるという声を、東京寺子屋で、教えていらっしゃる方からも伺いました。ですので、これは本当にいい授業ですので、さらにいい授業として全校で展開をしていってほしいと求めましたけれども、いかがか尋ねました。","respondent":"冠木指導課長","answer":"既にこれは全校で取り組みをしておりまして、今、順番にやっているところでございまして、このままやっていきたいと思います。","id":"exchange-063"},{"speaker":"吉田委員","kind":"質問","question":"３４９ページの校務費の中に入ると思うんですけれども、防犯ブザーについてお伺いいたします。ここで質問なんですけれど、中学生の防犯ブザーの所持率はどのくらいでしょうか、それをお伺いしたいと思います。","respondent":"和氣学務課長","answer":"持っている子は５６.４％ということで、学校を通じて所持するよう指導に努めているところですが、なかなか数字が上がらないというのが現状です。","id":"exchange-064"},{"speaker":"吉田委員","kind":"質問","question":"その中に、紛失や破損したものは入っているのでしょうか。校務費のほうで出していただけるのか、それと、この現状をどのように思われるかをお願いします。","respondent":"和氣学務課長","answer":"紛失した場合には、もちろん厳しく指導をした上で補てんをしているです。私どもとしましては学校を通じて、せっかく持っていますから、安全を考えて所持してほしいということを繰り返し指導しています。","id":"exchange-065"},{"speaker":"吉田委員","kind":"質問","question":"この間、警察の方にお伺いしたんですけれども、本当に怖い場面ではなかなか声が出せない。その辺どのように工夫なさっているのか、ご存じだったら説明を求めました。","respondent":"和氣学務課長","answer":"それからかごを購入されて、グループごとにそのかごに入れて近くに置いている。そんな形で、すぐにヘルメットをかぶれるという態勢をとっているというふうに聞いております。","id":"exchange-066"},{"speaker":"吉田委員","kind":"質問","question":"先ほど午前中にも何件かご質問がありましたが、５０社から７０社、多くは１００社以上受ける就職難と毎年毎年言われております。それをお聞きしまして、では、これから他の学校に具体的に、いつからこういうものを広げていらっしゃるのかを、ぜひお伺いしたいと思います。","respondent":"冠木指導課長","answer":"これを今度は自分の考えを持って表現をするというところまで私どもは力をつけていかなければいけないというふうに思っております。そういった意味で、この小中一貫の取り組みの中で、英語力のアップということを考えていくところです。","id":"exchange-067"},{"speaker":"吉田委員","kind":"意見","question":"具体的にありがとうあります。年間２４回という模擬授業とヒアリングということで、またはどうも若い層の方が英語が堪能でいらっしゃるとか、具体的にその辺もお教えくださいとの意見を述べました。","respondent":"冠木指導課長","answer":"英語力については特に注意してみて、品川区においでになる先生については、そういうようなところを気をつけているというのが１つあります。それから、回数を増やすということではなくて、ポイントを絞ってウイークポイントをなくすという方向でやっていきたいと思ってあります。","id":"exchange-068"},{"speaker":"大倉委員","kind":"質問・要望","question":"私は、３３３ページの区教員経費について、関連していろいろお聞かせほしいと求めました。今で４年目ですか、そこでどういった成果といっていいんですか、ちょっとできれば具体的に教えていただきたいのと。","respondent":"冠木指導課長","answer":"そういうようなところで、１期生５人についてはそれぞれの学校で、非常によく品川区の方針を理解し、その上で、お力を発揮し始めているです。なお、３期生につきましてはまだ１年目ですので、まだまだこれから育成をしていきたいというふうに思ってあります。","id":"exchange-069"},{"speaker":"大倉委員","kind":"質問・要望","question":"これは今になって事業として出てきたのか、その理由を教えていただきたいのと、この資質・能力というのはどういったことを指しているのでしょうか。それを合わせて教えていただいて、区としてどういう資質・能力が必要だと考えていらっしゃるのか、教えてほしいと求めました。","respondent":"冠木指導課長","answer":"１年、２年経ちまして、そしてさらにそれを発揮する状況になってまいりました。今度はその先生方に、それから私どもの集中研修会を実施いたしまして、学習をしていただくような研修を考えているところです。","id":"exchange-070"},{"speaker":"大倉委員","kind":"質問・要望","question":"これはちょっとどこに入っているかわからないんですけれども、これもプレスにあるんですが、土曜日授業の実施のところでお伺いしたいと思います。生徒側のほうの課題、問題さまざまあると思うんですが、ちょっと教えてほしいと求めました。","respondent":"冠木指導課長","answer":"多い学校でもかなりの回数で実施をしていた。半日１７回というのを出させていただいたのですけれども、地域の協力も得られやすくなるというような考え方をもって、土曜日の授業を実施をするです。","id":"exchange-071"},{"speaker":"大倉委員","kind":"質問","question":"１点だけ、小学校、中学校、スクールゾーンについてちょっとお伺いしたいと思います。今どういった問題があるのか、警察との連携はどういうふうにとられているかという部分を教えてほしいと求めました。","respondent":"齋藤庶務課長","answer":"第１、規制を法的安定性という部分でいうと、ドライバーがなかなか確認しにくいということで難しいというふうに言われております。区としては交通安全指導員を土曜日も配置するなど、万全な体制をとるように今努めているところです。","id":"exchange-072"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひしっかり要望していただいて、小学生が安全に通学できる道を確保してほしいと求めました。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"大沢委員","kind":"質問","question":"最初に３５４ページの学校施設建設費から伺わせていただきます。練馬区の小中学校の検査済証の問題がありましたけれども、品川区は現状どうなっているか説明を求めました。","respondent":"宍戸施設整備課長","answer":"当区では全く問題なく、検査済証を全件取ってあります。","id":"exchange-074"},{"speaker":"大沢委員","kind":"質問・要望","question":"よかったと思います。あるいはほかのどのような運用がされて、そのような工事がなされているのか、教えてほしいと求めました。","respondent":"宍戸施設整備課長","answer":"そのようなときにも、仮使用という手続を取りまして、適法に手続を取りながら進めているところです。","id":"exchange-075"},{"speaker":"大沢委員","kind":"質問","question":"これはもうそれだけしか聞きようがないので、これでこの質問は終わります。これはその中の予算で行われるということで理解をしてよろしいのか尋ねました。","respondent":"冠木指導課長","answer":"その中で、研修はもちろんですけれども、すべての教育活動において、子どもたちにとってわかりやすい授業、わかりやすい指導をしていきたいです。そんなところで、私どもはプラン２１の中に、この言葉の達人ということで、今回予算措置をさせていただいたところです。","id":"exchange-076"},{"speaker":"大沢委員","kind":"質問・要望","question":"これはやはり行政は、課長たちは課長たちの答弁のスタイルがあるだろうと思いますし、これはいいとか悪いとかの話ではありません。先生方はいろいろとプラン２１の中で教えるに当たって、先生方はどのような体制で先生方の研修を行っていくのか、聞かせてほしいと求めました。","respondent":"冠木指導課長","answer":"わかりやすい説明に徹したいと思いますけれども、今回の言葉の達人ということで研修を実施するに当たりまして、こんな考えを持ってあります。","id":"exchange-077"},{"speaker":"大沢委員","kind":"質問・要望","question":"各先生方のステージに応じながら、さまざまな部分で会話を交わすには、言葉というものがまず第一の入り口になってくるのではないかと思うんです。そういうものを駆使するような手だてというか、今の研修の中で施されるようなお考えはおありになるのか、ちょっと教えてほしいと求めました。","respondent":"冠木指導課長","answer":"自分が考えていること、ある程度話術が巧みになったとしても、それは実際に伝わらないということになってしまう。ですから、この研修会につきましては、そういったところも含めて考えているところです。","id":"exchange-078"},{"speaker":"大沢委員","kind":"質問","question":"携帯電話とか書くよりも、キー１本で変換をしてやる作業のほうが当たり前のようになってしまうのが今後主流になってくるのではないかと思います。国語という範疇ではなくて、英語と対価として日本語という１つの単元も必要だと思うんですけれども、そこのところをどういうふうにお考えか尋ねました。","respondent":"冠木指導課長","answer":"今の若手の先生方は、さっと携帯を出して、ちょっと変換をしてみて判断をするというような思考回路になっているというような事例もあります。これはもちろんベテランもでございまして、十分にそういったところをつけていく、指導をしていきたいというふうに思ってあります。","id":"exchange-079"},{"speaker":"高橋委員","kind":"質問・要望","question":"そういうことなどを含めた検証のプロジェクトというんでしょうか、検証の計画というんでしょうか、そういうものについてお話しください。改善していただきたいという声が、平成２４年度の改修の予定があれば、ご説明をほしいと求めました。","respondent":"冠木指導課長、齋藤庶務課長","answer":"一つ検証はできているのかなというふうに思ってありますが、さらに今度入ってくる７年生については、小学校１年生から英語を実施しております。これは私どもが習熟度別学習、特に算数等について力を入れているところでございまして… 浜川小学校の体育館につきましては、学校からもＰＴＡからもご要望いただいております。来年度の夏季、夏休みに工事として対応を考えております。","id":"exchange-080"},{"speaker":"高橋委員","kind":"確認","question":"ですから、この区費がなければ、一人ひとりの先生が３クラスに１人ずつついていて、それで終わっている。区費の先ほどの９２名の先生方がいらっしゃるおかげで理解がかなり進んでいるというところをちょっと確認したかったんですけど。","respondent":"冠木指導課長","answer":"委員のおっしゃるとおりでございまして、都費の定数を超えて区費でつけておりますので、３学級を４展開するとか、４学級を５展開するとかというようなさまざまな工夫ができてくると思います。","id":"exchange-081"},{"speaker":"高橋委員","kind":"質問・要望","question":"それからあと、果たして７年生でどうなるかというのは非常に注目されるところで、逆にものすごく先ほど言った９年生よりも力がつくかもしれない。逆に言うと、その成果をもう少し見る方法があると思うので、その辺についてお願いします。","respondent":"冠木指導課長","answer":"９年生、そういう考え方で設計をしておりますので、これを上手に組み合わせることによって行っているです。７年生のところで力を少し見てはどうかというご提案ですけれども、７年生の調査については少し検討させていただきたいというふうに思ってあります。","id":"exchange-082"},{"speaker":"高橋委員","kind":"質問","question":"これだけすばらしい教育を行っているのですから、検証結果を出すことによって、さらにそれが証明されて、またさらに次の小学校の英語の教育につながっていくと思いますので、ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"南委員","kind":"確認","question":"３３７ページ、プラン２１推進事業についてお尋ねしたいと思います。すべての子どもに学ぶ喜びを体得してほしい、教育目的の一つなのかどうか、ちょっとその辺をまず最初に確認したいと思います。","respondent":"冠木指導課長","answer":"子どもたちが社会的な適用をしていくとともに、心理的な適用もしていかないと子どもたちは育っていかないということはわかっていることです。自己肯定感は非常に重要な柱と思ってありますので、これは私ども小中一貫以前の保幼小の段階から力を入れているところです。","id":"exchange-084"},{"speaker":"南委員","kind":"質問・要望","question":"この教育行政、各学校での教育に当たっておられるのか、そのあたりをしっかり伺っておきたいというふうに思っています。その辺についての説明も伺いたいし、全部５０分授業なのか、あるいは４５分なのか、ちょっとその辺を教えてほしいと求めました。","respondent":"冠木指導課長","answer":"５年生というお話でしたので、５年生ぐらいになって、それぞれが進化してまいります。通常４５分で実施をしておりますが、５、６年生のところで５０分授業を実施しているという学校はあります。","id":"exchange-085"},{"speaker":"南委員","kind":"質問","question":"小学校５年生以上になったら、教科担任制になっているわけですよね。この教科担任制のメリット、デメリットはどういうふうに見ているのか、ちょっとそこも説明を求めました。","respondent":"冠木指導課長","answer":"私は理科なんですけども、より専門的な授業ができるという意味では間違いなく大きなメリットがあります。教科担任制というのは、非常に有効な手段だと思ってあります。","id":"exchange-086"},{"speaker":"南委員","kind":"質問・要望","question":"それはこの間長い教育行政の中で、品川に限らずやってきているわけですから、特に中学校ではそういう教育をしているわけですから。それについてはいかがか尋ねました。","respondent":"冠木指導課長","answer":"そういう話ではありませんので、今のような学級担任がもしいるのであれば、私は指導の対象だというふうに思っています。そういうことで、学級担任のデメリットはあるんですけれども、教科担任のデメリットは私はないと考えております。","id":"exchange-087"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だけれども、今度校舎改築をするとなると、子どもたちに対して擁壁の部分の対応をどこかでとるわけでしょうから、そのことだけは教えていただきたい。それから図書館なんですが、図書館、今行政側でやっているこの位置づけを簡単に教えていただきたい。","respondent":"吉岡保育課長、齋藤庶務課長、中元品川図書館長","answer":"私立幼稚園はそれぞれ設置者、おのずから区立と私立の差、あるいは私立の中でも違いがあろうかなというふうに思ってあります。… もう一つは、壁面の３分の１しか区の持ち物がございませんので、本来であれば、がけ地の上の方が養生すると、これが基本です。そういった面も含めまして… 品川区におきましては、品川区立図書館設置条例というものに基づきまして、行政のほうで置かせていただいているところです。","id":"exchange-088"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そういうふうに受けとめる保護者もいるので、そういうのは一考していただきたいと思うんですが、どうお考えになっているかということです。そうすると、単独公立幼稚園の役目、これをもう一度改めて教えていただきたい。","respondent":"齋藤庶務課長、中元品川図書館長、吉岡保育課長","answer":"具体的な動きとしては、宮古市の支援のＴシャツをつくって、３回、４回と現地にも行っていただいております。… 生涯にわたる区民の方の学習活動を支援することを目的としておりますので、委員おっしゃったご提案は大変すばらしいものだと思います。… 私立幼稚園１９園に対して、区立幼稚園は９園ですので、数量的にはやはり補完の役割だろうというふうに思ってあります。","id":"exchange-089"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"こういうところを踏まえて、しっかりこういう特色があるというところを、出していくべきだ。だから、総花的と言っているんだけれども、私はこれを読んでいて、そこら辺の考えをもう一つ教えていただきたい。","respondent":"吉岡保育課長","answer":"再度お答えいたします。今徐々に５歳児のジョイント期にはもう昼寝しないという方針でやっておりますので、保育園を目指してまいりたいというふうに思ってあります。","id":"exchange-090"},{"speaker":"稲川委員","kind":"質問・要望","question":"それも教えていただきたいんですが、３３７ページのまちの人々に学ぶ授業経費、品川区の小中一貫教育要領の中の音楽科についてです。特に教員に対しての音楽指導というんでしょうか、そういう部分についてお伺いをしたいんですが、音楽指導をする先生がおります。","respondent":"冠木指導課長","answer":"１つは、私どもの教育センターが行っている音楽の実技研修でございまして、今年度については２回実施をしております。それからもう１つ、音楽の先生方が研究をしている教育会というのがありますので、そちらのほうでも研修会を実施しているというふうに聞いております。","id":"exchange-091"},{"speaker":"稲川委員","kind":"質問","question":"これを見ると、本当に後半の学年、第９学年でしょうか、週１回になっているところです。民謡や長唄を教える際の教員の勉強会ですか、長唄はその道のプロというんでしょうか、区のお考えを説明するよう求めました。","respondent":"冠木指導課長","answer":"今回の研修会の一部にも、ぜひそういったお力添えをいただいて、私どもの音楽教育をさらに伸ばしていきたいなというふうに思っているところです。","id":"exchange-092"},{"speaker":"稲川委員","kind":"質問・要望","question":"ちょっとあわせてお伺いするのを忘れたんですが、これは委員長に許可を取ってあるんですが、こういった民謡指導マニュアルというのがあります。地域の優れた人材を活用する、教員に対して指導していくということも大切だと思うんですが、お答えほしいと求めました。","respondent":"冠木指導課長","answer":"それから小返しというんでしょうか、繰り返し学習をしていく部分、非常に有効な指導書だなというふうに思ってあります。そういった部分で地域の力をお借りできるというのは非常にありがたいところですので、そういった意味でも活用してまいりたいというふうに思います。","id":"exchange-093"},{"speaker":"稲川委員","kind":"質問・要望","question":"裏にＤＶＤもついておりますので、ぜひこれを参考にしてほしいと求めました。第５学年から第９学年、評判というんですかね、そういう場があるのかどうか説明を求めました。","respondent":"冠木指導課長","answer":"非常に子どもたちは姿勢よく取り組んでいて、短い時間ですので、そういった意味合いでやってよかったという校長からの声もございました。区全体としてその取り組みはありますけれども、それ以外の部分においても地域のお力をいただいて、音楽の授業を進めているです。","id":"exchange-094"},{"speaker":"稲川委員","kind":"質問・要望","question":"多分ここで第９学年、中学を卒業したら、もしかしたら夏季留学する方もいらっしゃると思いますし、語学研修に行く子どもたちもいると思います。その中で、ぜひこの教育に関しては、今後も力を入れていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"山元委員","kind":"質問・要望","question":"これは改めてＣＡＰですかね、教えていただきたいということと、実際にどのようにやっているのか。そして、品川区としてはいつからこの事業をスタートさせたのか、その辺も教えてほしいと求めました。","respondent":"冠木指導課長","answer":"ごめんなさい、平成１７年度から実施をしております。そういったところで、３年生、５年生向けということで、平成１７年度から実施をしています。","id":"exchange-096"},{"speaker":"山元委員","kind":"質問・要望","question":"ＰＴＡというのは、あくまでも保護者の方を対象にやっていらっしゃるんでしょうか。それ以外の方たちというのはどうなのか、その辺もちょっと教えてほしいと求めました。","respondent":"齋藤庶務課長","answer":"ＰＴＡでも家庭教育学級ということで、ＰＴＡに委託をして、ＣＡＰの授業をやっております。保護者、それと子どもを対象にして実施しています。","id":"exchange-097"},{"speaker":"山元委員","kind":"質問・要望","question":"平成１７年から結局六、七年経つんですかね。その成果というんでしょうか、あと現場的にどういうふうな状況、その辺も教えてほしいと求めました。","respondent":"冠木指導課長","answer":"これをあわせて指導することによって、子どもたちが暴力を放棄するというような考えを将来的に持っていってほしいなという考え方です。そういうようなところでいろんな課題がありますけれども、そういうようなところにつながらないような市民をつくっていきたいです。","id":"exchange-098"},{"speaker":"山元委員","kind":"質問","question":"先ほど３年生と５年生が対象ということで、障害の子たちとか、それから例えばもうちょっと年齢の低い子たちを対象にというのはどうなんでしょうか。お考えはあるんか尋ねました。","respondent":"冠木指導課長","answer":"先ほどちょっとお答えいたしましたけど、５年生というふうに、そして保護者にも意識を持ってもらってというやり方をしております。特別支援教育にかかわるお子さんも一緒に受けておりますので、３年生、５年生においては一緒にやっております。","id":"exchange-099"},{"speaker":"山元委員","kind":"質問・要望","question":"この中で文面的に一つちょっと確認をしたいんですが、原則的に第１・第３の土曜日、あくまでも変更があるのかなということが一つ。これはどういうことなのか、この辺を教えてほしいと求めました。","respondent":"冠木指導課長、和氣学務課長","answer":"そういったことで、今まで地域が取り組んでこられたそういった状況もありますので、その辺は柔軟に対応してまいりたいというふうに思っております。原則は１７回、第１、第３ですけれども、そういった部分については、対応しているです。 授業公開を午後にやりましょうという場合に関しては、１日になりますので給食を出してもいいということで、基本的には３回までという制限をかけて実施をしていただくということになってあります。","id":"exchange-100"},{"speaker":"山元委員","kind":"質問・要望","question":"それからもう１個、ごめんなさい。いろいろたくさん書いてありますが、現場的にこの４月からこれは実行されるんですが、その辺の現状を教えてほしいと求めました。","respondent":"和氣学務課長、冠木指導課長","answer":"基本的に全校で授業をやる、午後も何か行事をやるという場合のみに限ってあります。部活は弁当を従来どおり用意していただきたいと思います。 土曜日実施につきまして、さまざまな対応が必要になってくると思います。それから学習支援員の問題について、調整は済んでおりますので、４月からの実施に問題はございません。","id":"exchange-101"},{"speaker":"伊藤委員","kind":"質問","question":"簡単に３.１１を経験した岩手県釜石市、これは３,０００人の小学生、中学生のほぼ全員が津波災害から逃れることができたということ。例えば、こういうことを前提として、小中一貫した防災教育のカリキュラムを品川区で検討してみてはどうでしょうかという点が一つ。","respondent":"冠木指導課長","answer":"そういったところでどういうふうな対応をしたかということについては、この３月に各学校にそれぞれの学校はどうしたかということを発信しております。そういうものを総合した形で、学校で、では何ができるのかというふうな形で提案をしていくという考えでおります。","id":"exchange-102"},{"speaker":"伊藤委員","kind":"質問","question":"子どもたちがいざそういう災害に遭ったときに、正しい意識を自分で判断して、自主的に行動した釜石市はそれが成功例としてあるわけじゃないですか。だから、せっかく３.１１をまさに現地に行って経験された職員もいらっしゃるわけだから、そのことについて答弁をもう一回お願いいたします。","respondent":"冠木指導課長","answer":"子どもたちがみずから考えて、みずから判断できるというような子どもたちを育てていくということは非常に大切なことだというふうに思います。そういった意味で、そういった情報をつぶさに学校のほうに提供いたしまして、防災教育に役立てていきたいというふうに思ってあります。","id":"exchange-103"},{"speaker":"伊藤委員","kind":"意見","question":"その３.１１のことを十分に、学校長の責任になってくるわけだから、そのことについての態勢と考え方をお聞かせください。お願いいたしますとの意見を述べました。","respondent":"冠木指導課長","answer":"目的地までの情報を十分に収集して、移動時間に応じた対応、こういったときにはこういうシミュレーションがあるだろうというようなこともしていく。こういったところを各学校に周知をして、それぞれ来年の校外学習に活かしていただいているです。","id":"exchange-104"},{"speaker":"伊藤委員","kind":"質問","question":"だから、危機管理をするための交番が役に立たなかったということは大きなファクターなわけですから、昨年の３.１１の経験を踏まえ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"西本委員","kind":"質問","question":"もう一つは、３５４ページの学校施設建設費になるんでしょうか。学校は、なぜそういうふうに開示をしていかないのか、するべきなのではないかというふうに思いますが、いかがか尋ねました。","respondent":"和氣学務課長、齋藤庶務課長","answer":"先ほど言ったように、基本的に安全なものが流通しているという認識ですので。それから、福島県からお見えになっている被災者ですが、小学校で１３名、中学校で３名という状況です。 近隣の方の苦情で運動会ができなかったという事例は聞いておりません。学校も一生懸命地域と解決しようと思っているんだけれども、なかなか解決できない、こういう困難さがあるんだというふうに理解しております。","id":"exchange-106"},{"speaker":"西本委員","kind":"確認","question":"先ほどの確認ですが、牛乳を飲まない１７７人とありましたけれども、これはこの震災の後の数字という理解でよろしいでしょうか。お考えをお聞きします。","respondent":"和氣学務課長、齋藤庶務課長","answer":"これだけ安全につくっていますから、食べていただきたいという啓発はしておりますが、強制まではできません。どうしても持ってくるということであれば、強制までできませんので、その子たちが浮かないように努力をしています。 そのたびに学校の関係者や地域の関係者は何度も何度もお願いをしているけれども、なかなか解決しない。そういう意味では、学校はとても頑張っているというふうに考えております。","id":"exchange-107"},{"speaker":"西本委員","kind":"質問・要望","question":"給食の件ですが、安全な食材で給食、そして給食の教育というのも大切ですよということをしっかりと伝えていただきたいというふうに思っています。前のところになるという復帰の見通しを最後にお聞きします。","respondent":"和氣学務課長","answer":"来年度は菅平実施で、再来年度については、来年度中に検討してまいりたいというふうに考えています。","id":"exchange-108"},{"speaker":"井上委員","kind":"質問・要望","question":"私からは、社会教育費、３４３ページの校庭開放経費と図書館経費についてお伺いをいたします。なぜ広い校庭ができたというのに校庭開放をしようとしないのかなというふうに思いましたので、保護者やＰＴＡの役員をされている方に伺いました。","respondent":"齋藤庶務課長","answer":"学校とＰＴＡとのお話につきましては、私は承知しておりませんので、ご説明できません。","id":"exchange-109"},{"speaker":"井上委員","kind":"意見","question":"やっぱり工事中のグラウンドを見て、保護者の方はそうかなというふうに思ってしまわれたということですので、ここのところは説明をお願いしたいと思いますとの意見を述べました。","respondent":"久保田行財政改革担当課長","answer":"日曜日は第一、委員会のほうにもご報告し、議案のほうのご審議もお願いしたところです。やはり地域の少年少女のスポーツ活動にも資していきたいという区の方針もありますので、そういったすみ分けをさせていただいたところです。","id":"exchange-110"},{"speaker":"井上委員","kind":"質問・要望","question":"自分たちの思いは切れてしまっているのかなというふうに思うんですが、校庭開放についてはどういうふうに学校側としては要望を出されているのか、どのように把握をされているんか尋ねました。","respondent":"齋藤庶務課長","answer":"この２年間は工事がありましたのでできませんでしたが、実施されている学校では１日、品川小学校では１０.５人なんです。こういう事業ですので、どのような使い方をするか、やるやらないも含めて今後ＰＴＡの中でも議論がされるというふうに聞いております。","id":"exchange-111"},{"speaker":"井上委員","kind":"質問・要望","question":"今回の３月１１日の広報では、第一グラウンドの６,５００m2ですか、そこについてのお考えをまずお聞きしたい。で、ここはあくまでも学校の校庭という位置づけということですから、子どもの遊び場の環境は確保していただきたい。","respondent":"齋藤庶務課長","answer":"これだけ貴重な土地を７５０人の品川学園の子どもたちだけが独占すると、こういうことはありません。低学年用庭は使うことも検討できますので、これはＰＴＡと今後お話をすると、こういうことです。","id":"exchange-112"},{"speaker":"井上委員","kind":"質問・要望","question":"平日は使えるといっても、子どもたちの授業で、放課後そのまま使えるということではありません。部活にも使うところがあるし、ここの低学年のところは小学校の、慎重に検討していただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-113"},{"speaker":"武内委員","kind":"提案","question":"昨年の第２回定例会でうちの浅野委員のほうから提案させていただきまして、どれくらいで全体が終わるのかと、この辺を教えてほしいと求めました。３月下旬には結論を出すということなんですけども、教科の中に防災科というんですかね、この辺の動きがもしわかれば説明を求めました。","respondent":"齋藤庶務課長、和氣学務課長、冠木指導課長","answer":"非構造部材の調査ですが、まず２段階で考えております。改修の見込みですが、検査をしてみないとわからないです。もしくは物が落ちないようにすることだと考えておりますのと、あと小学生は成長が早くて、どういうものがいいのかというのも大変難しゅうあります。… 国の動きについては私どもも鋭意収集していますので、私どもとしましては、まず基本に市民科があります。","id":"exchange-114"},{"speaker":"武内委員","kind":"質問・要望","question":"ただ、調査結果が出て、万が一危険性があるよという場合には、もう一回私も要望したいと思うので検討してほしいと求めました。どういう形で指示をされているのかなと、その辺、あわせてご見解を説明するよう求めました。","respondent":"宍戸施設整備課長、冠木指導課長","answer":"平成２４年度中に養護施設についても実施いたします。来年度の小中学校等の点検結果、それから国の動向等を踏まえまして、今後の展開については考えていくべきものというふうに考えているところです。１冊の本を読む中で、その中で先ほど申し上げましたけれども、子どもたちの主体的な調べだとか学びを引き出していくと。","id":"exchange-115"},{"speaker":"武内委員","kind":"質問・要望","question":"ただそういう考え方というんですかね、子どもたちを育てる上での考え方、エッセンスというものはぜひくみ取っていただきたいなと。養護施設についてはやられる、それで例えば保育園、幼稚園、ここはどうですか、もう一度、すみません。","respondent":"宍戸施設整備課長","answer":"平成２４年度に幼稚園、それから保育園については点検を実施いたします。","id":"exchange-116"},{"speaker":"武内委員","kind":"質問・要望","question":"はい、わかりました。結果がどうなるかは全然予測がつきませんけども、なるべくスピーディーに改修等を対応していただきたいというふうに要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"},{"speaker":"松澤委員","kind":"質問","question":"５目の学校施設建設費、それと３４７ページ、それと土曜授業の実施についてお伺いしたいと思います。この後、小中一貫校建設は終わってしまうのか、これからまた何かあったらするのか、改めてお聞きをしたいと思います。","respondent":"齋藤庶務課長","answer":"区には小中一貫校６校構想というのがございまして、現時点では新たな一貫校を建設する予定はございません。","id":"exchange-118"},{"speaker":"松澤委員","kind":"質問","question":"わかりました。この３校がなぜ改築しなければならなかったのか、その必要について、また今まで何校ぐらいほかに改築をされたのかについてお伺いしたいと思います。","respondent":"齋藤庶務課長","answer":"Ｉｓ値が０.７必要だという基準がございまして、０.７に至らなかった学校については改築をしております。これまで平成１７年の台場小学校から始まりまして、小中一貫校を含めて１３校の改築をしております。","id":"exchange-119"},{"speaker":"松澤委員","kind":"質問","question":"耐震改築が、耐震化はするけれども、改築年数については二重投資と言わないでいいんだよというような形の中で耐震化を急いできた経緯があります。この３校が終わった後、０.７という数字がクリアしてしまうと、今後の改築計画についてお伺いしたいと思います。","respondent":"齋藤庶務課長","answer":"耐震計画あるいは就学人口の動向を踏まえて、現時点では新たな改築計画はございません。","id":"exchange-120"},{"speaker":"松澤委員","kind":"質問","question":"今お話を伺いました。ちょっと微妙な言い方をされましたけれども、しばらく耐震計画はないということでよろしいんですね、改めてお聞きしたいと思います。","respondent":"齋藤庶務課長","answer":"計画はございません。","id":"exchange-121"},{"speaker":"松澤委員","kind":"質問","question":"先ほどお話を聞きましたけれども、その中で３.１１について、品川区の子どもたちも帰宅困難者になってしまった。防災教育の中で、将来副読本なんかをつくって教育をするという計画はあるのでしょうか、その点をお聞きしたいと思います。","respondent":"冠木指導課長","answer":"そういった知見が集まってまいりますと、それからもう一つは、子どもたちが使える教材として発信をしていく必要性は十分にあると考えております。","id":"exchange-122"},{"speaker":"松澤委員","kind":"質問","question":"これはどんなことをやっているんでしょうか。その点についてお伺いしたいと思います。","respondent":"冠木指導課長","answer":"これは平成２４年度に設置していただけると聞いておりますので、来年につきましては、さらに充実したポンプ隊の参加が見込まれると思ってあります。それから、実際に教室で毛布１枚で寝て、朝解散というプログラムで実際の訓練ということでやらせていただいたところです。","id":"exchange-123"},{"speaker":"松澤委員","kind":"質問","question":"これが品川独自の教育委員会での行事なのか、あるいは上からのお達しによって行ったのか、その辺は聞かないでおきたいというふうに思います。３４７ページ、水ですね、水飲栓直結化工事、これはどのような、難しい字ですけど、事業なのでしょうか、お願いいたします。","respondent":"齋藤庶務課長","answer":"今東京都が学校については８割ほど負担をするので、こういうことで事業を進めておりまして、都営水道区域の公立小中学校６００校やります。おおむね３割の学校でやるということで、東京都が計画をしているというものです。","id":"exchange-124"},{"speaker":"松澤委員","kind":"質問","question":"そのときに、貯水槽、震度５になると、それがとまって、そこから水を飲むんですよというお話を伺いました。受水槽の水が震度５になるととまると、その水を救援が来る間に飲むんですと、全く相反する施策だと思うんですが、その辺、ちょっとお伺いします。","respondent":"齋藤庶務課長","answer":"あくまで直結化するのは給食室、水飲み場です。トイレですとか、その他の雑排水については引き続き受水槽を使います。","id":"exchange-125"},{"speaker":"松澤委員","kind":"質問","question":"あれっ、それじゃあ教員、私たちの水が、前の水を飲んでいるのかしらというような意見があったものですから、ちょっと聞いてみました。土曜日授業の実施について、私はこれも大変賛成なんですけれども、これのねらいはどういうことなのか、お聞きしたいと思います。","respondent":"冠木指導課長","answer":"二つ目に、既に品川区では１０日以上土曜日授業を実施している学校が複数ございまして、日数にこだわらなければ、全校で今実施しています。そんなところで、幾つか理由がありますけれども、土曜日授業を実施してまいりたいというふうに思ってあります。","id":"exchange-126"},{"speaker":"松澤委員","kind":"確認","question":"指導助手、これは当然やるのは教員で、それについて区費で補助している人たちの費用をここに出しているという考え方でいいんですよね。その点だけ確認しておきたいと思います。","respondent":"冠木指導課長","answer":"委員のおっしゃるとおりです。","id":"exchange-127"},{"speaker":"飯沼委員","kind":"質問・要望","question":"学校選択制のところなんですけれども、２０００年に導入された学校選択制について、改めて検証を伺いたいと思います。教員の意見はどのように反映をされているのか、３点目は、この間の成果と課題を具体的にお聞かせほしいと求めました。","respondent":"和氣学務課長","answer":"考えていくという体質に変わっていったという意味で、大きな成果が上がってきたというふうに考えているところです。そういう意味で、なかなか希望のところに行けないお子さんもいるというのは事実です。","id":"exchange-128"},{"speaker":"飯沼委員","kind":"質問","question":"こういった点、３点目は、学校選択制の周知が不足をしている、こういった３点に要約をされていました。やはり品川区の学校選択制が妨げになっている、こういったとらえ方をしていますが、品川の見解を説明するよう求めました。","respondent":"和氣学務課長","answer":"実際に地域の声もお伺いしながら進めてきているところですので、逆に言えば、地域の学校に対する目が非常に強くなったと思っています。","id":"exchange-129"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ、そこのまとめはしていただきたいし、公表をきちんとしていただかないと、どう評価しているのかがわからないんですよね。これは一般質問でもさせていただきましたけれども、この点、もう一回希望校に入れなかった人数、小学校と中学校を別々に説明を求めました。","respondent":"和氣学務課長","answer":"さらに、平成１９年に学事制の審議会をつくったときに区民向けのアンケートをとり、選択制が必要であるということで結論づけてあります。平成２４年に関しましては、中学校で１８名、小学校で６２名ということになってあります。","id":"exchange-130"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私はしっかりと相対的に見てほしい、人の話も聞いてほしい。私は、ぜひこの点で反省をして、選択制の見直しを求めますが、改めていかがか尋ねました。","respondent":"和氣学務課長","answer":"これはもっと今の状況では事前に情報を出すべきだというふうに考えておりますので、そのリスクも含めて選んでくださいよという提示をしております。少なくとも先ほど言いましたが、選択制があるから好きな学校に行くこともできる、そういうことです。","id":"exchange-131"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それは受けとめてほしいんですが、とにかく国と都の段階のところの全食材のチェックの強化というのも引き続き求めていっていただきたい。保護者の方から給食の食材から除いてほしい食品という訴えが来ているので、あと骨や内蔵を食べる小魚、このことはちょっとよく聞いてほしいんですが。","respondent":"和氣学務課長","answer":"基本的にそういうものについては昨日の国の発表でも、そういうものがさらに安全性が確認されたというふうに考えております。その意味で、学校もちゃんと配慮していますので、ご安心いただければと思います。","id":"exchange-132"},{"speaker":"飯沼委員","kind":"質問・要望","question":"内部被曝の８割から９割が飲食からということで、被曝線量が低ければ低いほど安全安心ということで、特に子どもには求められるのは当然です。その点はいかがでしょう。","respondent":"和氣学務課長","answer":"別に栄養士、栄養補助員を削減したわけではございませんので、あわせて４億８,０００万円の効果があるです。","id":"exchange-133"},{"speaker":"飯沼委員","kind":"質問・要望","question":"委託で削減ができたということは、同じような仕事をさせながら、年収２００万円以下なんですよね、ワーキングプアを生んでいるというところをしっかりと見つめて、ただ人件費が削られたというところだけではなくて、ぜひ反省をして、直営を取り戻してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"須貝委員","kind":"質問","question":"子どもたちの将来を思い、将来の夢をかなえさせてあげるには、まず学力や知識の取得を図ることが先ではないでしょうか。そして、学校、公立学校を支えているという話をよく聞きますが、この現実についてどのようにお考えか尋ねました。","respondent":"冠木指導課長","answer":"まことに重要な問題でございまして、現在品川区で進めております教育改革プラン２１もまさにこうした観点に立って展開しています。品川区の公教育が塾に支えられているという認識は持ってございません。","id":"exchange-135"},{"speaker":"須貝委員","kind":"質問","question":"これについてどのようにお考えなんでしょうか。なぜこういうことまで、この仕事、事業を何で教育委員会でやらないんか尋ねました。","respondent":"平澤生活福祉課長","answer":"私どもでやってあります塾代について、なぜ福祉部門で担当しているかというご質問かと思います。","id":"exchange-136"},{"speaker":"須貝委員","kind":"質問","question":"今教育委員会にどうだと、お子さんの学力を伸ばすということで、これを教育委員会が積極的に学校で普及させる。せっかくあるなら、中学３年生になる前にちゃんとそういうふうに親御さんに教えるということが私は教育委員会の仕事だと思うんですが、いかがか尋ねました。","respondent":"冠木指導課長","answer":"おそらく受験生のチャレンジ支援貸付事業のことだと思いますけれども、塾代等の貸し付けや低所得者等を対象とした相談を行い、生活支援の総合的な窓口である生活福祉課が所管することが最も適切だと考えているところです。","id":"exchange-137"},{"speaker":"須貝委員","kind":"質問","question":"では、ちょっとお聞きしますが、指導課長、どうしたら学力がつくんですか。どうしたら学力がおくれないようにできるんか尋ねました。","respondent":"冠木指導課長","answer":"そして５、６年生においては教科担任制を導入し、それは高学年になってくれば得意不得意がありますよ。私どもは９年間の小中一貫教育の中で、それが私どもの考え方であって、それでもって私どもは実績を上げてきたです。","id":"exchange-138"},{"speaker":"須貝委員","kind":"質問","question":"どうしたら、学力がつくんですか。そして、どうしたら学力がおくれないようになるんか尋ねました。","respondent":"冠木指導課長","answer":"それは一人ひとりの子どもたちが学習意欲を持って勉強することです。","id":"exchange-139"},{"speaker":"須貝委員","kind":"質問","question":"反復学習する環境がないのになぜ学力が上がるんですか。だけど、できないお子さんにとっては、やはり補習をさせるとか、何とかそういう方法をしないと、どうやって覚えるんか尋ねました。","respondent":"冠木指導課長","answer":"そういったことを平成１８年からじっくりと取り組んでまいりました。あさってですか、非常に今回の９年生は優秀な成績をおさめていただきましたので、この場をかりて報告をさせていただきたいと思ってあります。","id":"exchange-140"},{"speaker":"須貝委員","kind":"質問・要望","question":"委員長、すみません。聞いていないんで、ちょっと切らさせていただきたいんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"答弁って、聞いていない答弁なので、これはちょっとまずいんじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"私、その質問しましたか。申しわけありませんが、委員長、それあなた采配していますよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"ちょっと待ってください。質問をしていないですよ、今の項目は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-144"},{"speaker":"須貝委員","kind":"質問","question":"ちょっと、委員長、采配というのは、私らが聞いた質問に対してきちんと采配するのが委員長じゃないですか。そうじゃなかったら、私らは何にもできないじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"委員長、これは予算特別委員会の場で、我々の質問に対して答えていただけるという仕組みが、委員長、最初もそういうふうに述べましたよね。いんじゃないですか、それ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"学校で教えていないじゃないですか。やっぱり結果というのは大事じゃないですか、お子さんにとっても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-147"},{"speaker":"阿部委員","kind":"質問","question":"どういう経緯で、あるいはなぜ１７日という数字が出てきたのか、そのお考えをもう少し詳しく伺えればと思いました。これはどういうことなのかということ、公立幼稚園でも希望者が増えている中で、今後体制をどう充実していくのかということをお伺いしたいと思います。","respondent":"冠木指導課長、齋藤庶務課長、吉岡保育課長","answer":"特別支援学級の先生が巡回をするというような考え方を都が基本的に持っておりまして、一定程度の、私どもの特別支援学級は非常にレベルも高くて。… この案にご意見を頂戴して、区長の決定をもらって、６月には議会にご報告をする予定です。学校の関係者の皆さんには、学校だよりという形でお伝えして… こちらは昨年の６月に北品川すこやか園ということで、御殿山幼稚園と北品川第二保育園の新しい幼保一体施設をオープンいたしました。","id":"exchange-148"},{"speaker":"阿部委員","kind":"質問・要望","question":"それをどう確保していくか、ぜひ意識的にそれは検討していただきたいと思うんですが、この件についてお考えを伺いたいと思います。どのようにお考えになっているか、今後どうしていくかということを改めてお伺いしたいと思います。","respondent":"冠木指導課長、齋藤庶務課長、吉岡保育課長","answer":"私のほうから、２点お答えをいたします。特別支援教育についてですが、全校で取り組んでおりますので、そういった知見をさらに広げていきたいというふうに… 十分近隣の学校と連携をとりながら代替施設を確保し、体育の授業に支障がないように努めてまいります。校庭開放につきましては… 去年の５月時点での数字ですけれども、ほとんどの方は何らかの就学前の教育を受ける機会を持っていらっしゃるというふうに判断しています。","id":"exchange-149"},{"speaker":"阿部委員","kind":"質問・要望","question":"あるいは減らしたり、あるいはそのための振り替えをしたりということも一緒に考えていらっしゃるのかどうかということをお伺いしたいと思います。土曜授業の考え方についてご答弁をお願いします。","respondent":"冠木指導課長","answer":"土曜授業の半日１７回という考えについては、当面この形でやっていきたいというふうに考えてあります。それから、鈴ヶ森方式については、東京都のほうにも十分にＰＲしてまいりたいというふうに思います。","id":"exchange-150"},{"speaker":"阿部委員","kind":"質問・要望","question":"１点だけ、午前中のやりとりの中で気になったことがあったのでお伺いしたいと思います。教育委員会としてのお考えをぜひ、現場に立ったことのある方にご答弁いただけるとありがたいなと思っています。","respondent":"冠木指導課長","answer":"その間で校長先生はいろいろな判断をしてまいりますので、今後もそういうようなところで、十分バランスを考えながら判断をしてまいりたいと思います。","id":"exchange-151"},{"speaker":"若林委員","kind":"質問・要望","question":"システム的には、やはり今三つのパターンで、特に分離型の一貫校という言い方が正しいんでしょうか。この二つを何とか教育委員会学務課長等の知恵で乗り越えていただきたいなということで、冒頭に一言お願いいたします。","respondent":"和氣学務課長","answer":"陳情の問題で、私どももそれは受けとめました。あと小中一貫教育を充実させるという観点からも、改めてしっかりと見直してまいりたいというふうに考えてあります。","id":"exchange-152"},{"speaker":"若林委員","kind":"質問・要望","question":"そして新年度はどうなるのか、平成２４年度はどうなるのか、これをご答弁ほしいと求めました。子どもたちに伝えたという内容とか、それとも新年度こういうふうに活かしていきますよということがあるのかお聞きしたいと思います。","respondent":"冠木指導課長","answer":"今後の予定ですけれども、こういった取り組みについては、各学校にまた広めていきたいなというふうに思ってあります。なお、今後派遣という形で東京都と調整をしておりまして、平成２４年度についても派遣の教員が出る見込みです。","id":"exchange-153"},{"speaker":"若林委員","kind":"意見","question":"いずれにしても２０１６年、４年後には展開が進んでいくということですので、よろしくお願いいたします。例えば夏休みの１週間とか２週間とか、直に話を聞いて持ち帰るということが大事だと思いますので、そういうご検討もとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-154"},{"speaker":"須藤委員","kind":"質問","question":"３４９ページの空調機等借料というのが、小学校、中学校で去年もあって、今年もあるんだけども、これはどういうことなのか。これをいつまでずっと安心のためということでやるのかという思いがあるんだけど、そのあたりはいかがか尋ねました。","respondent":"齋藤庶務課長、和氣学務課長","answer":"普通教室のリースが去年で切れまして、８年でリースをしていますが、リース切れすると今度区のものになります。今回上げたのは、特別教室の分のリース料が発生しておりますので、その分を計上しています。 ずっと永劫続けるという気はございませんので、今の流通の関係の公表の仕方であるとか精度とかを十分研究しながら、時期を見てしっかり判断をしたいというふうに考えてあります。","id":"exchange-155"},{"speaker":"須藤委員","kind":"質問","question":"さっきあったように何十年も続きますと、何十年もそんなことをやるのかなという思いがちょっとしたので、そこのあたりをちょっと聞かせてもらいます。３３７ページに関係して、学校の先生がまだこの字は教えていないから、よく書けたねと褒めて上げるのかどっちか。","respondent":"冠木指導課長","answer":"漢字、よく書けたなと褒めてあげるのが品川です。","id":"exchange-156"},{"speaker":"須藤委員","kind":"意見","question":"私自身も４５年ぐらい前かな、２回目かなんかに私は通らせてもらったんだけども、その専科教員の資格というのはいつまで続いているのか。この間、４０代ぐらいの若い方に聞いたら、文部科学省が出した資格みたいなのはどういうつながりがあるのかとの意見を述べました。","respondent":"冠木指導課長","answer":"そういった人材が、例えば私どもの小学校の採用のほうに、東京都の方から指定されるというようなことはまずございません。まれにそういう方がいらっしゃる可能性はありますが、私この３年間人事の担当をしておりますけれども、そういう方は今のところいらっしゃいません。","id":"exchange-157"},{"speaker":"須藤委員","kind":"質問・要望","question":"小学校で５時間ぐらい、中学校で１０時間ぐらいというと、体育という言葉をつくったくらいの教育者がやった競技です。いわゆる気をつけの姿勢があまりできていないようなんだけど、そのあたりはしっかり教えてほしいと求めましたが、いかがか尋ねました。","respondent":"冠木指導課長","answer":"かかとをつけてしっかり礼をしなさいという指導は、私どもはこれまでも指導してきたところですが、不十分なところはまだまだあると思います。","id":"exchange-158"},{"speaker":"須藤委員","kind":"質問","question":"私は代表質問でもちょっとさせてもらったんだけど、なぜかなと思っているんだけど、知育の育て方になってくる。いかがか尋ねました。","respondent":"冠木指導課長","answer":"ですので、一生懸命説明の仕方であるとか、自分の考えであるとかというようなところを言葉で伝えていくということは非常に大切なことだと思います。あわせて、今委員のご指摘のような情操教育であるとか、心の教育というところも十分に取り組んでまいりたいと思います。","id":"exchange-159"},{"speaker":"須藤委員","kind":"意見","question":"学ぶ喜びの中で、脳の中でドーパミンというのが発生してくるよ、それと同時にセロトニンというのも喜びの中に入ってくる。今お話ししたものが全部一緒にしっくりするなと私自身は思っているんですが、時間なのでそういう考えはいかがかとの意見を述べました。","respondent":"冠木指導課長","answer":"委員のおっしゃるとおりに、そういった二つの機能を果たしてこそ、我々の人間の体というのは自然にそういった部分で育っていくのかなというふうに思ってありますので、肝に銘じまして取り組んでまいりたいというふうに思います。","id":"exchange-160"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/918450?Template=document&Id=976#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":123277,"voices":378}},{"id":"h24-20120319-3","meetingId":"h24-c-budget","date":"2012年3月19日","dateIso":"2012-03-19","committee":"予算特別委員会","time":"午前１０時００分～午後５時２８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を119件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山内委員","kind":"質問","question":"最初に、介護保険制度についてを伺います。事業者からも期待が非常に高いこのサービス、新たにこのサービスをする期待度を伺いたいと思います。","respondent":"木下健康福祉事業部長","answer":"その中の中心的メニューが、ご指摘がありました２４時間定期巡回・随時対応型訪問介護というサービスでありますので、私ども行政といたしましても。","id":"exchange-001"},{"speaker":"山内委員","kind":"質問・要望","question":"次に、保険料について伺います。この第五期でも８億円という金額を繰り越す、この８億円という金額、根拠というものを教えてほしいと求めました。","respondent":"木下健康福祉事業部長","answer":"保険料を３年間で決めますので、２年目がとんとん、３年目で余ったものを使うという形でゼロになることが制度の１つのモデルだったわけです。","id":"exchange-002"},{"speaker":"山内委員","kind":"質問・要望","question":"どんどんと、なかなか給付費も増えるという中で、８億円という金額をしっかりとプールできていくのかというものがちょっと懸念をされると思います。区は２億５,０００万円拠出をし、今回２億２,０００万円を繰り出すというか、そのあたりを教えてほしいと求めました。","respondent":"木下健康福祉事業部長","answer":"そういう点では、次の保険料引き下げ効果ということを長いスパンで見たときに、やや厳しいものがあるなというふうに認識をしているところです。","id":"exchange-003"},{"speaker":"山内委員","kind":"提案","question":"このすばらしい提案をするということで、いわゆる提案型で選択をされるということでありますけれども、この小規模特別養護老人ホーム。この５法人が区内のこれからできる施設といったものをしっかり運営をしていただきたいという思いで私はこの質問をしたいんですけれどもとの意見を述べました。","respondent":"木下健康福祉事業部長","answer":"５法人のご指摘ですけれども、品川区の場合には、いわゆる品川方式と称しまして、この間基盤整備を進めてまいりました。そういう点では、設計プランといい理念、ケアに対する考え方をしっかり持って提案をしていただくことが肝要だというふうに思っているところです。","id":"exchange-004"},{"speaker":"山内委員","kind":"質問・要望","question":"そういった意味で、５法人のやる気といったところをお伺いをしたので、そういったハッパをかけていただければなと考えています。なぜ１０カ月の間こういったことがされてこなかったのかということをまず伺いたいと思います。","respondent":"片田防災まちづくり事業部長","answer":"対応を整えるというような状況ですけれども、３.１１を含めた中で、いわゆるＢＣＰを策定してきたというような状況があります。それぞれやはり課題を認識していますので、３月２７日を今予定していますけれども、これまで区としての体制を調整してきたというような状況です。","id":"exchange-005"},{"speaker":"山内委員","kind":"質問","question":"それを聞いたのが１月のことです。私は区長のイニシアチブといったものが非常に重要ではないかと思うんですけれども、そのあたりはいかがお考えかを伺いたいと思います。","respondent":"濱野区長","answer":"本当に区と医療機関の皆様方とがしっかりと連携をとるということが防災体制を引く上で非常に重要なことだというふうに認識をしております。とにかく区民の生命ということを考えれば、全庁挙げてスピード感を持って取り組んでまいりたいと考えております。","id":"exchange-006"},{"speaker":"山内委員","kind":"質問・要望","question":"次に、防災行政無線に関することを伺いたいと思います。そうなったときに、改めて区はどのように対応をしていくのかといったことは今考えておられるのかということを伺います。","respondent":"日下部企画部長","answer":"ですから、そういうことになりますと、これはもう残念ながら放送についてこれを続けることはなかなか難しいというふうに考えております。ですから、その点については、ほかのライフラインと同様に、早期の復旧を待つしかないと、こういう考えでいるところです。","id":"exchange-007"},{"speaker":"山内委員","kind":"質問","question":"平成２４年度の予算で、商店街１９カ所に情報伝達スピーカーと連携をして、そういった震災時にはケーブルと同じような考えでいいのか。それとも無線を、まあ、どういうやり方をするのかというところをちょっとお聞きをしたいと思います。","respondent":"日下部企画部長","answer":"そういった点では、かなり大きな災害が起こりましても、それなりにしっかりした対応ができる。こういうことで、ちょっとケーブルとはまた仕組みが違うです。","id":"exchange-008"},{"speaker":"山内委員","kind":"提案","question":"実はうちの会派から要望というか、提案をしていますのが、コミュニティＦＭの設置であります。電波がしっかりと届くかどうかといったことは、改めて伺いたいと思いますけれども、そういったＦＭの開局の可能性を伺いたいなと思いますとの意見を述べました。","respondent":"日下部企画部長","answer":"あるいはまた、災害時に身近なレベルでの災害情報を提供できるということで、非常に効果としては期待ができるというふうに認識をしております。ただ一方で、そういう課題についても十分に検討をする必要があるのではないか、このように考えております。","id":"exchange-009"},{"speaker":"山内委員","kind":"質問","question":"当時はスタジオを借りてどうのこうのとかという大きな考え方でやっていましたけれども、そういったやり方もあるということを伺っています。私からの質問はこれで終了いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問・要望","question":"長期基本計画について質問させてほしいと求めましたけれども、平成２１年の４月に発刊をされました長期基本計画の前文、朗読します。３.１１と、区はどのように認識をし、そしてこれらの点にどのように今後対処していくのかをまずお伺いをさせていただきたいと考えています。","respondent":"日下部企画部長","answer":"円高の進行等をはじめとして、この間、非常に厳しい経済環境が続いてきたというふうに認識をしております。やはりこの３年間の社会経済環境の変化というのは、また早いものがあると、このように認識をしております。","id":"exchange-011"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、企画部長より、この長期基本計画、この３年間、さまざまな取り組み、そして、基本計画について、時代との整合性、そして認識を伺いました。されば、今現状でこの取り組みをどのようにされているか、ご説明ほしいと求めました。","respondent":"日下部企画部長","answer":"保育園、こちらも、区独自の取り組みによりまして、毎年５００人以上の受け入れ枠の拡大を図っている。ここ３年間で防災広場の整備、１７カ所に及んでおりますし、これが進んできたと考えているところです。","id":"exchange-012"},{"speaker":"大沢委員","kind":"質問・要望","question":"そのような一定の社会の変化に対し、課題が生まれた。それについてどのように対処をされてきたのか、ご説明ほしいと求めました。","respondent":"日下部企画部長","answer":"臨機応変な対応ができましたけれども、そういった土台があったからそれなりの対応ができたのではないかと、このように考えております。こういった変化に対してしっかり対応できるように、繰り返しになりますけれども、このように考えております。","id":"exchange-013"},{"speaker":"大沢委員","kind":"質問・要望","question":"うち５年のスパンで見直し、そのことについてどのようにお考えになっているのか、お示しほしいと求めました。","respondent":"日下部企画部長","answer":"経済環境の変化に迅速かつ柔軟に対応するため、５年を目途に見直しを行うということで、位置づけをしております。平成２４年度、１つの目安としては平成２５年度に見直しの作業を進めていく、このような手順になるのではないかと考えております。","id":"exchange-014"},{"speaker":"大沢委員","kind":"質問","question":"平成２５年度ということですから、平成２５年の４月から平成２６年ということになりますですね。区長のお考えと、もしご納得いただくようなことであれば、決意をお伺いをしたいと思います。","respondent":"濱野区長","answer":"というか、経済といいますか、策定時よりも厳しい状況になっていると認識をしております。このことについては、見直しの際にしっかりと頭の中にたたき込んで取り組んでまいりたい、そのように思っているところです。","id":"exchange-015"},{"speaker":"大沢委員","kind":"質問・要望","question":"では、次の質問に移らします。補助金についてお伺いをしたいと思いますけれども、国と地方の基本的なルール、まずお示しほしいと求めました。","respondent":"榎本企画財政課長","answer":"基本的なルールとしましては、地方財政法の中では、実施団体が負担をするというのが大原則になっています。委託金につきましては、国が実施すべきものを自治体がかわって行うということで、金額的にはかなり少ないという形です。","id":"exchange-016"},{"speaker":"大沢委員","kind":"質問・要望","question":"その中で、この負担が増えていった場合、区の予算、どのような圧迫、影響が及ぼされるのかということをお伺いしたいのが１点。この２点、基本的な考え方を教えてほしいと求めました。","respondent":"榎本企画財政課長","answer":"生活保護費につきましては４分の３が国負担ということで、残り４分の１が区の負担ということで、まだ伸び率としては少なくなっている。","id":"exchange-017"},{"speaker":"大沢委員","kind":"質問・要望","question":"今お話聞きましたけれども、今後、地方財政、非常に圧迫されていくと思います。今後、地方からどのように国に対してものを申していくのか、ビジョンがありましたら教えていただきたい。","respondent":"榎本企画財政課長","answer":"それで、今、大きくとらえますと、歳入面でいきますと、国が６の歳入で、地方が４の歳入。国が４の仕事で、それをちゃんと税源と仕事の量が合うように５対５に当面持っていこうというのが今のところの国に対しての要望事項となっております。","id":"exchange-018"},{"speaker":"大沢委員","kind":"質問・要望","question":"平成２１年でしょうか、タイ国のバンコクにビジネスサポートセンターを設置しました。このサポートセンター、はやもう４年余がたとうとしておりますけれども、現状と課題についてまず教えていただきたい。","respondent":"中川原地域振興事業部長","answer":"利用される中小企業の方が、利用の限度であります３カ月めいっぱい借りたいという、そういったニーズが多くなってきているというのが現状です。","id":"exchange-019"},{"speaker":"大沢委員","kind":"質問・要望","question":"今の質問の表題で、設置ということで私申し上げました。地方自治法の第２４４条で、このビジネスサポートセンターが成り立っているのか、説明をしていただきたい。","respondent":"中川原地域振興事業部長","answer":"ただし、品川区のような基礎自治体が海外にサポートセンターを設置することは極めてまれでございまして、短期間の展開を想定して実施しております。","id":"exchange-020"},{"speaker":"大沢委員","kind":"質問・要望","question":"今後のビジネスサポートセンターのあり方についてお伺いしますけれども、タイを囲むあそこのアジアの地域、非常に経済発展を遂げております。ものづくり品川を世界にアピールするにはどのような事業展開されていくのか、展望がおありになるでしょうから、ご披露ほしいと求めました。","respondent":"中川原地域振興事業部長","answer":"海外の企業、国際化対応専門相談員や専門非常勤の工業相談員として各企業の実情に応じたきめ細かな支援に努めているところです。そうした機関などとの連携も強化しつつ、各国の状況の情報収集に努めまして、品川区としての最善の策を検討していきたいと考えております。","id":"exchange-021"},{"speaker":"大沢委員","kind":"質問・要望","question":"防災計画についてお伺いをします。品川区の防災計画の中で、その取り組みから受けた答申、どのように評価をし、反映をしていくのか、まず伺いたいと思います。","respondent":"片田防災まちづくり事業部長","answer":"国の取り組みですけれども、国のほうは昨年の１０月に中央防災会議を行いまして、推進検討会議を設置したというような状況を聞いてあります。そういうものをきちっと位置づけた中で、対応を進めていきたいと、このように考えてあります。","id":"exchange-022"},{"speaker":"大沢委員","kind":"質問","question":"まさに首都直下型ということですので、また東日本大震災の主要部、東北地方の地震とまた別の様相を呈する。私、平成７年１月１７日に起こりました阪神・淡路大震災、改めて専門家のその件についてのご見地を伺いたいと思います。","respondent":"片田防災まちづくり事業部長","answer":"東京都の対応指針の中では、東京都を襲う地震像ということで、大きく分けて３タイプほどあります。逆に言うと、どんな地震が来ても大丈夫なように備えなきゃいけないと、こういうふうなことを考えてあります。","id":"exchange-023"},{"speaker":"大沢委員","kind":"質問・要望","question":"さまざま防災訓練の中で大きな消火器の訓練をやっておりますけれども、これは非常に重い、ちょっとお年寄りの方には使い勝手も悪い。では、いつでも、どこでもということで、使いやすさを考えた場合、単に消火の方法というのは何があるのか、教えていただきたい。","respondent":"片田防災まちづくり事業部長","answer":"その中で、消火器というところの利点ですけれども、初期消火にすごく役立つということで考えております。十分その辺の状況を踏まえて、私どものほうとしても検討してまいりたいと、このように考えてあります。","id":"exchange-024"},{"speaker":"大沢委員","kind":"質問・要望","question":"消火器については、いつでも、どこでも、だれでも簡単に使えるようなものを検討していただきたいと思うんですね。その点についてお考えをお伺いしたい。","respondent":"片田防災まちづくり事業部長","answer":"あるいは障害者のみの世帯ということで対応されて、いろいろシルバー人材センターとの連携のもとにそういう支援を行ってきたところですけれども。","id":"exchange-025"},{"speaker":"大沢委員","kind":"質問","question":"ここのところは機敏に対応できるべく今後の取り組みをお願いしたいと思いますし、先ほど４つ、まさに見えてきているのが予想されます。ぜひとも当たり前のことが当たり前にできる品川区づくり、お願いをしてこの質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"山元委員","kind":"提案","question":"初めに、防災対策の強化についてお伺いいたします。これまで会派として何度も提案、要望してきた防災ラジオあっ旋、それぞれの事業概要と対策の効果についてお教えくださいとの意見を述べました。","respondent":"片田防災まちづくり事業部長","answer":"やはり日ごろから地域の地盤高を認識した中で、万が一のときにすぐに行動がとれるといった啓発を含めた対策に有効だと、このように考えてあります。","id":"exchange-027"},{"speaker":"山元委員","kind":"質問・要望","question":"一日も早いスタートを要望いたしますが、いかがでしょうか。あわせて、洋式を含めた簡易トイレの備蓄の拡充も要望いたしますが、それぞれのご所見をお願いいたします。","respondent":"片田防災まちづくり事業部長","answer":"今３地区を予定していまして、示せない状況ですけれども、可能な限り早い時期にお示ししてまいりたいと考えています。一応購入予定、計画的に進めていきたいと、このように考えております。","id":"exchange-028"},{"speaker":"山元委員","kind":"質問","question":"次に、地域防災計画の改訂についてお伺いいたします。どのような視点から見直しを図っていくのか、都の被害想定など、今後の改訂に向けたスケジュールを説明するよう求めました。","respondent":"片田防災まちづくり事業部長","answer":"そういうものをどのように現実的な対応の中で進められるかといったこともあわせて、一応考えていきたいと、このように考えてあります。","id":"exchange-029"},{"speaker":"山元委員","kind":"提案","question":"代表質問の回答では、女性の視点の反映について、改めてこうした国の状況等を踏まえた今後の取り組みについてご所見をお伺いいたします。","respondent":"片田防災まちづくり事業部長","answer":"あるいは学校避難所での対応の運営の仕方とか、そういうジャンルごとの検討会、このように考えてあります。一定の標準的な女性の視点を取り入れたものを考えて、それぞれの避難所に応じた形での対応ができないかといったようなことを今考えているところです。","id":"exchange-030"},{"speaker":"山元委員","kind":"提案","question":"訓練の中で昨年本会議で同僚議員が提案いたしました避難所運営ゲーム、職員も交えて実施し、課題をより明確にしていくべきと思います。その上で、避難所ごとの個別の課題は学校避難所マニュアルに、それぞれのご所見をお伺いいたしますとの意見を述べました。","respondent":"片田防災まちづくり事業部長","answer":"学校避難所マニュアルの中でも、当然女性の視点は、先ほども申し上げましたように、重要な視点と認識しています。提案を行いながら、課題を抽出して、マニュアルに反映できるような工夫を行ってまいりたいと考えています。","id":"exchange-031"},{"speaker":"山元委員","kind":"提案","question":"昨年から私どもの提案した防災ヘルメットを配付して、いざというとき自分の身を守るとともに、高齢者や子どもたちを支援する役割も期待されています。先ほどのＨＵＧを取り入れた避難所訓練に中学生も積極的に参加してもらい、ご所見をお伺いいたしますとの意見を述べました。","respondent":"片田防災まちづくり事業部長","answer":"そういう意味では、地域の防災活動の担い手ということで、十分な可能性を持っているということで認識しています。いずれにいたしましても、防災教育の観点からという視点も含めて、関係機関のほうとも協議をして検討してまいりたいと考えています。","id":"exchange-032"},{"speaker":"山元委員","kind":"提案","question":"平成２４年度、新たに拡充された区の防災対策等を掲載し、区民への周知を図るように提案をいたします。広報しながわ防災特集号や今後発刊予定のわが家の防災ハンドブックに掲載してはと思いますが、あわせてご所見をお伺いいたしますとの意見を述べました。","respondent":"片田防災まちづくり事業部長","answer":"あるいは認識していただきたい、積極的にそういう取り組みを行わさせていただきたいと思いますし、必要な検討をしてまいりたいと考えています。","id":"exchange-033"},{"speaker":"山元委員","kind":"質問・要望","question":"はこの２つの総合対策の概要をご説明ほしいと求めました。事故発生状況と実施している対策をお知らせいただき、安全対策について、今後の課題についても確認をお聞かせほしいと求めました。","respondent":"岩田都市環境事業部長","answer":"すなわち、あくまでも車両だということを再認識していただいて、その周知徹底を図るというのが今回の考え方です。しかし、これがなかなか認識をされていないというのが課題ですので、課題に向けてのいろいろ総合対策を打っていかなければいけないと考えています。","id":"exchange-034"},{"speaker":"山元委員","kind":"提案","question":"インセンティブづくりなどについて、品川区の実情に合った総合的な対策を構築してほしいと求めましたが、いかがでしょうか。最後に、やさしいご答弁とまたメッセージをほしいと求めましたが、いかがか尋ねました。","respondent":"岩田都市環境事業部長","answer":"いわゆる関係者、そういったものも含めていろんな意見を交わしていくというのは大事なことですので、それは早急に検討してまいりたいと思います。","id":"exchange-035"},{"speaker":"山元委員","kind":"質問","question":"以上で私の質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"塚本委員","kind":"質問","question":"初めに不燃化施策ですけれども、昨年東京都が木密地域不燃化１０年プロジェクトで、不燃化特区制度の創設を発表しました。そこで、不燃化特区制度の概要と品川区がこの特区制度で目指す不燃化とはどのようなものか、お伺いをいたします。","respondent":"片田防災まちづくり事業部長","answer":"１０年プロジェクトといった中で特区制度を設けてきたという経過がありますので、円滑に進めてまいりたいと、このように考えてあります。これを東京都のほうとしても進めていきたいですので、区として防災に強いまちづくりを考えていきたいと、このように考えているところです。","id":"exchange-037"},{"speaker":"塚本委員","kind":"質問","question":"都が整備地域として指定をしている林試の森から荏原地域、約７７０ヘクタール、この地域を不燃化促進するということであると認識をいたしております。区独自の不燃化政策を策定するべきと、このように思いますけれども、お考えをお伺いいたします。","respondent":"片田防災まちづくり事業部長","answer":"ご案内のとおり、荏原地域を中心として、区内の３分の１が木造住宅密集地域といったような状況の中で、喫緊の課題と認識しています。延焼遮断帯を形成することが十分可能だと考えていますので、有効かつ効果がある対応を考えてまいりたいと、このように考えております。","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問・要望","question":"そして、８メートル隔てた道路であっても、広域火災の猛威というものについて自らの体験を通して切実に語っておられました。耐火ボードなど、比較的安価な耐火改修について、不燃化に対する効果をどのように評価しているか、お考えを説明するよう求めました。","respondent":"片田防災まちづくり事業部長","answer":"基準がありますので、そういうことを満たしていくような制度の中で、延焼を防げるといったような考え方です。委員ご紹介のありました耐火ボードの設置、これは墨田区のほうで進めているということは私どものほうとしても一応承知していますけれども、ただ。","id":"exchange-039"},{"speaker":"塚本委員","kind":"質問","question":"東京都議会の第１回定例会で、またリフォームや耐火塗装による延焼防止策をとの質問に対しまして、こういった答弁がございました。不燃化促進のために木造住宅の耐火改修に踏み込むべきではないかと、このように考えますけれども、いかがでございましょうか。","respondent":"片田防災まちづくり事業部長","answer":"先ほど私どものほうの考え方をお示しさせていただいたところですけれども、不燃化というのは喫緊の課題であることは十分認識しています。","id":"exchange-040"},{"speaker":"塚本委員","kind":"質問・要望","question":"同様の対応を検討していただきたいと、このように思いますので、よろしくお願いしたいと思います。そこで、品川区就業センターの就労支援の中身について、具体的に説明をお願いいたします。","respondent":"中川原地域振興事業部長","answer":"就労支援としましては、そして情報端末を設置して、ハローワークの求人情報を提供してまいります。現在北品川にあります５５歳からの無料職業紹介所、シルバー世代の就労支援についても、さらに強化を図っていく予定です。","id":"exchange-041"},{"speaker":"塚本委員","kind":"質問・要望","question":"私どもの会派では、昨年１２月２７日に新卒者、また若年者の就労支援について区長に申し入れをさせていただきました。若者向けの就労支援について、課題と展望、これについてお伺いをいたします。","respondent":"中川原地域振興事業部長","answer":"若者向けの就労支援ですが、専修学校などの学生や卒業後未就職の若者の就職を支援する専門のハローワークを設置し、きめ細やかな対応をしております。","id":"exchange-042"},{"speaker":"塚本委員","kind":"意見","question":"公明党の青年局では、昨年末に１,０００名を超える若者へのアンケート調査を実施いたしまして、若者雇用実態調査として結果を発表いたしました。区のお考えを説明するよう求めました。","respondent":"中川原地域振興事業部長","answer":"こういった品川区の中小企業の魅力のＰＲを含めた求人情報の発信につきましては、就業支援の大きなポイントであると認識しております。区としましては、ご提案のスマートフォンにも対応したホームページづくりを含めまして、効果的な情報発信について検討してまいります。","id":"exchange-043"},{"speaker":"塚本委員","kind":"意見","question":"若者がしっかり就職し、自立した生活を送れるようになることは、区が取り組むべきとても大切な課題と考えます。若者の就労支援の内容とその開始時期について区の方針を説明するよう求めました。","respondent":"中川原地域振興事業部長","answer":"さらに就職が困難な状況になってまいりますので、性格などに配慮しましたアフターフォローも含めた丁寧な支援が必要になってくると認識しております。そうしたさまざまな取り組みについても調査しつつ、来年度以降、検討を進めていきたいと考えているところです。","id":"exchange-044"},{"speaker":"塚本委員","kind":"質問","question":"本区は、今お伺いをいたしましたけれども、この問題の解決に向かってどういったものが必要であるというふうにお考えをお持ちであるのか。今、保健センター等のお話ございましたけれども、就業センターとしてのそういった点についてもう一度お伺いをしたいと思います。","respondent":"中川原地域振興事業部長","answer":"るるニートについての取り組みの難しさを述べさせていただきましたが、これは本当に一朝一夕にはできない難しい問題であるととらえております。障害者福祉課と庁内の中での連携をとりつつ、都の動きも注視しつつ、検討を進めていきたいと考えているところです。","id":"exchange-045"},{"speaker":"塚本委員","kind":"質問・要望","question":"外部の諸団体との連携、こういったこともしっかりとしながら、こういったことについて取り組んでほしいと求めました。区のお考えを説明するよう求めました。","respondent":"中川原地域振興事業部長","answer":"ニートにつきましては、本当にこれは難しい問題ですので、じっくり関連のところと検討を進めさせていただきたいと考えています。そして、「若ナビ」等々、メールの相談とか、そういったものについても、保健所等関連部署と連携して考えさせていただきたいと思います。","id":"exchange-046"},{"speaker":"塚本委員","kind":"質問・要望","question":"せめて品川区就業センターのホームページの開設、これだけでも早期に実施していただくように要望をさせてほしいと求めました。以上で品川区議会公明党の総括質疑を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"向委員","kind":"質問・要望","question":"品川区における基本的な自治体としての広報広聴活動のあり方をどのようにお考えなのか、とらえていらっしゃるかを教えてほしいと求めました。そしてまた、このたびの東日本大震災を経て、その考え方にどのような変化があったのかどうかもあわせてお伺いします。","respondent":"日下部企画部長","answer":"そもそもは、区政運営全般につきまして、できる限りきめ細かにお伝えをしていく必要があるということで認識をしております。そういった取り組みを進めまして、一人一人にしっかりと情報をお伝えするように努めていると、そういう状況です。","id":"exchange-048"},{"speaker":"向委員","kind":"質問","question":"区民が欲しいという形で情報が的確に提供されているのか、このあたりについてどのようにお考えか、お伺いしたいと思います。","respondent":"日下部企画部長","answer":"子育て支援の特集号ということで発行しておりますけれども、例えばこの子育て支援特集号の発行に当たりましては、関心度。ひとりよがりにならないで、わかりやすいような表現、こういった点にもいろいろ努力をしています。","id":"exchange-049"},{"speaker":"向委員","kind":"質問・要望","question":"できる限り早く、区民の皆さん、人々の情報の理解力というのも本当に求められる時代になってきたのではないかなと考えております。穴をつくらないような形で確実に投げ込んでいくかということを重要視する中でお尋ねしたいと思うんですけれども、お尋ねしたいと思います。","respondent":"日下部企画部長","answer":"ご質問にも出てまいりましたメールマガジンでありますとか、つまり、かなり幅広い方法で区民の皆さん方に情報をお伝えをしてきていると。","id":"exchange-050"},{"speaker":"向委員","kind":"確認","question":"大手の新聞社が６社ほどと、東京ＭＸの２社のみと伺っているんですけれども、発信がなされているのかどうか。そのあたりのリスクが伴った取材内容などになってないかどうか、チェック体制、どのようになっているのかをお伺いしたいと思います。","respondent":"日下部企画部長","answer":"企画書を出して、大体取材の意図がどういうところにあるのかとか、そういったことについてきちんとこちらで把握をした上で対応する。そういうふうな形で、行き違いが出ないような、そういう１つのチェック体制、こんな形で進めているというものです。","id":"exchange-051"},{"speaker":"向委員","kind":"質問・要望","question":"区民の方とか、持っておくべきと考えておりますし、今後も品川区としての独自性に富んだ広報広聴活動にご尽力いただきたいなと考えています。以上で私からの質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"井上委員","kind":"質問・要望","question":"１校、１園当たりの年間の測定回数を伺います。品川区は測定機関の選定基準を持っているのか、伺います。","respondent":"田村教育次長","answer":"保育園は５園ずつ検査実施していく予定でしたが、１学期当たり、ほぼ２週間分の給食の放射能測定を行うことが可能です。厚生労働省のマニュアルに沿うことを明記して、一般競争入札を実施していると、そのような状況です。","id":"exchange-053"},{"speaker":"井上委員","kind":"質問・要望","question":"自治体担当者からは不満の声が聞かれているようですが、なぜこれが自治体担当者には不評なのか、その理由を教えてください。それから、区市町村の意向調査が３月１５日で締め切られていますけれども、品川区はこれに対してどのような回答をしたのか、伺います。","respondent":"田村教育次長","answer":"東京都は来年度から検査機器を購入して、食材の事前検査を実施するということで、６２市区町村合わせて２台ということになります。仮に事前に食材を購入して保管するための場所や食材の傷みなどを考えますと、この東京都の提案の検査体制には参加しない予定で現在おります。","id":"exchange-054"},{"speaker":"井上委員","kind":"質問・要望","question":"品川区は以前５年間事務事業評価を行っていますが、その目的と意義を伺います。この区民参加の行政評価の成果と課題を伺います。","respondent":"日下部企画部長","answer":"以前実施しました事務事業評価、これは平成２２年度に実施しました事務事業評価と同様に、行政自身が内部評価を行うということで実施をしたものです。","id":"exchange-055"},{"speaker":"井上委員","kind":"質問・要望","question":"議員は行政評価の機会は別にありますので、その辺はご配慮していただき、これからも検討ほしいと求めました。１年で公開の事務事業評価をやめてしまった理由を伺います。","respondent":"日下部企画部長","answer":"私ども予算の中で事務事業評価の実施ということでご提案をしていますけれども、こういったことができませんと、こういったことを痛感いたしました。","id":"exchange-056"},{"speaker":"井上委員","kind":"質問","question":"スクラップの数値化、見える化をどのように示していくのか、そのお考えを伺います。私は、区民目線で公開の場で歳出にメスを入れる事務事業評価を今後も継続していくべきだと思いますけれども、区の方針を伺います。","respondent":"日下部企画部長","answer":"今検討しておりますけれども、平成２４年度は、そういう形をとっていきたいと考えております。そういった取り組みについては、これについては今後議会のご意見等も伺いながら、あり方について検討していきたいと考えております。","id":"exchange-057"},{"speaker":"井上委員","kind":"質問・要望","question":"経常経費の主なものは人件費になるわけですけれども、人件費の削減というところだけではなくて、委託事業等にもメスを入れていくべきだと思います。政治的にならない数値化指標が必要だと考えていますけれども、それが大変重要なポイントと思いますが、そこについて見解を、示すよう求めました。","respondent":"日下部企画部長","answer":"もともと行政評価の目的の１つというのは、区民の皆さん方に対して説明責任をどうやって果たすかというところも１つのポイントになっておりますので。なかなか全体を１つの具体的な数値で比較できるような、今後できる限り工夫を図っていきたい、このように考えております。","id":"exchange-058"},{"speaker":"井上委員","kind":"質問","question":"では、次の質問は、養育困難家庭の支援体制について伺います。区の認識をしている課題についてお伺いいたします。","respondent":"金子子ども未来事業部長","answer":"５倍の依頼会員がおりますので、提供会員の獲得増強に努めていくということが１つと、子育ての困難さのニーズというのは高まっております。あくまでも二次的なサポートと考えておりますので、そういう意味では、今後検討すべきものと考えています。","id":"exchange-059"},{"speaker":"井上委員","kind":"提案","question":"前回にも私も提案をしました本特別委員会でも同様な指摘がありましたので、真摯に受けとめていただきたいと思っています。それから、支援内容とスタッフの人数、そして、支援を受けている件数、どういう事例で利用されているのか、説明を求めました。","respondent":"金子子ども未来事業部長","answer":"支援の件数ですけれども、平成２２年度が３０３件、平成２３年度が、１月末現在ですけれども、３２５件となっています。支援の内容ですが、あるいはシングルマザー等の要支援妊婦への妊娠期から産後の育児支援までと、これが非常に大きなニーズとなっている現状です。","id":"exchange-060"},{"speaker":"井上委員","kind":"質問","question":"２０１０年と２０１１年の実績を伺います。近年、待機児童対策解消のために各園で２名の定員確保がされているのか、危惧をしていますけれども、その辺の現状についてあわせて伺います。","respondent":"金子子ども未来事業部長","answer":"最大については、４カ月以上という方がいるのは、そういった事実はあります。兄弟がいる場合の同じ保育園で対応できているかということですけれども、原則として兄弟の在園は一緒にしようということで実施をしております。","id":"exchange-061"},{"speaker":"井上委員","kind":"質問・要望","question":"２０万円ほどの利用料金がかかりますけれども、そういった場合の減免制度があるのかどうか、お伺いをします。減免の考え方とあわせて見解を伺います。","respondent":"金子子ども未来事業部長","answer":"先ほどちょっと説明が不足したかもしれませんけれども、期間延長も対応しているということを一言添えておきます。就労支援とは別な入園要件ということですけれども、就労のほかにも、基本的には対応できているというふうに考えてあります。","id":"exchange-062"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほど養育家庭訪問という生活支援の制度を伺いましたけれども、また、７名しかそういったスタッフがいないということでした。制度創設を求めますけれども、区の見解を伺います。","respondent":"金子子ども未来事業部長","answer":"委員ご指摘の三重県で実施されている日常生活支援事業の家庭生活支援というのも、あくまでもひとり親家庭への支援制度であると承知しています。児童相談所とも連携して、検討、あるいは運用を改善してまいりたいと考えております。","id":"exchange-063"},{"speaker":"井上委員","kind":"提案","question":"第一義に親であるというところから、本当に支援を必要とされている方たちにとって行政ができるところというのをもうちょっと広げる枠組みはできないのかという提案なんですけれども、そのことについてもう一度見解をお伺いしますとの意見を述べました。","respondent":"金子子ども未来事業部長","answer":"先ほどの繰り返しになってしまいますが、現在の制度を運用している中で、さまざまな課題が出てきて、不十分であれば、それは新たな制度、あるいは運用の中でできるのか、そういったことを検討していきたいと考えています。","id":"exchange-064"},{"speaker":"井上委員","kind":"質問・要望","question":"続いて、子どもの貧困克服のための支援体制についてお伺いをいたします。扶助費の伸び率がどのように推移しているのかも伺います。","respondent":"木下健康福祉事業部長","answer":"国のほうで一定の方向を明確にするべきだと考えていますけれども、さまざまな視点からの検討がされており、既に具体化されているものもあります。","id":"exchange-065"},{"speaker":"井上委員","kind":"質問","question":"親の生活環境で著しく影響を受ける家庭の子どもたちへの支援体制が実際にどうなっているのか、お伺いをいたします。２００８年からスタートしたチャレンジ支援貸付事業もその１つと思われますが、品川区の利用件数の推移と品川区の評価もお伺いします。","respondent":"木下健康福祉事業部長","answer":"いわゆる貧困の連鎖を防いでいくという点で、同じスタート台になるべく立てるような支援ということはやはり必要なことだと認識をしております。","id":"exchange-066"},{"speaker":"井上委員","kind":"質問・要望","question":"私は子どもの権利条例東京市民フォーラムという研修会で、八王子市の職員から子どもの貧困克服のための子どもの健全育成支援という実践を伺いました。大変力を入れて、子どもの健全育成という視点でもう一歩進んだ取り組みを検討してほしいと求めましたけれども、区の見解を伺います。","respondent":"木下健康福祉事業部長","answer":"支援をしていくという、そういう経験なり実績なりを持った方々でないと、やはり効果的な事業展開は難しいのではないかと思っているところです。","id":"exchange-067","title":"議員研修会の内容と所要時間"},{"speaker":"井上委員","kind":"質問","question":"やっぱり教育委員会との連携も必要であると思っています。教育委員会のこういった貧困世帯の支援体制というものをどのように認識をし、そして支援体制が取り組まれているのか、説明を求めました。","respondent":"田村教育次長","answer":"経済的に困窮している世帯に対しては、就学援助の制度というのがございまして、それを活用しているです。福祉の部門で判断して、研究していくという状況を見据えていきたい、そのように思っております。","id":"exchange-068"},{"speaker":"井上委員","kind":"質問・要望","question":"貧困世帯の支援というのはなかなかどこまで手を入れていいのかということが難しいと悩んでいらっしゃるというのが全体的な今の現状だと思います。そこをどういうふうに切り込んで貧困の連鎖を断ち切るかということがこれから求められていますし、もう一度その辺のところを答弁お願いいたします。","respondent":"田村教育次長","answer":"先ほど来あった受験生のチャレンジ支援貸付事業についても同様ですが、福祉の部門の仕事という受けとめ方を教育委員会がするだけじゃなく、機会をとらえて、教育委員会のほうとしても保護者についてのＰＲをさらに進めてまいりたいと、そのように考えております。","id":"exchange-069"},{"speaker":"井上委員","kind":"質問・要望","question":"自分で選択ができない子どもたちにどれだけ大人の知恵を使ってその子たちの未来をつくっていけるかということが問われていますので、区全体で一丸となって取り組んでいただくことを要望して質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は予防接種について２点、検診（健診）業務について、最後に保育園の食物アレルギー対応についてお伺いしたいと思います。以上３点、お願いいたします。","respondent":"本保品川区保健所長","answer":"２つ目、それから日本小児科学会の見解についての区の考え方ですけれども、これについては私どもとしても支持いたします。この場合には、異なる実施主体で接種するということになりますので、認めてはおりません。","id":"exchange-071"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"私のところでも、１月のワクチン接種を統計したところ、同時接種を行ったのは大体３４％でした。現在の過密な乳児の接種スケジュールの改善のための品川区の施策、対策というものがありましたら、もう一度お示しほしいと求めました。","respondent":"本保品川区保健所長","answer":"同時接種をある程度現在の品川区の中で進める要素を考えるとすれば、その場において同時接種が多少拡大する余地があるかと思ってあります。そのようなことで同時接種の拡大を図りたいと考えています。","id":"exchange-072"},{"speaker":"鈴木（博）委員","kind":"質問","question":"この予防接種部会の決定に対する品川区のご見解をお聞かせください。今後、Ｂ型肝炎ワクチンの啓発についてのお考えもあわせて、示すよう求めました。","respondent":"本保品川区保健所長","answer":"最終的な決定ではまだなくて、まだ幾つかの課題も残っているというふうに、その前の検討会の中で指摘されているところです。啓発もその後で行っていきたいと考えているところです。","id":"exchange-073"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"次に効率的間違いのない検診（健診）についてお尋ねいたします。検診（健診）の業務の煩雑さ、ミスを回避するため、電子媒体への移行の要望も強いと聞きますが、区のご見解はいかがか尋ねました。","respondent":"木下健康福祉事業部長","answer":"がん検診についても、そういうような方法でやはり今後考えていくべきだろうということでありまして、それぞれの実施主体がデータベース化をする。","id":"exchange-074"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"今回新たに提出する品川区立保育園食物アレルギー疾患生活管理指導表の意義はどのようにとらえたらよろしいのでしょうか、お伺いしたいと思います。小児科医会、園医等への説明等はあったのでしょうか、お尋ねいたします。","respondent":"金子子ども未来事業部長","answer":"３つ目の医師会等々への説明についてのお尋ねですけれども、これのお知らせの文書というものを私ども作成しました。これを食物アレルギーのある園児の保護者を通して、その主治医の方のところに届いていく、そういったスタイルでご説明をしているという状況です。","id":"exchange-075"},{"speaker":"鈴木（博）委員","kind":"質問","question":"園医、食物アレルギーに対する対応を強化されることを希望いたしまして、私の質問を終わらせていただきます。ご清聴ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"高橋委員","kind":"質問・要望","question":"１番目に予算編成についてお尋ねします。６５歳以上と若年世代、そして、ここ数年の当初予算の伸び率とそれぞれの世代への歳出の額の伸び率等についてお尋ねいたします。","respondent":"榎本企画財政課長","answer":"大きく単年度で、建設費を入れると単年度で大きく上下しちゃいますので、建設費を除いたもので大まかにくくってみました。区のレベルですと、一般会計だけで比較しますと、子ども世代のほうに倍率でいくと７倍から８倍ぐらいの予算の支出の比重がかかっているです。","id":"exchange-077"},{"speaker":"高橋委員","kind":"質問・要望","question":"今後私も勉強すべき課題と考えており、今回はそのためにも、今、区のお話をお伺いして、勉強の材料にしていきたいと思います。そういったような今後の予算編成上の見通し、いろいろ難しい状況が前提とあると思うんですけれども、その辺についてお答えをほしいと求めました。","respondent":"榎本企画財政課長","answer":"この比率の考え方ですけれども、若年世代のほうにかなり厚くなってきているのは、平成１７年からは次世代育成支援対策推進行動計画ということで。","id":"exchange-078"},{"speaker":"高橋委員","kind":"質問","question":"かなり多くなるんですか、何という言い方をしたらいいんでしょうか、高齢者の方々の施策が果たして区の政策判断の中で十分なのか。若年の比率ではなくて、高齢者と若年の方への支出という比ですね、それについてどのようにお考えかということを最後に伺いたいと思います。","respondent":"榎本企画財政課長","answer":"平成１９年と比較すると１０％ほど、９.９％ほど増えているという形で、これが今後まだ数年間は両方とも伸びていくというような形での見込みです。","id":"exchange-079"},{"speaker":"高橋委員","kind":"質問・要望","question":"品川区の人口が約３５万人ですから、本当に今回心を痛め、そして心よりお見舞い申し上げます。教員のノウハウ、どのように蓄積し、継承をしていくと思われるか尋ねました。","respondent":"片田防災まちづくり事業部長、田村教育次長","answer":"実際に訓練の中での仮設テントの組み立てとか、あるいは仮設トイレの組み立てとか、いろんな訓練を行っております。その中で、ＡＥＤを使ったような訓練とか、あわせて行っているような実態です。 それと、教職員の参加が２８５名。随時、児童・生徒が参加していると、そのような状況を把握しています。","id":"exchange-080"},{"speaker":"高橋委員","kind":"質問・要望","question":"どうしても他教科を教える先生が出てきたり、私が伺った学校のところでの共通の悩みは、同じクラスの中で授業できない。これは学校側が要請をすれば、教育委員会としては協力を惜しまないというような寛大なるお考えがあるというふうに受け取ってよろしいか尋ねました。","respondent":"田村教育次長","answer":"高橋委員、中学校全校で平均８日間実施していますというので、基礎基本から発展学習まで各学校の対応で実際に実施しているという状況があります。各取り組み、教育委員会のほうも支援するのはやぶさかじゃないと、そのように理解しています。","id":"exchange-081"},{"speaker":"高橋委員","kind":"質問","question":"そして、論文指導など、どのような形で指導をしていただいているのでしょうか。その点についてお伺いいたします。","respondent":"田村教育次長","answer":"教育委員会も関連していますが、やはり面接試験、実際に面接のノウハウについて具体的にご指導いただくのは各校長、副校長が担当で実施しています。","id":"exchange-082"},{"speaker":"高橋委員","kind":"質問・要望","question":"この青少年にかかわるスポーツを取りまとめて、青少年育成課のほうで取りまとめていくということに関してはどのようにお考えでしょうか。青少年育成課が所管というような形で、少し考えてみただけでも複雑になっておりますけれども、その辺の整理についてどうお考えか尋ねました。","respondent":"金子子ども未来事業部長","answer":"この青少年育成に関しては、私ども青少年育成課が中心となって、他の事業部と連携をしながら実施していくというのを基本的な考えとしております。対象育成団体の拡大につきましては、これに準じる形の団体の可能性があれば、検討していきたいと考えております。","id":"exchange-083"},{"speaker":"高橋委員","kind":"質問","question":"その経緯についてお尋ねいたします。こちらの団体は、品川区、そして品川区外の団体も利用されているのか尋ねました。","respondent":"金子子ども未来事業部長","answer":"こちらの施設は、区内団体のほかに、区外団体もご利用をいただいていまして、大体３０％ほど区外団体の利用実績があります。ただ、受付に関しましては、区内団体を優先しておりまして、区内団体が２カ月前から、区外は１カ月前からというふうな調整をしています。","id":"exchange-084"},{"speaker":"高橋委員","kind":"質問・要望","question":"要望になってしまいますが、１つは、区外団体の方々も無料になっているという点、何らか検討をお願いします。これは要望にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"住宅の倒壊や火災による避難者の３割減と立てていますけれども、５年たった現在、減災の目標に対する到達がどこまで来ているのかを伺います。これまでの実績もあわせて伺います。","respondent":"片田防災まちづくり事業部長","answer":"その約７割のうちのさらに約７割が整備地域に、区としての認識についても、こういう状況について認識しているような状況です。平成２４年度に耐震改修促進計画の見直しを行う予定ですので、その中で具体的な耐震化の状況についても把握していきたいということで考えております。","id":"exchange-086"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成１９年から平成２７年までの９年間で、何棟の目標に対して現在何棟まで進んだのかという具体的な数字をお示しほしいと求めました。それと、耐震化と不燃化、進めていくためには何が課題と考えているか、この答弁が先ほどありませんでしたので、お願いします。","respondent":"片田防災まちづくり事業部長","answer":"あるいは建て替え等への支援等については、平成１８年から事業を進めてきました中で、それと昨年から着手しました除却への支援ということも含めて。","id":"exchange-087"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"わずか３％の実績という、３％という実績ということは本当に驚くべき到達だと思うんですけど、この到達に対して区としてどう考えているのか。その理由と、またこの耐震化について、耐震化を今後どのように進めていこうと考えているのかについても説明を求めました。","respondent":"片田防災まちづくり事業部長","answer":"個別訪問を行ってきたりしてまいりましたけれども、もう一つは、まちづくりを進めていくということが必要だと考えています。そういうところを区のほうとしても考えていかなきゃいけないと、このような状況で考えております。","id":"exchange-088"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その危険性をどうしたら取り除くことができるのか、その対策、区はそういう認識についてはどのように考えられているかについて伺いたいと思います。その上で、この立場で啓発の取り組みをどのようにしていくのかということについても具体的にお聞かせほしいと求めました。","respondent":"片田防災まちづくり事業部長","answer":"そういう中で、区としても情報啓発、あわせて、区として支援策を用意しているものに対して、きちっと区民に知らせていきたいと。やっぱり我がこととしての意識を持つことが一番大事だと考えますので、きちっと支援を進めていきたいと、このように考えている状況です。","id":"exchange-089"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"と同時に、区の助成制度も繰り返して知らせていただくということをしていただきたいと思うんですが、いかがでしょうか。町会ごとはもちろん、番地ごとぐらいに説明会をしていただきたいと思うんですけれども、いかがか尋ねました。","respondent":"片田防災まちづくり事業部長","answer":"区として、こういうメニューもありますよというような対応を行ってきたところですので、当然繰り返しの対応は検討していきたいと考えています。これからまた、改めて平成２４年度に全戸配布をする予定の中にも、当然それを入れ込んでいくというような状況で考えております。","id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは強く求めておきたいと思います。耐震診断の体制整備、そして耐震化への助成増額ということは求めてきましたけれども、これも改めて求めたいと思います。","respondent":"片田防災まちづくり事業部長","answer":"生命を守るという部分で、区としてもシェルター等を含めて支援をこれまでも考えてきた、対応してきたところです。必要な対策について私どものほうとしても不燃化を進めているというような状況です。","id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"代表質問でも我が党が求めましたけれども、墨田区で始める耐火ボードへの助成、これをぜひとも取り組んでいただきたい。そういう中で、区民の生命と財産を守る対策、ぜひとも取り組んでいただくことを求めて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"中塚委員","kind":"質問・要望","question":"これまでの説明では、一次審査で不承諾者は５００名、その後二次募集が終了しましたが、その結果を伺います。その不承諾者の親の状況について、常勤、パート、自営、求職および内定、そのほかについて、概要で結構ですので、その割合をお伺いしたいと思います。","respondent":"金子子ども未来事業部長","answer":"年齢の割合なんですけれども、０から２歳児が８４％、３歳以上が１６％という割合になってあります。自営の方が１６％、内定の方が２０％、その他が４％となっています。","id":"exchange-093"},{"speaker":"中塚委員","kind":"質問・要望","question":"４００名を超える子どもたちがこういう状況で、今年でついに５年連続、この事態をどう考えているのでしょうか。やはり区立認可保育園の増設、ここを待機児対策に位置づける必要があると思いますが、いかがか尋ねました。","respondent":"金子子ども未来事業部長","answer":"再三再四ご説明申し上げました、平成２２年度、平成２３年度の２年度で約１,１００人の受け入れ枠の拡大を実施してまいりました。今後とも待機児童対策を積極的に実施してまいりますが、平成２４年度は、さらに人口動向の詳細な調査を行ってまいります。","id":"exchange-094"},{"speaker":"中塚委員","kind":"質問・要望","question":"待機児解消に向け、必要な整備を、区立認可保育園で増設を進めていく、改めて求めますが、いかがでしょうか。ならば今年入れなかった４７８人、その後の後追い調査をぜひ実施すべきだと思いますが、いかがか尋ねました。","respondent":"金子子ども未来事業部長","answer":"種々の総合的な施策で対応するということでこの間やってきましたけれども、今後ともこの考えは堅持していきたいと考えています。平成２４年度ですね、詳細な調査を実施しますので、また対策を考えていきたいと考えています。","id":"exchange-095"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区は増設計画を掲げておりますが、いつまでにどれぐらいを考えているのか、その考えを伺いたいと思います。昨年９月の入所調整会議にかけられた５９１人の中で、今年の３月までに入所できた方の合計数、年齢別の入所者数を伺います。","respondent":"木下健康福祉事業部長","answer":"特別養護老人ホームの関係ですけれども、先週金曜日に特別養護老人ホームの入所調整会議を実施いたしました。このような内訳になっているところです。","id":"exchange-096"},{"speaker":"中塚委員","kind":"質問","question":"伺いたいことは、この９割が入所できない、現在の入所しづらい状況を改善したいという考えはあるのでしょうか。あわせて、将来の高齢者人口の増加に伴う必要な特別養護老人ホームのベッド数の想定数、将来の想定についても状況とお考えを伺いたいと思います。","respondent":"木下健康福祉事業部長","answer":"そういうことを踏まえて柔軟に対応できるということでありますので、いわゆる計画で具体化するよりも、適宜条件が整えば整備をしてまいりますと。このような考え方で今後とも進めていきたいと考えています。","id":"exchange-097"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、この間の改善状況を伺っているのではなく、９割の人が入所ができない。再三指摘するように、国の負担割合の引き上げ、区の一般財源の投入の増加、それこそ対応すべきではないか尋ねました。","respondent":"木下健康福祉事業部長","answer":"そういうことも含めた結果だというふうに受けとめるべきだと考えています。同時に、そういうことも含めてトータルに考えるということと、そういうような総合的な判断が必要だろうと思います。","id":"exchange-098"},{"speaker":"中塚委員","kind":"質問","question":"その実態をどう考えているのか、伺いたいと思います。入所しづらい状況を踏まえた特別養護老人ホームの増設へと切り替えるべきだと思いますが、いかがか尋ねました。","respondent":"木下健康福祉事業部長","answer":"私どもとしましては、入所調整基準もそのようなことを具体的にメッセージとして発信できるような基準になっているということであります。介護期間などが点数化されているというわけでありまして、そういう意味では、客観的な指標になっていると思っているところです。","id":"exchange-099"},{"speaker":"中塚委員","kind":"質問・要望","question":"ご主人が急死をし、やむを得ず老人保健施設に入れたけれども、それが遅らせたら、じゃあ、どうしたらよいのかと話しておりました。こうした実態に心を寄せて、特別養護老人ホームの増設を、あわせて冒頭の認可保育園の増設を強く求めて総括質疑を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"大西委員","kind":"意見","question":"この３万人の自殺者に対して区はどのようにお考えになっているか。都市ごと等の傾向、そういうものがあるのかという点についてお尋ねをいたしますとの意見を述べました。","respondent":"本保品川区保健所長","answer":"自殺対策についてのご質問です。この日本の自殺の実態自体が他の先進国の中では、公衆衛生的な対策、健康施策としての進め方を強化していく必要があるかと考えております。","id":"exchange-101"},{"speaker":"大西委員","kind":"質問","question":"私が調べたところによると、東京都と全国の傾向が似ているように感じております。バブルが崩壊したときには、それほどの自殺者は出ていないという認識を持っていますけれども、その点に間違いはないか尋ねました。","respondent":"本保品川区保健所長","answer":"特に全国で非常に上昇しました平成１０年におきまして、品川区が前年に比べまして上昇したかというと、そうではないという現状はあります。","id":"exchange-102"},{"speaker":"大西委員","kind":"質問","question":"そういたしますと、経済的理由における自殺者の数は少ない。そして、先ほど言われていたイタリア等の施策と品川区の施策の違いというのはどこか明確なところはありますか尋ねました。","respondent":"本保品川区保健所長","answer":"やはり社会経済的な問題というのは１７％で、数自体としては見かけ上は少ないと考えられますが、やはり大きな要因を持っているかと思います。一番大きい精神疾患が２６％ということで、英国と比べてどうかという内容でお答えいたしますと、４０％ぐらいしか受診されていない。","id":"exchange-103"},{"speaker":"大西委員","kind":"質問","question":"精神疾患と病気を苦にしてというものでおよそ４０％程度あろうかと思いますが、この精神疾患の自殺者の推移というのがわかりましたら、説明を求めました。","respondent":"本保品川区保健所長","answer":"この期間に講演会などを行いまして、多いときは４００名、少ないときでも１００名台の参加の方が計上されているところです。ただ、大きな自殺者の推移について影響を及ぼしたかというと、必ずしもそうではないという結果になっているかと思います。","id":"exchange-104"},{"speaker":"大西委員","kind":"質問","question":"そうですか。それとも病気というものに対する、将来に対する悲観なのかという点では、どちらのほうのことが大きいんか尋ねました。","respondent":"本保品川区保健所長","answer":"高脂血症、その状況をもって、うつ的な状況になるというご本人の心のありようの変遷というのが自殺につながっている可能性はあるかと考えています。","id":"exchange-105"},{"speaker":"大西委員","kind":"質問","question":"その中でやっぱり災害の弱者の方々をどう品川区は行政としてできる部分があるのかを少しお尋ねしたいと思いますけど、大きな違いがあったと思います。品川区はもし首都直下型、どういう災害が一番大きな被害を品川区にもたらすのかという点では、どのようにとらえておられますか尋ねました。","respondent":"片田防災まちづくり事業部長","answer":"今回の東日本大震災のほうでは、津波ということで、津波の被害もやはり９割ぐらいの方が亡くなっているという状況です。の火災の延焼による死者という、あるいは負傷者、そういうところを懸念しているような状況です。","id":"exchange-106","title":"議員研修会の内容と所要時間"},{"speaker":"大西委員","kind":"質問","question":"それでドアが開けられない状態になっちゃったというような状態。そういうときに、そういった方々に特別に倒壊や、また火災における災害から逃れるための何らかの方策の支援というのはなされておりますか尋ねました。","respondent":"片田防災まちづくり事業部長","answer":"倒壊への対応という状況の中では、シェルターの設置支援、そういう災害弱者に対する取付け補助という形でこれまでも支援を行ってまいりました。","id":"exchange-107"},{"speaker":"大西委員","kind":"質問","question":"そうすると、今、品川区の中には大体人から支援を受けないと避難することができない方々、まあ、介護認定の少し重い方々だとか、いろんな形の方々がおられると思うんですけれども、区のほうとしては人数自体の掌握はなされていますか尋ねました。","respondent":"片田防災まちづくり事業部長","answer":"それ以外に、障害者ということで、視覚障害者等での等級を持たれている方等々含めて、３,３４７名と。愛の手帳の保持者ということでの１から４度というような方では、１,４９５名ほどの状況を把握しているような状況です。","id":"exchange-108"},{"speaker":"大西委員","kind":"質問","question":"町会と言われるお話がありましたけれども、昨今町会も随分私の見るところ、高齢化が進んでいるように感じるんですよね。そういう方々でもっていざ地震のときに本当に１人の人を１人の人が担ぎ出せるとか、その辺に関してはいかがか尋ねました。","respondent":"片田防災まちづくり事業部長","answer":"地域の防災訓練、あるいは避難誘導ワークショップを通して、具体的に日ごろから災害があった場合にどういう行動をとろうかと。そういう地域の力を活用して進めているというような状況ですので、確かに町会の方で、日ごろのからの活用していくといったような状況です。","id":"exchange-109"},{"speaker":"大西委員","kind":"質問","question":"ご意見というよりも、災害が起こったときはどうすればいいのかというのがよくわからないんだけどということをいただくんですね。いざ起こったときには皆様はこのような形で活動してくださいということがしっかりと告知されているのかどうなのかについてはいかがか尋ねました。","respondent":"片田防災まちづくり事業部長","answer":"その登録制度の中で、地域の町会等にそういう名簿についてお示ししながら、必要な対応をとっていただくような対応を考えているというような状況です。３町会・自治会で逆に個別支援プランという形の取り組みを行ってきてありますので、考え方、このように考えている状況です。","id":"exchange-110"},{"speaker":"大西委員","kind":"質問・要望","question":"まあ、皆さん地震保険入っていると思うんですけど、その点に関してはどういうふうかご存じであればということをお尋ねしたいんですが。これ、安心じゃないんだということも告知しなきゃいけないんじゃないかと思うんですけど、いかがか尋ねました。","respondent":"片田防災まちづくり事業部長","answer":"ちょっと市場のことはわかりかねますけれども、基本的には皆さん方は火災保険に入っている方のほうが恐らく多いんじゃないのかなと。ローンを活用したりというような部分の中で、それは個人のご判断になりますので、そのように私どものほうとしても受けとめているような状況です。","id":"exchange-111"},{"speaker":"大西委員","kind":"質問","question":"地震を起因として起こった場合の火災、それによって失われたものについては、地震保険では担保されないということでいいんでしょうか。要は、皆さんのほうに火災保険だけでは担保されない、その辺はもしおわかりになればで結構ですが、ちょっと。","respondent":"片田防災まちづくり事業部長","answer":"先ほどの答弁の中でちょっと１つ違いがありましたので、ご報告しますと、やはり地震保険だけでは入れない。地震によって倒壊したということであれば、当然地震保険に入っていれば、その適用を受けられるということで考えております。","id":"exchange-112"},{"speaker":"大西委員","kind":"質問","question":"私の総括質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-113"},{"speaker":"須藤委員","kind":"質問・要望","question":"昨年秋に我が会派が区民の声としてまとめた、区側に要望した政策提言についても配慮された各予算案として評価をいたします。できる限りの努力をさらに要望するとともに、区民が真に必要とする施策の展開を期待し、品川区議会自民党の意見表明といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"武内委員","kind":"提案","question":"福祉避難所機能の充実など、これまで我が会派が提案、要望してきた施策が数多く反映されたことは高く評価します。さらに民間住宅ストックを活用した住宅困窮者対策などの提案、要望を真摯に受けとめ、区議会公明党の意見表明といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-115"},{"speaker":"阿部委員","kind":"提案","question":"今後の事務事業評価においても、真に行政で行うべき事業のさらなる精査、長期にわたる委託事業のあり方の検討などに取り組むことを求めます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-116"},{"speaker":"西本委員","kind":"質問・要望","question":"積極的に推進し、区内経済が元気になるよう、一層の促進を要望いたします。それと同時に、いつまでも元気で品川区で過ごせる環境整備もさらに促進していただきたいと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"},{"speaker":"飯沼委員","kind":"質問・要望","question":"精神保健の充実が求められながら、保健師の不足も続いています。基金の新たなため込みはやめ、区民のために使うことを求め、意見表明を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-118"},{"speaker":"吉田委員","kind":"質問・要望","question":"高齢期の住まいと安全安心対策、待機児童の３点についても重要課題とし、より一層全力で向かっていくことを求めます。積極的に取り組んでいっていただき、これまで以上に未来につなぐ住みよいまち、品川づくりを推進していくことを要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-119"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/918450?Template=document&Id=978#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":110345,"voices":255}}]);
